compare_order!(compare_search_screens_compare_results_by_scouted_assists, search_screens_compare_results_by_scouted_assists, IDX_SEARCH_SCREENS_COMPARE_RESULTS_BY_SCOUTED_ASSISTS);
compare_order!(compare_search_screens_compare_results_by_scouted_goals_conceded, search_screens_compare_results_by_scouted_goals_conceded, IDX_SEARCH_SCREENS_COMPARE_RESULTS_BY_SCOUTED_GOALS_CONCEDED);
compare_order!(compare_search_screens_compare_results_by_scouted_average_rating, search_screens_compare_results_by_scouted_average_rating, IDX_SEARCH_SCREENS_COMPARE_RESULTS_BY_SCOUTED_AVERAGE_RATING);
compare_order!(compare_search_screens_compare_results_by_last_scouted_match, search_screens_compare_results_by_last_scouted_match, IDX_SEARCH_SCREENS_COMPARE_RESULTS_BY_LAST_SCOUTED_MATCH);
compare_order!(compare_search_screens_compare_results_by_ability_stars, search_screens_compare_results_by_ability_stars, IDX_SEARCH_SCREENS_COMPARE_RESULTS_BY_ABILITY_STARS);
