pub(crate) unsafe extern "C" fn compare_open_manager_stats_screen() {
    // simplification: opening a screen does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn()>(IDX_OPEN_MANAGER_STATS_SCREEN)()
}

