// ---------- batch 318: the award finders of the award screens (award_screens.cpp) ----------

/// The award finders' common body: the manager's table of 30 award lists (the pointer at +8); in each non-null list
/// (+4 the item array, +8 i16 the count, read once) the first award whose dword at `at` equals `key` is returned;
/// 0 when none.
unsafe fn award_manager_find_by(manager: usize, key: u32, at: usize) -> usize {
    let lists = read_usize(manager + 8);
    for k in 0..0x1e {
        let list = read_usize(lists + k * 4);
        if list == 0 {
            continue;
        }
        let count = read_i16(list + 8) as i32;
        let items = read_usize(list + 4);
        for i in 0..count.max(0) as usize {
            if read_u32(read_usize(items + i * 4) + at) == key {
                return read_usize(read_usize(read_usize(read_usize(manager + 8) + k * 4) + 4) + i * 4);
            }
        }
    }
    0
}

/// The award of a staff competition: the first award, in the 30 lists of the manager, whose staff competition
/// (+5) is `comp`; 0 when none (`award_manager_find_by`).
/// Original: `AWARD_MANAGER::find_award_by_staff_comp` (0x414a60, award_screens.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn award_manager_find_award_by_staff_comp(manager: usize, comp: u32) -> usize {
    award_manager_find_by(manager, comp, 5)
}

/// The award of a club competition: the first award whose club competition (+9) is `comp`; 0 when none.
/// Original: `AWARD_MANAGER::find_award_by_club_comp` (0x414ac0, award_screens.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn award_manager_find_award_by_club_comp(manager: usize, comp: u32) -> usize {
    award_manager_find_by(manager, comp, 9)
}

compare_value!(compare_award_manager_find_award_by_staff_comp, award_manager_find_award_by_staff_comp, IDX_AWARD_MANAGER_FIND_AWARD_BY_STAFF_COMP, (comp: u32) -> usize);
compare_value!(compare_award_manager_find_award_by_club_comp, award_manager_find_award_by_club_comp, IDX_AWARD_MANAGER_FIND_AWARD_BY_CLUB_COMP, (comp: u32) -> usize);

// ---------- batch 318: the board request screen ("Meet with Board") (belgium_rules.cpp) ----------

/// The screen's build and input functions (passed to `ScreenManager::open_screen`).
pub(crate) const FN_BOARD_REQUEST_SCREEN_DRAW: usize = 0x4253f0;
pub(crate) const FN_BOARD_REQUEST_SCREEN_HANDLE_EVENT: usize = 0x4257f0;
/// The texts "Meet with Board", "  Specify the details of requests from board:", "Cancel" and "Confirm".
const BOARD_REQUEST_TITLE: usize = 0x98a1d8;
const BOARD_REQUEST_INTRO: usize = 0x98a1a8;
const BOARD_REQUEST_CANCEL: usize = 0x98a1a0;
const BOARD_REQUEST_CONFIRM: usize = 0x98a198;
/// u32: the game is a network game.
const BOARD_REQUEST_NETWORK_GAME: usize = 0xb77c84;
/// The item ids of the screen: a request (its value is the request), Cancel and Confirm.
const BOARD_REQUEST_ITEM_REQUEST: u16 = 0x64;
const BOARD_REQUEST_ITEM_CANCEL: u16 = 8;
const BOARD_REQUEST_ITEM_CONFIRM: u16 = 9;

/// Opens the board request screen of a club (`club` points to the club's id): `ScreenManager::open_screen` with
/// `FN_BOARD_REQUEST_SCREEN_DRAW` and `FN_BOARD_REQUEST_SCREEN_HANDLE_EVENT`, single instance, the empty 0x5a8f60 as
/// the leave function; when it opens, parameter 0 = the club id, 1 (the chosen request) and 2 (its button) = 0.
/// Original: `board_request_screen_open` (0x425390, belgium_rules.cpp, cdecl).
pub(crate) unsafe extern "C" fn board_request_screen_open(club: usize) {
    if exe::screenmanager_open_screen(G_SCREEN_MANAGER, FN_BOARD_REQUEST_SCREEN_DRAW, FN_BOARD_REQUEST_SCREEN_HANDLE_EVENT, 1, FN_SHARED_NOOP_RET0_5A8F60, 0) == 0 {
        return;
    }
    covered!("tel30_4 board request screen opened");
    exe::screenmanager_set_screen_param(G_SCREEN_MANAGER, 0, read_usize(club), 0);
    exe::screenmanager_set_screen_param(G_SCREEN_MANAGER, 1, 0usize, 0);
    exe::screenmanager_set_screen_param(G_SCREEN_MANAGER, 2, 0usize, 0);
}

/// The club of the screen: parameter 0 is its id in the club table.
unsafe fn board_request_club() -> usize {
    read_usize(G_CLUB_TABLE).wrapping_add(get_screen_param(0).wrapping_mul(club::SIZE))
}

/// Builds the board request screen of the club in parameter 0 (nothing without a chairman at +0xcf).
///
/// Parameter 1 is the chosen request; parameter 2 is read too (unused). The boardroom picture
/// (`background_set_section_picture(7, 0)`); the title is the chairman's name (`database_format_staff_name`, style 1)
/// in the club's kit colours (kit 1, background then foreground); the subtitle "Meet with Board". An area
/// (0x6e, 0x8c)-(0x30c, 0x221) with the 7 column bytes [2, 0x14, 2, 0xa, 2, 4, 3] and 0x195 / font_get_height(3)
/// rows holds the wrapped introduction ("  Specify the details of requests from board:", font 3, pale grey) from row 0;
/// a second area over the same rectangle (2 columns [2, 0x11]) takes, from two rows below the text, one button per
/// request 1 to 5 (`get_board_request_option_text` on the manager manager, 2000 bytes): an unavailable one
/// (`is_board_request_available`) grey with no id, an available one pale grey (yellow when chosen) with id 0x64 and
/// the request as value; the first button's index goes to parameter 2. Then the menu bar (`menubar_build(4, 0)`) and
/// an area (0x64, 0x22b)-(0x316, 0x24e) with the columns [3, 1], one row and the club's kit background: "Cancel"
/// (id 8) and "Confirm" (id 9, a plain text with no request chosen). The colour words are passed zero-extended (the
/// original pushes registers with only their low half loaded).
/// Original: `board_request_screen_draw` (0x4253f0, belgium_rules.cpp, cdecl).
pub(crate) unsafe extern "C" fn board_request_screen_draw() {
    let mut text = [0usize; 2];
    exe::new_text(text.as_mut_ptr(), 0usize);
    let mut row: i32 = 0;
    let club = board_request_club();
    let chairman = read_usize(club + 0xcf);
    if chairman != 0 {
        covered!("tel30_4 board request screen built");
        let chosen = get_screen_param(1) as u8;
        get_screen_param(2);
        background_set_section_picture(7, 0);
        let (mut foreground, mut background) = (0u32, 0u32);
        exe::database_get_club_kit_colours(club, 1, &mut foreground, &mut background);
        let mut name = [0u8; 500];
        exe::database_format_staff_name(chairman, name.as_mut_ptr() as usize, 0x1f4, 1);
        exe::screenmanager_add_screen_title(G_SCREEN_MANAGER, background & 0xffff, foreground & 0xffff, name.as_ptr() as usize);
        let langlib: unsafe extern "C" fn(usize, usize, ...) -> usize = core::mem::transmute(FN_LANGLIB_SPRINTF);
        langlib(JOB_TEXT, BOARD_REQUEST_TITLE);
        exe::screenmanager_add_screen_subtitle(G_SCREEN_MANAGER, JOB_TEXT, 1);
        let rows = (0x195 / exe::font_get_height(3)) as u8 as u32;
        let columns: [u8; 7] = [2, 0x14, 2, 0xa, 2, 4, 3];
        let buttons: [u8; 2] = [2, 0x11];
        let footer: [u8; 2] = [3, 1];
        let intro = tel26_add_area(current_human_display(), [0x6e, 0x8c, 0x30c, 0x221, 7, columns.as_ptr() as u32, rows, 0, 2, 0, 0xffff_ffff]);
        langlib(JOB_TEXT, BOARD_REQUEST_INTRO);
        exe::text_set_string(text.as_mut_ptr() as usize, JOB_TEXT as *const u8);
        let draw: unsafe extern "thiscall" fn(usize, u32, i32, i32, *mut i32, u32, u32, u32, u32) -> i32 = core::mem::transmute(0x4aeaf0usize);
        draw(text.as_mut_ptr() as usize, intro, 0x6e, 0x30c, &mut row, 3, read_u16(G_GUI_COLOUR_PALE_GREY) as u32, 0, 0);
        let list = tel26_add_area(current_human_display(), [0x6e, 0x8c, 0x30c, 0x221, 2, buttons.as_ptr() as u32, rows, 0, 1, 0, 0xffff_ffff]);
        row += 2;
        let mm = read_usize(G_MANAGER_MANAGER);
        let option_text: unsafe extern "thiscall" fn(usize, u32, usize, u32) = core::mem::transmute(0x6a8770usize);
        let available: unsafe extern "thiscall" fn(usize, usize, u32) -> u8 = core::mem::transmute(0x6ae180usize);
        let mut request: u8 = 1;
        loop {
            option_text(mm, request as u32, JOB_TEXT, 0x7d0);
            if request == 6 {
                break;
            }
            let (colour, id) = if available(mm, club, request as u32) == 0 {
                (read_u16(G_GUI_COLOUR_GREY) as u32, 0)
            } else if chosen == request {
                (read_u16(G_GUI_COLOUR_YELLOW) as u32, BOARD_REQUEST_ITEM_REQUEST as u32)
            } else {
                (read_u16(G_GUI_COLOUR_PALE_GREY) as u32, BOARD_REQUEST_ITEM_REQUEST as u32)
            };
            let button = tel26_area_button([list, 1, row as u32, 1, 0, 1, 3, colour, JOB_TEXT as u32, id, request as i8 as i32 as u32]);
            if request == 1 {
                set_screen_param(2, button as i16 as i32 as usize);
            }
            row += 1;
            request += 1;
            if request > 6 {
                break;
            }
        }
        exe::menubar_build(4, 0);
        let bar = tel26_add_area(current_human_display(), [0x64, 0x22b, 0x316, 0x24e, 2, footer.as_ptr() as u32, 1, 0, 1, background, 0xffff_ffff]);
        langlib(JOB_TEXT, BOARD_REQUEST_CANCEL);
        let (grey, pale) = (read_u16(G_GUI_COLOUR_GREY) as u32, read_u16(G_GUI_COLOUR_PALE_GREY) as u32);
        tel26_area_button([bar, 0, 0, 0x30, grey, 0xc, 3, pale, JOB_TEXT as u32, BOARD_REQUEST_ITEM_CANCEL as u32, 0]);
        langlib(JOB_TEXT, BOARD_REQUEST_CONFIRM);
        if chosen == 0 {
            tel26_area_text([bar, 1, 0, 0x30, grey, 0x2c, 3, pale, JOB_TEXT as u32]);
        } else {
            tel26_area_button([bar, 1, 0, 0x30, grey, 0xc, 3, pale, JOB_TEXT as u32, BOARD_REQUEST_ITEM_CONFIRM as u32, 0]);
        }
    }
    exe::drop_text(text.as_mut_ptr());
}

/// The id of an item of the board request screen (`display_item_id`; none, -1, gives the current command id).
unsafe fn board_request_item_id(item: i16) -> u16 {
    tel26_item_id(item)
}

/// Answers a click on the board request screen.
///
/// Parameters 0 (the club), 1 (the chosen request) and 2 are read. In a network game the pending command argument
/// is cleared and -9 returned. A request button (id 0x64) puts its value (the request) in parameter 1 and returns -11
/// (redraw); Confirm (id 9) with a request chosen passes it to `MANAGER_MANAGER::handle_board_request(club,
/// request)`, and Confirm or Cancel (id 8) return -9 (back); any other item goes to the menu bar
/// (`menubar_handle_command`, then `menubar_handle_object_link` when it returns 0).
/// Original: `board_request_screen_handle_event` (0x4257f0, belgium_rules.cpp, cdecl).
pub(crate) unsafe extern "C" fn board_request_screen_handle_event(item: u32) -> i32 {
    let club = board_request_club();
    let chosen = get_screen_param(1);
    get_screen_param(2);
    if read_u32(BOARD_REQUEST_NETWORK_GAME) != 0 {
        write_u32(G_PENDING_COMMAND_ARG, 0);
        return -9;
    }
    let raw = item;
    let item = item as i16;
    let id = board_request_item_id(item);
    if id == BOARD_REQUEST_ITEM_REQUEST {
        set_screen_param(1, tel26_item_value(item) as usize);
        return -11;
    }
    if id == BOARD_REQUEST_ITEM_CONFIRM {
        if chosen != 0 {
            covered!("tel30_4 board request confirmed");
            let handle: unsafe extern "thiscall" fn(usize, usize, u32) = core::mem::transmute(0x6a8810usize);
            handle(read_usize(G_MANAGER_MANAGER), club, chosen as u32);
        }
        return -9;
    }
    if id == BOARD_REQUEST_ITEM_CANCEL {
        return -9;
    }
    let r = exe::menubar_handle_command(raw);
    if r != 0 {
        return r;
    }
    exe::menubar_handle_object_link(raw)
}

// simplification: opens a screen (the history allocates a node): it does not run twice. Original only; the plan: the
// new current screen is this one, with the club in parameter 0 and no request chosen.
/// Comparer for `board_request_screen_open`.
pub(crate) unsafe extern "C" fn compare_board_request_screen_open(club: usize) {
    original_fn::<unsafe extern "C" fn(usize)>(IDX_BOARD_REQUEST_SCREEN_OPEN)(club);
    let node = current_screen_node(G_SCREEN_MANAGER);
    if node == 0 || read_usize(node) != FN_BOARD_REQUEST_SCREEN_DRAW {
        return;
    }
    let (p0, p1, p2) = (get_screen_param(0), get_screen_param(1), get_screen_param(2));
    SCOREBOARD.record(p0 == read_usize(club) && p1 == 0 && p2 == 0, || format!("board_request_screen_open (Meet with Board): params {:#x} {} {}", p0, p1, p2));
}

/// Comparer for `board_request_screen_draw`: through the display list (`compare_by_display_list_with`), plus the
/// screen's picture path (the boardroom picture rolls the generator, which the list comparer restores).
pub(crate) unsafe extern "C" fn compare_board_request_screen_draw() {
    let o = original_fn::<unsafe extern "C" fn()>(IDX_BOARD_REQUEST_SCREEN_DRAW);
    let mut extra = Vec::new();
    let node = current_screen_node(G_SCREEN_MANAGER);
    if node != 0 {
        extra.push((node + screen_node_fields::PICTURE, screen_node_fields::PICTURE_SIZE));
    }
    compare_by_display_list_with("board_request_screen_draw (Meet with Board)", &extra, || o(), || board_request_screen_draw());
}

/// Comparer for `board_request_screen_handle_event`: a request button and Cancel side by side over the parameters
/// and the answer (`compare_resposta`); Confirm (the board's answer), the menu bar and a network game the original
/// only.
pub(crate) unsafe extern "C" fn compare_board_request_screen_handle_event(item: u32) -> i32 {
    let id = board_request_item_id(item as i16);
    let stays = read_u32(BOARD_REQUEST_NETWORK_GAME) == 0 && (id == BOARD_REQUEST_ITEM_REQUEST || id == BOARD_REQUEST_ITEM_CANCEL);
    compare_resposta("board_request_screen_handle_event (Meet with Board)", item, original_fn(IDX_BOARD_REQUEST_SCREEN_HANDLE_EVENT), board_request_screen_handle_event, !stays)
}

// ---------- batch 318: the squad list comparators (1) (club_screens.cpp) ----------

/// The sort context of the squad list comparators, written by `build_filtered_sorted_squad_list` (0x4841d0) before
/// its qsort: the club whose list it is.
pub(crate) const PLAYER_SORT_CLUB: usize = 0xad9db0;
/// u8: the attribute of the "attribute" column.
pub(crate) const PLAYER_SORT_ATTRIBUTE: usize = 0xad9db4;
/// u8: the field of the "statistic" column (`PlayerStats::get_stat`).
pub(crate) const PLAYER_SORT_STAT_FIELD: usize = 0xad9db5;
/// u8: the name style passed to `database_format_staff_name`.
pub(crate) const PLAYER_SORT_NAME_STYLE: usize = 0xadab33;
/// u32: the team index passed to `Tactics::find_selection_slot` (1 = reserves).
pub(crate) const PLAYER_SORT_RESERVES: usize = 0xadab34;
/// usize: the team sheet of a club the human does not control (0 = none).
pub(crate) const PLAYER_SORT_TEAM_SHEET: usize = 0xadab38;
/// usize: the club or its linked side, whose contracts and squad numbers the columns show.
pub(crate) const PLAYER_SORT_SIDE: usize = 0xadab3c;
/// usize: the fixture of the status column.
pub(crate) const PLAYER_SORT_FIXTURE: usize = 0xadab44;
/// u8: the category of the "statistic" column (`PlayerStats::get_stat`).
pub(crate) const PLAYER_SORT_STAT_CATEGORY: usize = 0xadab4a;
/// usize: the viewer whose knowledge hides attributes (`staff_is_player_attribute_visible`).
pub(crate) const PLAYER_SORT_VIEWER: usize = 0xadadf0;
/// `G_SQUAD_MANAGER` (0xdd7ef0), the squad number owner.
const PLAYER_SORT_SQUAD_MANAGER: usize = 0xdd7ef0;

/// The tie-break of every squad list comparator: a null first entry sorts last (1), a null second one first (-1);
/// otherwise the two names, written in the list's name style (`PLAYER_SORT_NAME_STYLE`) into 200-byte buffers by
/// `database_format_staff_name`, compared with `utils_string_compare(first, second, 1, 0)`.
pub(crate) unsafe fn player_sort_by_name(a: usize, b: usize) -> i32 {
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    let style = read_u8(PLAYER_SORT_NAME_STYLE) as u32;
    let (mut x, mut y) = ([0u8; 200], [0u8; 200]);
    exe::database_format_staff_name(a, x.as_mut_ptr() as usize, 200, style);
    exe::database_format_staff_name(b, y.as_mut_ptr() as usize, 200, style);
    exe::utils_string_compare(x.as_ptr(), y.as_ptr(), 1, 0)
}

/// The two entries of a qsort call (pointers to staff pointers).
unsafe fn player_sort_pair(a: *const usize, b: *const usize) -> (usize, usize) {
    (*a, *b)
}

/// Squad list order "selection": the players by their slot in the team selection, the unselected last.
///
/// A null first entry sorts last (1), a null second first (-1). When the human controls the list's club
/// (`human_manager_current_controls_club(club, 0, 1)`), each player's slot is `Tactics::find_selection_slot(club,
/// player, PLAYER_SORT_RESERVES)`; otherwise, with no team sheet (`PLAYER_SORT_TEAM_SHEET` 0) the result is 1, and
/// with one the slot is the last of its 20 entries (0x49 bytes apart, from +0x190 of the sheet's first or second half:
/// the second, 0x625 bytes on, when the club's id matches the sheet's first dword) holding the player's id. An
/// unselected first player (0xff) sorts last (1), then an unselected second one first (-1); different slots give
/// the signed byte difference first - second; equal slots go to the names (`player_sort_by_name`).
/// Original: `compare_players_by_selection_slot_then_name` (0x485470, club_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_players_by_selection_slot_then_name(pa: *const usize, pb: *const usize) -> i32 {
    let (a, b) = player_sort_pair(pa, pb);
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    let club = read_usize(PLAYER_SORT_CLUB);
    let (mut sa, mut sb) = (0xffu8, 0xffu8);
    if exe::human_manager_current_controls_club(club, 0, 1) != 0 {
        covered!("tel30_5 selection slot of the human's club");
        let reserves = read_u32(PLAYER_SORT_RESERVES);
        sa = exe::tactics_find_selection_slot(read_usize(G_TACTICS), club, a, reserves);
        sb = exe::tactics_find_selection_slot(read_usize(G_TACTICS), club, b, reserves);
    } else {
        let sheet = read_usize(PLAYER_SORT_TEAM_SHEET);
        if sheet == 0 {
            return 1;
        }
        let (ida, idb) = (read_u32(a), read_u32(b));
        let half = (read_u32(club) == read_u32(sheet)) as usize;
        let mut entry = sheet + half * 0x625 + 0x190;
        for k in 0u8..0x14 {
            let id = read_u32(entry);
            if id == ida {
                sa = k;
            }
            if id == idb {
                sb = k;
            }
            entry += 0x49;
        }
    }
    if sa == 0xff {
        return 1;
    }
    if sb == 0xff {
        return -1;
    }
    let d = sa.wrapping_sub(sb) as i8;
    if d != 0 {
        return d as i32;
    }
    let (a, b) = player_sort_pair(pa, pb);
    player_sort_by_name(a, b)
}

/// Squad list order "squad slot": the players by the human manager's squad number index
/// (`HUMAN_MANAGER::get_player_squad_number(player, 0)`), the unnumbered (0xff) last, no name tie-break.
///
/// A null first entry sorts last (1), a null second first (-1). An unnumbered first player gives 1 when the second
/// has a number and 0 when neither has; an unnumbered second one gives -1; otherwise first - second (signed bytes).
/// Original: `compare_players_by_human_squad_slot` (0x485630, club_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_players_by_human_squad_slot(pa: *const usize, pb: *const usize) -> i32 {
    let (a, b) = player_sort_pair(pa, pb);
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    let number: unsafe extern "thiscall" fn(usize, usize, usize) -> u8 = core::mem::transmute(0x601880usize);
    let na = number(read_usize(G_HUMAN_MANAGER), a, 0);
    let nb = number(read_usize(G_HUMAN_MANAGER), b, 0);
    if na == 0xff {
        return (nb != 0xff) as i32;
    }
    if nb == 0xff {
        return -1;
    }
    na as i8 as i32 - nb as i8 as i32
}

/// Squad list order "status": the players by their status code (`get_player_status_code(player, club, fixture)`,
/// 0x4849f0), then by name.
///
/// A null first entry sorts last (1), a null second first (-1); then the signed byte difference of the codes
/// first - second; equal codes go to the names.
/// Original: `compare_players_by_status_code_then_name` (0x4856a0, club_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_players_by_status_code_then_name(pa: *const usize, pb: *const usize) -> i32 {
    let (a, b) = player_sort_pair(pa, pb);
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    let status: unsafe extern "C" fn(usize, usize, usize) -> u8 = core::mem::transmute(0x4849f0usize);
    let (club, fixture) = (read_usize(PLAYER_SORT_CLUB), read_usize(PLAYER_SORT_FIXTURE));
    let sb = status(b, club, fixture);
    let sa = status(a, club, fixture);
    let d = sa.wrapping_sub(sb) as i8;
    if d != 0 {
        return d as i32;
    }
    let (a, b) = player_sort_pair(pa, pb);
    player_sort_by_name(a, b)
}

/// Squad list order "name": the players by name (`player_sort_by_name`).
/// Original: `compare_players_by_name` (0x4857a0, club_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_players_by_name(pa: *const usize, pb: *const usize) -> i32 {
    let (a, b) = player_sort_pair(pa, pb);
    player_sort_by_name(a, b)
}

/// Squad list order "position": the players by their positions text, then by name.
///
/// A null first entry (or one with no player record at `staff::PLAYER`) sorts last (1), a null second one first
/// (-1); the positions are written by `database_format_player_positions(player, buffer, 200, 4)` and compared with
/// `utils_string_compare(first, second, 1, 0)`; equal texts go to the names.
/// Original: `compare_players_by_positions_then_name` (0x485830, club_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_players_by_positions_then_name(pa: *const usize, pb: *const usize) -> i32 {
    let (a, b) = player_sort_pair(pa, pb);
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    let (ra, rb) = (read_usize(a + staff::PLAYER), read_usize(b + staff::PLAYER));
    if ra == 0 {
        return 1;
    }
    if rb == 0 {
        return -1;
    }
    let positions: unsafe extern "C" fn(usize, *mut u8, u32, u32) -> u32 = core::mem::transmute(0x53ee50usize);
    let (mut x, mut y) = ([0u8; 200], [0u8; 200]);
    positions(ra, x.as_mut_ptr(), 200, 4);
    positions(rb, y.as_mut_ptr(), 200, 4);
    let r = exe::utils_string_compare(x.as_ptr(), y.as_ptr(), 1, 0);
    if r != 0 {
        return r;
    }
    let (a, b) = player_sort_pair(pa, pb);
    player_sort_by_name(a, b)
}

/// Squad list order "club": the players by their club's name (the text at +0x38 of the `staff::CLUB_JOB` club),
/// then by name.
///
/// A null first entry (or one without a club) sorts last (1), a null second one first (-1); the club names are
/// compared with `utils_string_compare(first, second, 1, 0)`; equal names go to the players' names.
/// Original: `compare_players_by_club_name_then_name` (0x485960, club_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_players_by_club_name_then_name(pa: *const usize, pb: *const usize) -> i32 {
    let (a, b) = player_sort_pair(pa, pb);
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    let (ca, cb) = (read_usize(a + staff::CLUB_JOB), read_usize(b + staff::CLUB_JOB));
    if ca == 0 {
        return 1;
    }
    if cb == 0 {
        return -1;
    }
    let r = exe::utils_string_compare((ca + 0x38) as *const u8, (cb + 0x38) as *const u8, 1, 0);
    if r != 0 {
        return r;
    }
    let (a, b) = player_sort_pair(pa, pb);
    player_sort_by_name(a, b)
}

/// Squad list order "squad status": the players by the squad status of their contract with the list's side, then
/// by name.
///
/// A null first entry sorts last (1), a null second one first (-1). Each player's contract with
/// `PLAYER_SORT_SIDE` comes from `CONTRACT_MANAGER::get_contract_for_club`; when the human controls the side
/// (`human_manager_current_controls_club(side, 0, 1)`) the status is the high nibble of the contract's byte +0x4f
/// (100 without a contract), otherwise both are 100. The signed difference first - second decides; equal statuses
/// go to the names.
/// Original: `compare_players_by_squad_status_then_name` (0x485a60, club_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_players_by_squad_status_then_name(pa: *const usize, pb: *const usize) -> i32 {
    let (a, b) = player_sort_pair(pa, pb);
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    let side = read_usize(PLAYER_SORT_SIDE);
    let ca = exe::contract_manager_get_contract_for_club(read_usize(G_CONTRACT_MANAGER), a, side);
    let cb = exe::contract_manager_get_contract_for_club(read_usize(G_CONTRACT_MANAGER), b, side);
    let (mut sa, mut sb) = (100u8, 100u8);
    if exe::human_manager_current_controls_club(side, 0, 1) != 0 {
        if ca != 0 {
            sa = read_u8(ca + 0x4f) >> 4;
        }
        if cb != 0 {
            sb = read_u8(cb + 0x4f) >> 4;
        }
    }
    let d = sa as i8 as i32 - sb as i8 as i32;
    if d != 0 {
        return d;
    }
    let (a, b) = player_sort_pair(pa, pb);
    player_sort_by_name(a, b)
}

/// Squad list order "squad number": the players by the absolute value of their squad number at the list's side,
/// then by name.
///
/// A null first entry (or one with no player record) sorts last (1), a null second one first (-1); then a first
/// player with squad number 0 (`SQUAD_MANAGER::get_squad_number(player, PLAYER_SORT_SIDE)`) sorts last (1) and a
/// second one first (-1); otherwise the byte difference |first| - |second| (signed) decides, and equal numbers go
/// to the names.
/// Original: `compare_players_by_squad_number_then_name` (0x485ba0, club_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_players_by_squad_number_then_name(pa: *const usize, pb: *const usize) -> i32 {
    let (a, b) = player_sort_pair(pa, pb);
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    if read_usize(a + staff::PLAYER) == 0 {
        return 1;
    }
    if read_usize(b + staff::PLAYER) == 0 {
        return -1;
    }
    let number = |p: usize| exe::squad_manager_get_squad_number(read_usize(PLAYER_SORT_SQUAD_MANAGER), p, read_usize(PLAYER_SORT_SIDE));
    if number(a) == 0 {
        return 1;
    }
    if number(b) == 0 {
        return -1;
    }
    let nb = (number(b) as i32).abs();
    let na = (number(a) as i32).abs();
    let d = (na as u8).wrapping_sub(nb as u8) as i8;
    if d != 0 {
        return d as i32;
    }
    let (a, b) = player_sort_pair(pa, pb);
    player_sort_by_name(a, b)
}

/// Squad list order "release clause": the players by the code of their release clause, then by its abbreviation,
/// then by name.
///
/// A null first entry sorts last (1), a null second one first (-1). Each player's buffer starts as "  -" (the four
/// bytes at 0x98e8c8) and 26 zero bytes, and the code as -1; a contract (`CONTRACT_MANAGER::get_contract`) replaces
/// both with `STAFF_CONTRACT::get_release_clause_abbreviation(buffer, 30)`. The signed byte difference
/// second - first decides; then the two texts byte by byte (1 when the first is greater, -1 when smaller, the low
/// byte of the result); equal texts go to the names.
/// Original: `compare_players_by_release_clause_then_name` (0x485d20, club_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_players_by_release_clause_then_name(pa: *const usize, pb: *const usize) -> i32 {
    let (a, b) = player_sort_pair(pa, pb);
    let (mut ta, mut tb) = ([0u8; 30], [0u8; 30]);
    let dash = read_u32(0x98e8c8).to_le_bytes();
    ta[..4].copy_from_slice(&dash);
    tb[..4].copy_from_slice(&dash);
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    let ca = exe::contract_manager_get_contract(read_usize(G_CONTRACT_MANAGER), a);
    let cb = exe::contract_manager_get_contract(read_usize(G_CONTRACT_MANAGER), b);
    let clause: unsafe extern "thiscall" fn(usize, *mut u8, u32) -> u8 = core::mem::transmute(0x868020usize);
    let (mut ka, mut kb) = (0xffu8, 0xffu8);
    if ca != 0 {
        ka = clause(ca, ta.as_mut_ptr(), 0x1e);
    }
    if cb != 0 {
        kb = clause(cb, tb.as_mut_ptr(), 0x1e);
    }
    let d = kb.wrapping_sub(ka) as i8;
    if d != 0 {
        return d as i32;
    }
    let mut k = 0;
    let order = loop {
        let (x, y) = (ta[k], tb[k]);
        if x != y {
            break if x < y { -1i8 } else { 1 };
        }
        if x == 0 || k + 1 >= ta.len() {
            break 0;
        }
        k += 1;
    };
    if order != 0 {
        return order as i32;
    }
    let (a, b) = player_sort_pair(pa, pb);
    player_sort_by_name(a, b)
}

/// The rank of a European registration byte (`staff::SQUAD_SELECTED_FOR`): 1 → 4, 2 → 3, 4 → 2, 0 → 1, others 0.
fn euro_registration_rank(v: u8) -> u8 {
    match v {
        1 => 4,
        2 => 3,
        4 => 2,
        0 => 1,
        _ => 0,
    }
}

/// Squad list order "European registration": the players by the rank of their registration byte
/// (`staff::SQUAD_SELECTED_FOR`: 1, 2, 4, 0, then the others), then by name.
///
/// A null first entry sorts last (1), a null second one first (-1); then the signed byte difference of the ranks
/// second - first (1 → 4, 2 → 3, 4 → 2, 0 → 1, others 0); equal ranks go to the names.
/// Original: `compare_players_by_euro_registration_then_name` (0x485ed0, club_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_players_by_euro_registration_then_name(pa: *const usize, pb: *const usize) -> i32 {
    let (a, b) = player_sort_pair(pa, pb);
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    let rb = euro_registration_rank(read_u8(b + staff::SQUAD_SELECTED_FOR));
    let ra = euro_registration_rank(read_u8(a + staff::SQUAD_SELECTED_FOR));
    let d = rb.wrapping_sub(ra) as i8;
    if d != 0 {
        return d as i32;
    }
    player_sort_by_name(a, b)
}

/// Squad list order "form": the players by their recent form (`PlayerStats::get_recent_form`), best first, then by
/// name.
///
/// A null first entry, or one without a player record or with an id not below `G_STAFF_COUNT`, sorts last (1); the
/// same for the second gives -1. Then the signed difference second - first of the forms; equal forms go to the names.
/// Original: `compare_players_by_form_then_name` (0x485fd0, club_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_players_by_form_then_name(pa: *const usize, pb: *const usize) -> i32 {
    let (a, b) = player_sort_pair(pa, pb);
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    let (ra, rb) = (read_usize(a + staff::PLAYER), read_usize(b + staff::PLAYER));
    let count = read_i32(G_STAFF_COUNT);
    if ra == 0 || read_i32(a) >= count {
        return 1;
    }
    if rb == 0 || read_i32(b) >= count {
        return -1;
    }
    let fb = exe::playerstats_get_recent_form(read_usize(G_PLAYER_STATS), rb) as i32;
    let fa = exe::playerstats_get_recent_form(read_usize(G_PLAYER_STATS), ra) as i32;
    if fb - fa != 0 {
        return fb - fa;
    }
    let (a, b) = player_sort_pair(pa, pb);
    player_sort_by_name(a, b)
}

/// The original of one of this item's comparators side by side with the copy, by return value.
unsafe fn player_sort_compare(name: &str, original: unsafe extern "C" fn(*const usize, *const usize) -> i32,
    copy: unsafe extern "C" fn(*const usize, *const usize) -> i32, a: *const usize, b: *const usize) -> i32 {
    let r = original(a, b);
    let v = copy(a, b);
    SCOREBOARD.record(r == v, || format!("squad list sort {} ({:#x}, {:#x}): original={} rust={}", name, *a, *b, r, v));
    r
}

/// Comparer for `compare_players_by_selection_slot_then_name`: the order side by side.
pub(crate) unsafe extern "C" fn compare_compare_players_by_selection_slot_then_name(a: *const usize, b: *const usize) -> i32 {
    player_sort_compare("selection", original_fn(IDX_COMPARE_PLAYERS_BY_SELECTION_SLOT_THEN_NAME), compare_players_by_selection_slot_then_name, a, b)
}

