/// Comparer for `release_find_screen`: only the original runs (it frees the engines), the parameters checked against
/// the plan afterwards (2, 8, 0xe and 0x14 cleared, the others as they were).
pub(crate) unsafe extern "C" fn compare_release_find_screen() {
    let mut plan = tel34_find_params();
    for k in [2usize, 8, 0xe, 0x14] {
        plan[k] = 0;
    }
    original_fn::<unsafe extern "C" fn()>(IDX_RELEASE_FIND_SCREEN)();
    let got = tel34_find_params();
    SCOREBOARD.record(got == plan, || format!("Search For screen (release_find_screen): params {:x?} x plan {:x?}", got, plan));
}

// ---------- batch 318: the Discipline Player screen (Fine.cpp) ----------

/// The screen manager's network flag (`[0xb77c84]`): set, the screens of a network game answer every widget with -9.
const TEL35_NETWORK_FLAG: usize = 0xb77c84;
/// Fine.cpp's discipline texts: "Discipline Player", "Official Warning", "<%d - Fine period> Week Fine" and the
/// language-10 variants (a plain "%d" week text and a fixed one-week text).
const DISCIPLINE_TITLE: usize = 0x9cc0e8;
const DISCIPLINE_WARNING: usize = 0x9cc060;
const DISCIPLINE_WEEK_FINE: usize = 0x9cc01c;
const DISCIPLINE_WEEK_FINE_L10: usize = 0x9cc03c;
const DISCIPLINE_ONE_WEEK_L10: usize = 0x9cc050;

/// `Text::draw_wrapped(slot, left, right, &line, font, colour, style, flags)` (0x4aeaf0, thiscall, ret 0x20): lays a
/// Text's words out as area rows from `line` on, advancing it.
pub(crate) unsafe fn tel35_text_draw_wrapped(text: usize, area: u32, left: i32, right: i32, line: *mut i32, font: u32, colour: u32, style: u32, flags: u32) -> i32 {
    let f: unsafe extern "thiscall" fn(usize, u32, i32, i32, *mut i32, u32, u32, u32, u32) -> i32 = core::mem::transmute(0x4aeaf0usize);
    f(text, area, left, right, line, font, colour, style, flags)
}

/// A colour word zero-extended (the original pushes a register with only its low half loaded).
pub(crate) unsafe fn tel35_colour(a: usize) -> u32 {
    read_u16(a) as u32
}

/// The person of screen parameter 0 (a staff id): the staff table entry.
unsafe fn discipline_person() -> usize {
    read_usize(G_STAFF_TABLE).wrapping_add((get_screen_param(0) as u32).wrapping_mul(staff::SIZE as u32) as usize)
}

/// The fine period's text into the screens' text buffer: 1 "Official Warning", otherwise "<n> Week Fine" with
/// n = period − 1 (langlib).
unsafe fn discipline_period_text(period: i32) {
    let text: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    if period == 1 {
        text(JOB_TEXT, DISCIPLINE_WARNING);
    } else {
        text(JOB_TEXT, DISCIPLINE_WEEK_FINE, period - 1);
    }
}

/// Rule: the Discipline Player screen opens for a person with the fine period at 1 (an official warning) and the reason
/// at 0.
///
/// `open_discipline_player_screen(&person)`: `open_screen` with the builder 0x5a83e0, the handler 0x5a8990, single
/// instance, the no-op leave routine 0x5a8f60 and 0; when it opens, parameter 0 = the person's id (the first dword of
/// the record the argument points to), 1 = 1 (the period) and 3 = 0 (the reason).
/// Original: `open_discipline_player_screen` (0x5a8380, Fine.cpp, cdecl).
pub(crate) unsafe extern "C" fn open_discipline_player_screen(person: usize) {
    covered!("tel35_1 open discipline");
    if exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x5a83e0usize, 0x5a8990usize, 1, 0x5a8f60usize, 0) == 0 {
        return;
    }
    set_screen_param(0, read_u32(person) as usize);
    set_screen_param(1, 1);
    set_screen_param(3, 0);
}

/// Rule: the Discipline Player screen shows the person's name in his club's colours, the sentence with a link to the
/// person, the period chooser ("-", the period, "+"; "-" greyed at a warning, "+" greyed at two weeks), the five
/// reasons (the chosen one in yellow) and Cancel / Confirm.
///
/// `draw_discipline_player_screen()`: the person of parameter 0 (`staff::SIZE` × id into the staff table); with no club
/// (`staff::CLUB_JOB`) nothing is built. Otherwise the period (parameter 1) and, as the reason, the low byte of
/// parameter 2 (the original reads 2, where this routine keeps the "-" widget, not 3 where the handler keeps the
/// reason: a defect kept). The person's background picture (`background_set_staff_picture`, 0, 0); the title: his name
/// (`database_format_staff_name`, 500 bytes, style 1) in the club's kit colours (kit 1); the subtitle "Discipline
/// Player". Area 1 (0x6e, 0x8c)-(0x30c, 0x221), seven columns (2, 20, 2, 10, 2, 4, 3), rows = 0x195 / the height of
/// font 3, kind 2: the sentence with the person's name (a Text with the link 0x7d7 to the person) drawn wrapped from
/// row 0 (font 3, pale grey); two rows below, "Disciplinary action:" (column 1), "-" in column 2 (a grey text at period
/// ≤ 1, otherwise a button id 2), its widget kept in parameter 2, the period's text in column 3 ("Official Warning", or
/// "<n> Week Fine"; in language 10 a fixed text for period 2 and a plain "%d" one otherwise), "+" in column 4 (a grey
/// text at period ≥ 3, otherwise a button id 1); two rows below "Reason For Disciplinary Action:". Area 2, the same
/// rectangle, two columns (2, 17), kind 1: from two rows below, the five reasons (`Fine::reason_text` k, 2000 bytes)
/// as buttons id 3 with data k, the chosen one yellow and the others grey. The menu bar (4, 0) and the button area
/// (0x64, 0x22b)-(0x316, 0x24e) (columns 3, 1; the club's background colour) with "Cancel" (id 4) and "Confirm" (id 5).
/// Original: `draw_discipline_player_screen` (0x5a83e0, Fine.cpp, cdecl).
pub(crate) unsafe extern "C" fn draw_discipline_player_screen() {
    let text: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    let format: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_CRT_SPRINTF);
    let reason_text: unsafe extern "thiscall" fn(usize, u32, usize, u32, u32) = core::mem::transmute(0x5a73a0usize);
    let columns: [u8; 7] = [2, 0x14, 2, 0xa, 2, 4, 3];
    let buttons: [u8; 4] = [3, 1, 2, 0x11];
    let mut tx = [0u32; 8];
    let t = tx.as_mut_ptr() as usize;
    exe::new_text(tx.as_mut_ptr() as *mut usize, 0usize);
    let person = discipline_person();
    let club = read_usize(person + staff::CLUB_JOB);
    if club == 0 {
        exe::drop_text(tx.as_mut_ptr() as *mut usize);
        return;
    }
    covered!("tel35_1 draw discipline");
    let period = get_screen_param(1) as u8 as i8 as i32;
    let reason = get_screen_param(2) as u8;
    let background: unsafe extern "C" fn(usize, u32, u32) -> i32 = core::mem::transmute(0x41c790usize);
    background(person, 0, 0);
    let (mut fore, mut back) = (0u32, 0u32);
    exe::database_get_club_kit_colours(club, 1, &mut fore, &mut back);
    let mut name = [0u8; 500];
    exe::database_format_staff_name(person, name.as_mut_ptr() as usize, 0x1f4, 1);
    exe::screenmanager_add_screen_title(G_SCREEN_MANAGER, back & 0xffff, fore & 0xffff, name.as_ptr() as usize);
    text(JOB_TEXT, DISCIPLINE_TITLE);
    exe::screenmanager_add_screen_subtitle(G_SCREEN_MANAGER, JOB_TEXT, 1);
    let rows = (0x195 / exe::font_get_height(3)) as u8 as u32;
    let d = current_human_display();
    let area = tel26_add_area(d, [0x6e, 0x8c, 0x30c, 0x221, 7, columns.as_ptr() as u32, rows, 0, 2, 0, u32::MAX]);
    text(JOB_TEXT, 0x9cc08c, 0x64, name.as_ptr());
    exe::text_set_string(t, JOB_TEXT as *const u8);
    exe::text_add_link(t, name.as_ptr(), 0x7d7, person);
    let mut line = 0i32;
    tel35_text_draw_wrapped(t, area, 0x6e, 0x30c, &mut line, 3, tel35_colour(G_GUI_COLOUR_PALE_GREY), 0, 0);
    let mut row = line + 2;
    let pale = tel35_colour(G_GUI_COLOUR_PALE_GREY);
    let grey = tel35_colour(G_GUI_COLOUR_GREY);
    let blue = tel35_colour(G_GUI_COLOUR_DARK_BLUE);
    text(JOB_TEXT, 0x9cc074);
    tel26_area_button([area, 1, row as u32, 1, 0, 1, 3, pale, JOB_TEXT as u32, 0, 0]);
    let minus = if period <= 1 {
        tel26_area_text([area, 2, row as u32, 0x30, blue, 0xc, 3, grey, 0x98ba0c])
    } else {
        tel26_area_button([area, 2, row as u32, 0x30, blue, 0xc, 3, pale, 0x98ba0c, 2, 0])
    };
    set_screen_param(2, minus as i16 as isize as usize);
    if period == 1 {
        text(JOB_TEXT, DISCIPLINE_WARNING);
    } else if exe::langlib_get_language() == 0xa {
        if period == 2 {
            tel26_copy_text(JOB_TEXT as *mut u8, DISCIPLINE_ONE_WEEK_L10 as *const u8);
        } else {
            format(JOB_TEXT, DISCIPLINE_WEEK_FINE_L10, period - 1);
        }
    } else {
        text(JOB_TEXT, DISCIPLINE_WEEK_FINE, period - 1);
    }
    tel26_area_text([area, 3, row as u32, 1, tel35_colour(G_GUI_COLOUR_BLACK), 0xc, 3, pale, JOB_TEXT as u32]);
    if period >= 3 {
        tel26_area_text([area, 4, row as u32, 0x30, blue, 0xc, 3, grey, 0x9afe7c]);
    } else {
        tel26_area_button([area, 4, row as u32, 0x30, blue, 0xc, 3, pale, 0x9afe7c, 1, 0]);
    }
    row += 2;
    text(JOB_TEXT, 0x9cbffc);
    tel26_area_button([area, 1, row as u32, 1, 0, 1, 3, pale, JOB_TEXT as u32, 0, 0]);
    row += 2;
    let reasons = tel26_add_area(d, [0x6e, 0x8c, 0x30c, 0x221, 2, buttons.as_ptr().wrapping_add(2) as u32, rows, 0, 1, 0, u32::MAX]);
    for k in 0..5u8 {
        reason_text(read_usize(G_FINE), k as u32, JOB_TEXT, 0x7d0, 0);
        let colour = if reason != k { grey } else { tel35_colour(G_GUI_COLOUR_YELLOW) };
        tel26_area_button([reasons, 1, row as u32, 1, 0, 1, 3, colour, JOB_TEXT as u32, 3, k as u32]);
        row += 1;
    }
    exe::menubar_build(4, 0);
    let d = current_human_display();
    let bar = tel26_add_area(d, [0x64, 0x22b, 0x316, 0x24e, 2, buttons.as_ptr() as u32, 1, 0, 1, back & 0xffff, u32::MAX]);
    text(JOB_TEXT, 0x98a1a0);
    tel26_area_button([bar, 0, 0, 0x30, grey, 0xc, 3, pale, JOB_TEXT as u32, 4, 0]);
    text(JOB_TEXT, 0x98a198);
    tel26_area_button([bar, 1, 0, 0x30, grey, 0xc, 3, pale, JOB_TEXT as u32, 5, 0]);
    exe::drop_text(tx.as_mut_ptr() as *mut usize);
}

/// Rule: on the Discipline Player screen "-" and "+" move the period between a warning and a two-week fine (greying
/// the button at the end), a reason click colours it yellow, Confirm fines the person and closes, Cancel closes.
///
/// `discipline_player_screen_input(item)`: in a network game (`[0xb77c84]`) the pending command argument is cleared and
/// -9 comes back. The widget's id (`tel26_item_id`): 2 ("-"): the period (parameter 1) goes down while above 1 and is
/// written back; the "-" widget (parameter 2) gets flags 6, grey and data 0 when the period reaches 1; the period text
/// (the next widget) is rewritten; "+" (the one after) gets flags 2, pale grey and id 1; redraw, 0. 1 ("+"): the period
/// goes up while below 3; "-" gets flags 2, pale grey and id 2; the text; "+" gets flags 6, grey and data 0 when it
/// reaches 3; redraw, 0. 3 (a reason): the widget's data k; the five reason widgets (parameter 2 + 4 ...) recoloured,
/// yellow the chosen one (k above 3 selects the fifth) and grey the others; parameter 3 = k; redraw, 0. 5 (Confirm):
/// `Fine::fine_player(person, period, reason)`, -9. 4 (Cancel): -9. Otherwise the menu bar's command, then its object
/// link.
/// Original: `discipline_player_screen_input` (0x5a8990, Fine.cpp, cdecl).
pub(crate) unsafe extern "C" fn discipline_player_screen_input(raw: u32) -> i32 {
    let person = discipline_person();
    let mut period = get_screen_param(1) as i32;
    let reason = get_screen_param(3);
    if read_u32(TEL35_NETWORK_FLAG) != 0 {
        write_u32(G_PENDING_COMMAND_ARG, 0);
        return -9;
    }
    let item = raw as i16;
    let sm = G_SCREEN_MANAGER;
    match tel26_item_id(item) {
        2 => {
            covered!("tel35_1 discipline minus");
            if period > 1 {
                period -= 1;
            }
            set_screen_param(1, period as usize);
            let mut w = get_screen_param(2) as u32;
            if period <= 1 {
                exe::screenmanager_set_widget_flags(sm, w as usize, 6);
                exe::screenmanager_set_widget_text_colour(sm, w, tel35_colour(G_GUI_COLOUR_GREY));
                exe::screenmanager_set_widget_data(sm, w, 0usize);
            }
            w = w.wrapping_add(1);
            discipline_period_text(period);
            exe::screenmanager_set_widget_text(sm, w, JOB_TEXT);
            w = w.wrapping_add(1);
            exe::screenmanager_set_widget_flags(sm, w as usize, 2);
            exe::screenmanager_set_widget_text_colour(sm, w, tel35_colour(G_GUI_COLOUR_PALE_GREY));
            exe::screenmanager_set_widget_id(sm, w, 1);
        }
        1 => {
            covered!("tel35_1 discipline plus");
            if period < 3 {
                period += 1;
            }
            set_screen_param(1, period as usize);
            let mut w = get_screen_param(2) as u32;
            exe::screenmanager_set_widget_flags(sm, w as usize, 2);
            exe::screenmanager_set_widget_text_colour(sm, w, tel35_colour(G_GUI_COLOUR_PALE_GREY));
            exe::screenmanager_set_widget_id(sm, w, 2);
            w = w.wrapping_add(1);
            discipline_period_text(period);
            exe::screenmanager_set_widget_text(sm, w, JOB_TEXT);
            w = w.wrapping_add(1);
            if period >= 3 {
                exe::screenmanager_set_widget_flags(sm, w as usize, 6);
                exe::screenmanager_set_widget_text_colour(sm, w, tel35_colour(G_GUI_COLOUR_GREY));
                exe::screenmanager_set_widget_data(sm, w, 0usize);
            }
        }
        3 => {
            covered!("tel35_1 discipline reason");
            let k = tel26_item_value(item);
            let chosen = k.min(4);
            let first = (get_screen_param(2) as u32).wrapping_add(4);
            for j in 0..5u32 {
                let colour = if j == chosen { G_GUI_COLOUR_YELLOW } else { G_GUI_COLOUR_GREY };
                exe::screenmanager_set_widget_text_colour(sm, first.wrapping_add(j), tel35_colour(colour));
            }
            set_screen_param(3, k as usize);
        }
        5 => {
            covered!("tel35_1 discipline confirm");
            exe::fine_fine_player(read_usize(G_FINE), person, period as u32, reason as u32);
            return -9;
        }
        4 => return -9,
        _ => return manager_menu_bar(raw),
    }
    exe::screenmanager_redraw_screen(sm, 0, 0);
    0
}

/// Comparer for `open_discipline_player_screen`.
pub(crate) unsafe extern "C" fn compare_open_discipline_player_screen(person: usize) {
    // simplification: opening a screen does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(usize)>(IDX_OPEN_DISCIPLINE_PLAYER_SCREEN)(person)
}

/// Comparer for `draw_discipline_player_screen`: the screen side by side over the display list.
pub(crate) unsafe extern "C" fn compare_draw_discipline_player_screen() {
    let o = original_fn::<unsafe extern "C" fn()>(IDX_DRAW_DISCIPLINE_PLAYER_SCREEN);
    compare_by_display_list_with("Discipline Player screen (draw_discipline_player_screen)", &[], || o(), || draw_discipline_player_screen());
}

/// Comparer for `discipline_player_screen_input`.
pub(crate) unsafe extern "C" fn compare_discipline_player_screen_input(item: u32) -> i32 {
    // simplification: the fine, the redraw and the menu bar commands do not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(u32) -> i32>(IDX_DISCIPLINE_PLAYER_SCREEN_INPUT)(item)
}

// ---------- batch 318: the history screens (History.cpp) ----------

/// The History.cpp path for the error box.
const HISTORY_CPP: usize = 0x9cec24;
/// The history screens' file name buffer (0xb5dedc, also the "Ok" text).
const HISTORY_FILE_TEXT: usize = 0xb5dedc;
/// The empty text (0xad9c64).
const HISTORY_EMPTY: usize = 0xad9c64;
/// The size of a history record (an entry list: +0 the entries, 8 bytes each (text, picture), +4 their count, +8 the
/// record's name) and of a written history file entry (+0 the file name, 0x104 bytes; +0x104 its title, 0x12c bytes).
const HISTORY_RECORD_SIZE: usize = 0x6c;
const HISTORY_FILE_ENTRY_SIZE: usize = 0x230;
/// The size of a picture name in the history's picture table (screen parameter 4).
const HISTORY_PICTURE_NAME_SIZE: usize = 0x104;

/// `ScreenManager::add_text_item(x1, y1, x2, y2, style, colour, flags, font, text colour, text, 1)` (0x803fd0, thiscall,
/// ret 0x2c).
pub(crate) unsafe fn tel35_text_item(f: [u32; 11]) -> u32 {
    type TextItem = unsafe extern "thiscall" fn(usize, u32, u32, u32, u32, u32, u32, u32, u32, u32, u32, u32) -> u32;
    let g: TextItem = core::mem::transmute(0x803fd0usize);
    g(G_SCREEN_MANAGER, f[0], f[1], f[2], f[3], f[4], f[5], f[6], f[7], f[8], f[9], f[10])
}

/// The C runtime's strncpy (0x9466d0, cdecl).
pub(crate) unsafe fn tel35_strncpy(dst: usize, src: usize, n: u32) {
    let f: unsafe extern "C" fn(usize, usize, u32) -> usize = core::mem::transmute(0x9466d0usize);
    f(dst, src, n);
}

/// A cdecl routine of the exe with one argument, returning eax.
pub(crate) unsafe fn tel35_cdecl1(f: usize, a: usize) -> usize {
    let g: unsafe extern "C" fn(usize) -> usize = core::mem::transmute(f);
    g(a)
}

/// The picture of the history record's selected entry: the picture name (`HISTORY_PICTURE_NAME_SIZE` bytes each from
/// parameter 4) of `index`, or the default picture (parameter 7) for -1.
unsafe fn history_picture_name(index: i32) -> usize {
    if index == -1 {
        get_screen_param(7)
    } else {
        get_screen_param(4).wrapping_add((index as u32).wrapping_mul(HISTORY_PICTURE_NAME_SIZE as u32) as usize)
    }
}

/// Rule: the history screen opens on a .his file with the default frame (0x91, 0x4b)-(0x2e9, 0x20f), the text column
/// 0x115 from the left, the picture 0x101 × 0x14f and the pictures under "cm3_history".
///
/// `history_screen_open(name)`: `open_screen` with the builder 0x5f1360, the handler 0x5f1ba0, single instance, the
/// leave routine 0x5f1d60 and 0; when it opens, the parameters: 0 = -1 (no file list), 1..7 = 0, 8..0xb = -1, 0xc =
/// a copy of the name (`set_screen_param` with copy 1), 0xd = -1, 0xe..0x12 = 0x91, 0x4b, 0x2e9, 0x20f, 0x115, 0x13 =
/// "cm3_history", 0x14 = 0x101 and 0x15 = 0x14f.
/// Original: `history_screen_open` (0x5f11c0, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_screen_open(name: usize) {
    covered!("tel35_2 open history");
    if exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x5f1360usize, 0x5f1ba0usize, 1, 0x5f1d60usize, 0) == 0 {
        return;
    }
    set_screen_param(0, usize::MAX);
    for k in 1..8 {
        set_screen_param(k, 0);
    }
    for k in 8..0xc {
        set_screen_param(k, usize::MAX);
    }
    exe::screenmanager_set_screen_param(G_SCREEN_MANAGER, 0xc, name, 1);
    for (k, v) in [(0xd, usize::MAX), (0xe, 0x91), (0xf, 0x4b), (0x10, 0x2e9), (0x11, 0x20f), (0x12, 0x115), (0x13, 0x9cec18),
        (0x14, 0x101), (0x15, 0x14f)] {
        set_screen_param(k, v);
    }
}

/// Rule: the history screen shows a .his file: its title, the record chooser (when the file has more than one), the
/// record's picture and its text word-wrapped to the text column, with an Ok button.
///
/// `history_screen_draw()`: the frame (parameters 0xe..0x11), the text column's left offset (0x12), the file list
/// (0xc) and its count (0xd); the text width = the frame's width − the offset − 0x34. The background picture 0. With a
/// file index (parameter 0) neither in the list nor -1 with no list (-1): the History.cpp 180 box, nothing more. With no
/// file loaded (parameter 1 empty): `history_load_his_file` of "<name>.his" (no list) or of the list's entry, 0; when it
/// fails nothing is built. The full-screen black area (799 × 599; 1919 × 1079 in the 1080 exe, read from it), the frame
/// area in the colour (0, 0x30, 0x70), the title (parameter 1, font 4) from 10 inside the frame, 0x2d high. The record
/// (parameter 6 of the records in parameter 2, `HISTORY_RECORD_SIZE` each): its first entry's picture index written to
/// parameter 8; the picture's frame (yellow) and the picture item 0x400 (the picture of that index under parameter
/// 0x13, or the default picture (parameter 7) when the index is -1 or its file does not exist; an index below -1 is
/// taken without the check); with more than one record (parameter 3), the record's name (font 3) at the text column,
/// the chooser button and its popup area (0x200030, colour (0, 0x80, 0xff)) with one item per record (id 2, data k),
/// and the text 0x2c lower. Two frame areas of the text column (8 and 0x62) and the text area (1, grey) 10 inside,
/// written to parameter 9 (the picture item to 0xa). Each entry's text is cut into lines that fit the width (font 2;
/// a line ends at the last space before the width, the following spaces skipped; the text is cut in place and put
/// back), one item per line with the entry's picture index as data (the first line's item written to parameter 0xb
/// when it is -1), and a blank item after each entry. Last the "Ok" button (id 1).
/// Original: `history_screen_draw` (0x5f1360, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_screen_draw() {
    let format: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_CRT_SPRINTF);
    let text: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    let load: unsafe extern "C" fn(usize, u32) -> i32 = core::mem::transmute(0x5f1e50usize);
    let x1 = get_screen_param(0xe) as i32;
    let y1 = get_screen_param(0xf) as i32;
    let x2 = get_screen_param(0x10) as i32;
    let y2 = get_screen_param(0x11) as i32;
    let indent = get_screen_param(0x12) as i32;
    let files = get_screen_param(0xc);
    let count = get_screen_param(0xd) as i32;
    let width = x2 - indent - x1 - 0x34;
    exe::background_set_picture(0usize);
    let p0 = get_screen_param(0) as i32;
    if !((p0 >= 0 && p0 < count) || (p0 == -1 && count == -1)) {
        tel26_error_box(HISTORY_CPP, 0xb4);
        return;
    }
    if get_screen_param(1) == 0 {
        let loaded = if get_screen_param(0) as i32 == -1 {
            format(HISTORY_FILE_TEXT, 0x9cec50, get_screen_param(0xc));
            load(HISTORY_FILE_TEXT, 0)
        } else {
            load(read_usize(files.wrapping_add(get_screen_param(0).wrapping_mul(4))), 0)
        };
        if loaded == 0 {
            return;
        }
    }
    covered!("tel35_2 draw history");
    let black = tel35_colour(G_GUI_COLOUR_BLACK);
    let pale = tel35_colour(G_GUI_COLOUR_PALE_GREY);
    let yellow = tel35_colour(G_GUI_COLOUR_YELLOW);
    tel26_add_area(current_human_display(), [0, 0, exe_immediate(0x5f14d0 as *const i32) as u32, exe_immediate(0x5f14c8 as *const i32) as u32,
        1, 0, 1, 0, 2, black, u32::MAX]);
    let colour = exe::graphics_rgb_to_pixel(0, 0x30, 0x70, 0);
    tel26_add_area(current_human_display(), [x1 as u32, y1 as u32, x2 as u32, y2 as u32, 1, 0, 1, 0, 0x30, colour, u32::MAX]);
    let (left, right, top) = (x1 + 0xa, x2 - 0xa, y1 + 0xa);
    tel35_text_item([left as u32, top as u32, right as u32, (top + 0x2d) as u32, 0x30, black, 0xc, 4, pale, get_screen_param(1) as u32, 1]);
    let mut y = top + 0x37;
    let records = get_screen_param(2);
    let record = records.wrapping_add((get_screen_param(6) as u32).wrapping_mul(HISTORY_RECORD_SIZE as u32) as usize);
    let first = read_i32(read_usize(record) + 4);
    set_screen_param(8, first as usize);
    let pic_x2 = get_screen_param(0x14) as i32 + x1 + 0xc;
    let pic_y2 = get_screen_param(0x15) as i32 + y + 2;
    tel35_text_item([left as u32, y as u32, pic_x2 as u32, pic_y2 as u32, 0x61, colour, 1, 2, yellow, HISTORY_EMPTY as u32, 1]);
    let picture = if first == -1 {
        get_screen_param(7)
    } else if first < -1 {
        history_picture_name(first)
    } else if exe::utils_file_exists(exe::utils_build_file_path(get_screen_param(0x13), history_picture_name(first))) != 0 {
        history_picture_name(first)
    } else {
        get_screen_param(7)
    };
    let path = exe::utils_build_file_path(get_screen_param(0x13), picture);
    let picture_item = tel26_add_item(current_human_display(), [0x400, (x1 + 0xc) as u32, (y + 2) as u32, pic_x2 as u32, pic_y2 as u32, 0, 0, 1,
        black, black, 0xc, 2, pale, path as u32, 1, 0, 0, u32::MAX]);
    if get_screen_param(3) as i32 > 1 {
        covered!("tel35_2 history record chooser");
        let x = indent + x1;
        tel35_text_item([x as u32, y as u32, right as u32, (y + 0x22) as u32, 0x32, colour, 0xc, 3, yellow, (record + 8) as u32, 1]);
        let popup_colour = exe::graphics_rgb_to_pixel(0, 0x80, 0xff, 0);
        let button = tel26_add_button([(x + 5) as u32, (y + 5) as u32, (x + 0x14) as u32, (y + 0x19) as u32, 0x20, black, 0xc, 2, yellow,
            HISTORY_EMPTY as u32, 0, 0]);
        let popup = tel26_add_area(current_human_display(), [0, 0, 0, 0, 0, 0, 0, 0, 0x200030, popup_colour, button]);
        let mut k = 0i32;
        while k < get_screen_param(3) as i32 {
            let name = records.wrapping_add(8).wrapping_add((k as u32).wrapping_mul(HISTORY_RECORD_SIZE as u32) as usize);
            tel26_add_item(current_human_display(), [2, 0, 0, 0, 0, 0, 0, 0x90, popup_colour, yellow, 1, 1, black, name as u32, 0, 2, k as u32, popup]);
            k += 1;
        }
        y += 0x2c;
    }
    let x = x1 + indent;
    let bottom = y2 - 0x32;
    tel26_add_area(current_human_display(), [x as u32, y as u32, right as u32, bottom as u32, 1, 0, 0xf, 0, 8, colour, u32::MAX]);
    tel26_add_area(current_human_display(), [x as u32, y as u32, right as u32, bottom as u32, 1, 0, 0xf, 0, 0x62, colour, u32::MAX]);
    let area = tel26_add_area(current_human_display(), [(x + 0xa) as u32, (y + 0xa) as u32, right as u32, (y2 - 0x3c) as u32, 1, 0, 0xf, 0, 1,
        tel35_colour(G_GUI_COLOUR_GREY), u32::MAX]);
    set_screen_param(9, area as i16 as isize as usize);
    set_screen_param(0xa, picture_item as i16 as isize as usize);
    let mut row = 0u32;
    let mut k = 0usize;
    while (k as i32) < read_i32(record + 4) {
        let mut s = read_usize(read_usize(record) + k * 8) as *mut u8;
        if *s != 0 {
            let mut c = *s;
            loop {
                let mut i = 0isize;
                let mut b = c;
                loop {
                    *s.offset(i) = b;
                    b = *s.offset(i + 1);
                    i += 1;
                    *s.offset(i) = 0;
                    if !(exe::font_text_width(2usize, s) < width && b != 0) {
                        break;
                    }
                }
                *s.offset(i) = b;
                while b != b' ' && b != 0 {
                    i -= 1;
                    b = *s.offset(i);
                }
                b = *s.offset(i);
                *s.offset(i) = 0;
                let value = read_u32(read_usize(record) + k * 8 + 4);
                let line = tel26_add_item(current_human_display(), [1, 0, 0, 0, 0, 0, row, 1, black, 0, 1, 2, pale, s as u32, 0, 0, value, area]);
                row += 1;
                if get_screen_param(0xb) as i32 == -1 {
                    set_screen_param(0xb, line as i16 as isize as usize);
                }
                *s.offset(i) = b;
                if b == b' ' {
                    loop {
                        let a = *s.offset(i + 1);
                        i += 1;
                        if a != b' ' {
                            break;
                        }
                    }
                }
                let a = *s.offset(i);
                s = s.offset(i);
                if a == 0 {
                    break;
                }
                c = a;
            }
        }
        let value = read_u32(read_usize(record) + k * 8 + 4);
        tel26_add_item(current_human_display(), [1, 0, 0, 0, 0, 0, row, 1, black, 0, 1, 2, pale, HISTORY_EMPTY as u32, 0, 0, value, area]);
        row += 1;
        k += 1;
    }
    text(HISTORY_FILE_TEXT, 0x990f7c);
    tel26_add_button([left as u32, (y2 - 0x28) as u32, right as u32, (y2 - 0xa) as u32, 0x30, tel35_colour(G_GUI_COLOUR_GREY), 0xc, 4, pale,
        HISTORY_FILE_TEXT as u32, 1, 0]);
}

/// Rule: scrolling the history text shows the picture of the first visible line's entry; Ok closes, a record of the
/// chooser shows that record.
///
/// `history_screen_handle_event(item)`: with no file loaded (parameter 1) -9. The first visible widget of the text
/// (the scroll row of the text area, parameter 9, + the first line's widget, parameter 0xb, + 7): its data (0 for
/// -1) differing from parameter 8 becomes parameter 8, and the picture item (parameter 0xa) gets that picture's path
/// (under parameter 0x13; the default picture, parameter 7, for -1); redraw. Then the item: -1 gives 0; id 1 (Ok) -9;
/// id 2 (a record) writes its data to parameter 6 and gives -11; others 0.
/// Original: `history_screen_handle_event` (0x5f1ba0, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_screen_handle_event(raw: u32) -> i32 {
    if get_screen_param(1) == 0 {
        return -9;
    }
    let scroll = exe::screenmanager_get_area_scroll_row(G_SCREEN_MANAGER, get_screen_param(9)) as u32;
    let shown = scroll.wrapping_add(get_screen_param(0xb) as u32).wrapping_add(7) as i16;
    if tel26_item_value(shown) != get_screen_param(8) as u32 {
        covered!("tel35_2 history picture follows");
        set_screen_param(8, tel26_item_value(shown) as usize);
        let path = exe::utils_build_file_path(get_screen_param(0x13), history_picture_name(get_screen_param(8) as i32));
        exe::screenmanager_set_widget_text(G_SCREEN_MANAGER, get_screen_param(0xa) as u32, path);
        exe::screenmanager_redraw_screen(G_SCREEN_MANAGER, 0, 0);
    }
    let item = raw as i16;
    if item == -1 {
        return 0;
    }
    match tel26_item_id(item) {
        1 => -9,
        2 => {
            set_screen_param(6, tel26_item_value(item) as usize);
            -11
        }
        _ => 0,
    }
}

/// Rule: leaving the history screen frees the loaded file: the picture table, and each record's entry texts, entry
/// list and the record table.
///
/// `history_screen_free()`: parameter 1 = 0; the picture table (parameter 4) freed and cleared when there is one;
/// parameter 7 = 0; with a record table (parameter 2): for each of the parameter 3 records whose entry list is not
/// null, every non-null entry text freed, then the list; then the table, and parameters 2 and 3 = 0.
/// Original: `history_screen_free` (0x5f1d60, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_screen_free() {
    set_screen_param(1, 0);
    if get_screen_param(4) != 0 {
        exe::crt_free(get_screen_param(4));
        set_screen_param(4, 0);
    }
    set_screen_param(7, 0);
    let records = get_screen_param(2);
    let count = get_screen_param(3) as i32;
    if records == 0 {
        return;
    }
    covered!("tel35_2 history free");
    for r in 0..count.max(0) as usize {
        let record = records + r * HISTORY_RECORD_SIZE;
        if read_usize(record) == 0 {
            continue;
        }
        let mut j = 0usize;
        while (j as i32) < read_i32(record + 4) {
            let t = read_usize(read_usize(record) + j * 8);
            if t != 0 {
                exe::crt_free(t);
            }
            j += 1;
        }
        exe::crt_free(read_usize(record));
    }
    exe::crt_free(records);
    set_screen_param(2, 0);
    set_screen_param(3, 0);
}

/// Rule: the written history screen opens on a tab with no file list yet.
///
/// `history_written_screen_open(tab)`: `open_screen` with the builder 0x5f2c00, the handler 0x5f31c0, not single, the
/// leave routine 0x5f33d0 and 0; parameter 0 = the tab, 1..4 = 0.
/// Original: `history_written_screen_open` (0x5f2b80, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_written_screen_open(tab: usize) {
    covered!("tel35_2 open written history");
    if exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x5f2c00usize, 0x5f31c0usize, 0, 0x5f33d0usize, 0) == 0 {
        return;
    }
    set_screen_param(0, tab);
    for k in 1..5 {
        set_screen_param(k, 0);
    }
}

/// Rule: the written history screen lists, under the tabs Nations, Competitions, Leagues, Clubs and Players, the
/// titles of the .his files of the chosen tab's category.
///
/// `history_written_screen_draw()`: ten tab records (0xd4 bytes, built by the runtime's vector constructor with
/// `MenuItem::MenuItem`); the "CM3_HISTORY" folder; the tab (parameter 0), the list (1) and its count (2). The random
/// background picture, the title "History" (dark blue, pale grey), the menu bar (4, 0) and the tab bar of five tabs
/// (Nations 1, Competitions 2, Leagues 3, Clubs 0, Players 4, all kind 1) from 0x50 to 0x221. With no list: a block of
/// 100 file entries (`HISTORY_FILE_ENTRY_SIZE`, `operator new`; null: the History.cpp 1235 box and nothing more); every
/// "*.his" of the folder (`file_find_first`/`file_find_next`) whose name without its extension has the tab's category
/// (`history_get_his_file_category`) and a title (`history_get_his_file_title`) is copied (name 0x104, title 0x12c,
/// each cut at its last byte); a 101st shows the History.cpp 1270 box and the screen stops there (the search left open,
/// the block not kept); the entries sorted by title (qsort with 0x5f3410); parameter 1 = the block and 2 = the count;
/// the search closed. The list area (0x6e, top)-(0x30c, bottom) with (bottom − top − 16) / the height of font 3 rows,
/// one button per entry (" <title>", id 2, the entry as data), scrolled to parameter 3 and written to parameter 4; the
/// Back and Next buttons.
/// Original: `history_written_screen_draw` (0x5f2c00, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_written_screen_draw() {
    let text: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    let format: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_CRT_SPRINTF);
    let mut tabs = [0u32; 0xd4 * 10 / 4];
    let t = tabs.as_mut_ptr() as usize;
    exe::crt_vector_constructor_iterator(t, 0xd4, 0xa, 0x4568f0usize, 0x5a53c0usize);
    let mut folder = [0u8; 0x104];
    tel26_copy_text(folder.as_mut_ptr(), exe::utils_build_file_path(0x9cedb8usize, HISTORY_EMPTY) as *const u8);
    let tab = get_screen_param(0);
    let mut list = get_screen_param(1);
    let mut count = get_screen_param(2) as i32;
    exe::background_set_random_picture();
    text(JOB_TEXT, 0x9914d4, HISTORY_EMPTY);
    exe::screenmanager_add_screen_title(G_SCREEN_MANAGER, tel35_colour(G_GUI_COLOUR_DARK_BLUE), tel35_colour(G_GUI_COLOUR_PALE_GREY), JOB_TEXT);
    exe::menubar_build(4, 0);
    for (k, (label, link)) in [(0x9c9f64u32, 1u32), (0x98ed18, 2), (0x9cedcc, 3), (0x9cedc4, 0), (0x990a80, 4)].into_iter().enumerate() {
        let entry = t + k * 0xd4;
        text(entry + 4, label as usize);
        write_u32(entry + 0xcc, 1);
        write_u32(entry + 0xd0, link);
    }
    let (mut top, mut bottom) = (0x50i32, 0x221i32);
    exe::gui_add_tab_bar(t, 5, tab as i32, &mut top, &mut bottom, 1);
    if list == 0 {
        covered!("tel35_2 written history file search");
        let block = exe::crt_operator_new(0xdac0);
        count = 0;
        if block == 0 {
            tel26_error_box(HISTORY_CPP, 0x4d3);
            exe::crt_vector_destructor_iterator(t, 0xd4, 0xa, 0x5a53c0usize);
            return;
        }
        let mut pattern = [0u8; 0x104];
        let mut found = [0u8; 0x114];
        exe::crt_makepath(pattern.as_mut_ptr(), 0usize, folder.as_ptr() as usize, 0x989ad8usize, 0x9cedb0usize);
        if exe::file_find_first(pattern.as_ptr() as usize, found.as_mut_ptr() as usize, 0) == 0 {
            let mut entry = block;
            loop {
                tel26_copy_text(pattern.as_mut_ptr(), found.as_ptr().add(0x10));
                let mut i = tel35_c_string_len(pattern.as_ptr()) as isize - 1;
                while i >= 0 {
                    if pattern[i as usize] == b'.' {
                        pattern[i as usize] = 0;
                        break;
                    }
                    i -= 1;
                }
                if tel35_cdecl1(0x5f2580, pattern.as_ptr() as usize) as u32 == tab as u32 {
                    let title = tel35_cdecl1(0x5f2700, pattern.as_ptr() as usize);
                    if title != 0 {
                        if count >= 0x64 {
                            tel26_error_box(HISTORY_CPP, 0x4f6);
                            exe::crt_vector_destructor_iterator(t, 0xd4, 0xa, 0x5a53c0usize);
                            return;
                        }
                        tel35_strncpy(entry, pattern.as_ptr() as usize, 0x104);
                        write_u8(entry + 0x103, 0);
                        tel35_strncpy(entry + 0x104, title, 0x12c);
                        write_u8(entry + 0x104 + 0x12b, 0);
                        count += 1;
                        entry += HISTORY_FILE_ENTRY_SIZE;
                    }
                }
                if exe::file_find_next(found.as_mut_ptr()) != 0 {
                    break;
                }
            }
            if count != 0 {
                exe::crt_qsort(block, count as u32, HISTORY_FILE_ENTRY_SIZE as u32, 0x5f3410usize);
            }
        }
        set_screen_param(1, block);
        set_screen_param(2, count as usize);
        exe::file_find_close(found.as_ptr() as usize);
        list = block;
    }
    let rows = ((bottom - top - 0x10) / exe::font_get_height(3)) as u8 as u32;
    let area = tel26_add_area(current_human_display(), [0x6e, top as u32, 0x30c, bottom as u32, 1, 0, rows, 0, 2, 0, u32::MAX]);
    for k in 0..count.max(0) as usize {
        let entry = list + k * HISTORY_FILE_ENTRY_SIZE;
        format(JOB_TEXT, 0x987ff0, entry + 0x104);
        tel26_area_button([area, 0, k as u32, 1, 0, 1, 3, tel35_colour(G_GUI_COLOUR_PALE_GREY), JOB_TEXT as u32, 2, entry as u32]);
    }
    let scroll = get_screen_param(3);
    let d = current_human_display();
    if area as i16 != -1 {
        exe::area_set_scroll_row(d.wrapping_add(4).wrapping_add((area as i16 as isize as usize).wrapping_mul(0xbf1)), scroll);
    }
    set_screen_param(4, area as i16 as isize as usize);
    tel26_back_next();
    exe::crt_vector_destructor_iterator(t, 0xd4, 0xa, 0x5a53c0usize);
}

/// The length of a C string (the original's repne scasb).
pub(crate) unsafe fn tel35_c_string_len(s: *const u8) -> usize {
    let mut n = 0;
    while *s.add(n) != 0 {
        n += 1;
    }
    n
}

/// Rule: on the written history screen a tab click changes the category and drops the list; an entry opens its
/// history screen.
///
/// `history_written_screen_handle_click(item)`: with an item, the list's scroll row (area of parameter 4) is kept in
/// parameter 3. Id 1 (a tab) with a tab other than parameter 0: parameter 0 = that tab, the list (parameter 1) deleted
/// (`operator delete`) and parameters 1 and 2 = 0, -11. Id 2 (an entry): its file name (0x104 bytes, cut at its last
/// byte) opens the history screen (`history_screen_open`), -11. Otherwise (the same tab included) the menu bar's
/// command, then its object link.
/// Original: `history_written_screen_handle_click` (0x5f31c0, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_written_screen_handle_click(raw: u32) -> i32 {
    let tab = get_screen_param(0) as u32;
    let list = get_screen_param(1);
    let item = raw as i16;
    if item != -1 {
        set_screen_param(3, exe::screenmanager_get_area_scroll_row(G_SCREEN_MANAGER, get_screen_param(4)));
    }
    let id = tel26_item_id(item);
    if id == 1 && tel26_item_value(item) != tab {
        covered!("tel35_2 written history tab");
        set_screen_param(0, tel26_item_value(item) as usize);
        if list != 0 {
            exe::crt_operator_delete(list);
        }
        set_screen_param(1, 0);
        set_screen_param(2, 0);
        return -11;
    }
    if id == 2 {
        covered!("tel35_2 written history entry");
        let mut name = [0u8; 0x104];
        tel35_strncpy(name.as_mut_ptr() as usize, tel26_item_value(item) as usize, 0x104);
        name[0x103] = 0;
        tel35_cdecl1(0x5f11c0, name.as_ptr() as usize);
        return -11;
    }
    manager_menu_bar(raw)
}

/// Rule: leaving the written history screen deletes the file list.
///
/// `history_written_screen_close()`: the list (parameter 1) deleted (`operator delete`) when there is one; parameters
/// 1 and 2 = 0.
/// Original: `history_written_screen_close` (0x5f33d0, History.cpp, cdecl).
pub(crate) unsafe extern "C" fn history_written_screen_close() {
    let list = get_screen_param(1);
    if list != 0 {
        exe::crt_operator_delete(list);
    }
    set_screen_param(1, 0);
    set_screen_param(2, 0);
}

/// Comparer for `history_screen_open`.
pub(crate) unsafe extern "C" fn compare_history_screen_open(name: usize) {
    // simplification: opening a screen does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(usize)>(IDX_HISTORY_SCREEN_OPEN)(name)
}

/// Comparer for `history_screen_draw`: side by side over the display list, the file name buffer and the parameters;
/// loading the file does not run twice (only the original runs then).
pub(crate) unsafe extern "C" fn compare_history_screen_draw() {
    let o = original_fn::<unsafe extern "C" fn()>(IDX_HISTORY_SCREEN_DRAW);
    if get_screen_param(1) == 0 {
        // simplification: loading the .his file allocates the records; the first build only in the original
        return o();
    }
    compare_by_display_list_with("History screen (history_screen_draw)", &[(HISTORY_FILE_TEXT, 0x104)], || o(), || history_screen_draw());
}

/// Comparer for `history_screen_handle_event`.
pub(crate) unsafe extern "C" fn compare_history_screen_handle_event(item: u32) -> i32 {
    // simplification: the redraw does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(u32) -> i32>(IDX_HISTORY_SCREEN_HANDLE_EVENT)(item)
}

/// Comparer for `history_screen_free`.
pub(crate) unsafe extern "C" fn compare_history_screen_free() {
    // simplification: freeing does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn()>(IDX_HISTORY_SCREEN_FREE)()
}

/// Comparer for `history_written_screen_open`.
pub(crate) unsafe extern "C" fn compare_history_written_screen_open(tab: usize) {
    // simplification: opening a screen does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(usize)>(IDX_HISTORY_WRITTEN_SCREEN_OPEN)(tab)
}

/// Comparer for `history_written_screen_draw`: side by side over the display list when the list exists (the file
/// search allocates it: the first build only in the original).
pub(crate) unsafe extern "C" fn compare_history_written_screen_draw() {
    let o = original_fn::<unsafe extern "C" fn()>(IDX_HISTORY_WRITTEN_SCREEN_DRAW);
    if get_screen_param(1) == 0 {
        // simplification: the file search allocates the list; the first build only in the original
        return o();
    }
    compare_by_display_list_with("Written history screen (history_written_screen_draw)", &[], || o(), || history_written_screen_draw());
}

/// Comparer for `history_written_screen_handle_click`.
pub(crate) unsafe extern "C" fn compare_history_written_screen_handle_click(item: u32) -> i32 {
    // simplification: opening a screen and the menu bar commands do not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn(u32) -> i32>(IDX_HISTORY_WRITTEN_SCREEN_HANDLE_CLICK)(item)
}

/// Comparer for `history_written_screen_close`.
pub(crate) unsafe extern "C" fn compare_history_written_screen_close() {
    // simplification: deleting does not run twice; proven in Rust mode
    original_fn::<unsafe extern "C" fn()>(IDX_HISTORY_WRITTEN_SCREEN_CLOSE)()
}

// ---------- batch 318: the retire and holiday screens and two list comparers (manager_screens.cpp) ----------

/// A thiscall routine of the exe with one argument.
pub(crate) unsafe fn tel35_this1(f: usize, this: usize, a: usize) -> usize {
    let g: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(f);
    g(this, a)
}

/// A thiscall routine of the exe with two arguments.
pub(crate) unsafe fn tel35_this2(f: usize, this: usize, a: usize, b: usize) -> usize {
    let g: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(f);
    g(this, a, b)
}

/// `HUMAN_MANAGER::get_holiday_option(option, 0)` (0x5fea50) of the human manager table: the option's byte.
unsafe fn holiday_option(option: u32) -> u8 {
    exe::human_manager_get_holiday_option(read_usize(G_HUMAN_MANAGER), option, 0usize)
}

/// `HUMAN_MANAGER::set_holiday_option(option, value, 0)` (0x5feb60, thiscall, ret 0xc).
unsafe fn set_holiday_option(option: u32, value: i32) {
    let g: unsafe extern "thiscall" fn(usize, u32, i32, u32) = core::mem::transmute(0x5feb60usize);
    g(read_usize(G_HUMAN_MANAGER), option, value, 0)
}

/// The background picture of the manager's screens: his club's, else his national team's, else a random one.
unsafe fn manager_job_background(manager: usize) {
    let club = read_usize(manager + staff::CLUB_JOB);
    let nation = read_usize(manager + staff::NATIONAL_JOB);
    if club != 0 {
        exe::background_set_club_picture(club, 0, 0);
    } else if nation != 0 {
        exe::background_set_club_picture(nation, 0, 0);
    } else {
        exe::background_set_random_picture();
    }
}

/// The No (id 1) and Yes (id 2) buttons of a manager confirm screen: the area (0x64, 0x22b)-(0x316, 0x24e), two columns
/// with the weights `weights` (3, 1).
unsafe fn manager_no_yes(weights: &[u8; 2]) {
    let text: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    let area = tel26_add_area(current_human_display(), [0x64, 0x22b, 0x316, 0x24e, 2, weights.as_ptr() as u32, 1, 0, 1, 0, u32::MAX]);
    text(JOB_TEXT, 0x98e8cc);
    tel26_area_button([area, 0, 0, 0x30, tel35_colour(G_GUI_COLOUR_GREY), 0xc, 3, tel35_colour(G_GUI_COLOUR_PALE_GREY), JOB_TEXT as u32, 1, 0]);
    text(JOB_TEXT, 0x98e8d0);
    tel26_area_button([area, 1, 0, 0x30, tel35_colour(G_GUI_COLOUR_GREY), 0xc, 3, tel35_colour(G_GUI_COLOUR_PALE_GREY), JOB_TEXT as u32, 2, 0]);
}

/// Rule: the retire screen opens for the current human manager.
///
/// `open_retire_screen()`: `open_screen` with the builder 0x6b28d0, the handler 0x6b2b40, single instance, no leave
/// routine.
/// Original: `open_retire_screen` (0x6b28b0, manager_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn open_retire_screen() {
    covered!("tel35_3 open retire");
    exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x6b28d0usize, 0x6b2b40usize, 1, 0usize, 0);
}

/// Rule: the retire screen asks the human manager to confirm resigning his club and national jobs and retiring.
///
/// `retire_screen_build()`: the slot's manager; the background of his club, national team or a random one; the menu bar
/// (4, 0); the title (his name, `database_format_staff_name` 2000 bytes, style 1) in the kit colours (kit 1) of his
/// club (or national team), or in the heading colours 0 and 1 with neither; the subtitle "Please Confirm"; the question
/// with both jobs ("{}<club>{} and {}<nation>{}", their names +0x38 and gender chars +0x52), only the club, only the
/// nation (name +4, gender char +0x37) or "Retire from football ?", as a text area (0x6e, 0x91)-(0x30c, 0x217); No and
/// Yes.
/// Original: `retire_screen_build` (0x6b28d0, manager_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn retire_screen_build() {
    let text: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    covered!("tel35_3 retire");
    let weights: [u8; 2] = [3, 1];
    let manager = tel26_slot_manager().addr();
    manager_job_background(manager);
    exe::menubar_build(4, 0);
    let (mut fore, mut back) = (0u32, 0u32);
    let team = if read_usize(manager + staff::CLUB_JOB) != 0 { read_usize(manager + staff::CLUB_JOB) } else { read_usize(manager + staff::NATIONAL_JOB) };
    if team != 0 {
        exe::database_get_club_kit_colours(team, 1, &mut fore, &mut back);
    } else {
        fore = exe::get_heading_colour(1) as u32;
        back = exe::get_heading_colour(0) as u32;
    }
    exe::database_format_staff_name(manager, JOB_TEXT, 0x7d0, 1);
    exe::screenmanager_add_screen_title(G_SCREEN_MANAGER, back & 0xffff, fore & 0xffff, JOB_TEXT);
    text(JOB_TEXT, 0x9909b8);
    exe::screenmanager_add_screen_subtitle(G_SCREEN_MANAGER, JOB_TEXT, 1);
    let club = read_usize(manager + staff::CLUB_JOB);
    let nation = read_usize(manager + staff::NATIONAL_JOB);
    let gender = |t: usize, at: usize| read_u8(t + at) as i8 as i32;
    if club != 0 && nation != 0 {
        text(JOB_TEXT, 0xa15590, gender(club, 0x52), gender(club, 0x52), gender(nation, 0x52), gender(nation, 0x52), club + 0x38, nation + 0x38);
    } else if club != 0 {
        text(JOB_TEXT, 0xa15550, gender(club, 0x37), gender(club, 0x37), club + 4);
    } else if nation != 0 {
        text(JOB_TEXT, 0xa1550c, gender(nation, 0x37), gender(nation, 0x37), nation + 4);
    } else {
        text(JOB_TEXT, 0xa154f4);
    }
    tel26_text_area([0x6e, 0x91, 0x30c, 0x217, 2, 0, 0x10, 4, tel35_colour(G_GUI_COLOUR_PALE_GREY), JOB_TEXT as u32, 0]);
    manager_no_yes(&weights);
}

/// Rule: confirming the retirement takes the manager out of his jobs and out of the game.
///
/// `retire_screen_handle_action(item)`: id 1 (No) -9. Id 2 (Yes), the slot's manager: his club (when he has one) loses
/// its manager (`MANAGER_MANAGER::remove_club_manager` departure 3), the match day's human interest refreshed, the
/// vacancy opened with him as the previous manager and the club's transfer offers cancelled; the same for his national
/// team (without the offers); his inbox cleared, holiday, reserve control and computer control off, his pending
/// offers, contract and loan contract removed, he leaves the national squads, his staff history rewound and his human
/// manager record cleared, his scouting lists cleared; his three names emptied, +0x5f = 0, the date at +0x10 set to
/// day 1 of 1966, +0x18 = 1966, no national (+0x24) or club (+0x39) job, and his screen record removed; -11. Otherwise
/// the menu bar.
/// Original: `retire_screen_handle_action` (0x6b2b40, manager_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn retire_screen_handle_action(raw: u32) -> i32 {
    match tel26_item_id(raw as i16) {
        1 => -9,
        2 => {
            covered!("tel35_3 retire confirmed");
            let manager = tel26_slot_manager().addr();
            let club = read_usize(manager + staff::CLUB_JOB);
            if club != 0 {
                exe::manager_manager_remove_club_manager(read_usize(G_MANAGER_MANAGER), club, 3, 0, 0);
                if read_usize(G_MATCH_DAY) != 0 {
                    exe::match_day_refresh_human_interest_flags(read_usize(G_MATCH_DAY));
                }
                exe::manager_manager_add_job_vacancy(read_usize(G_MANAGER_MANAGER), club, manager);
                exe::transfer_manager_cancel_club_offers(read_usize(G_TRANSFER_MANAGER), club);
            }
            let nation = read_usize(manager + staff::NATIONAL_JOB);
            if nation != 0 {
                exe::manager_manager_remove_club_manager(read_usize(G_MANAGER_MANAGER), nation, 3, 0, 0);
                if read_usize(G_MATCH_DAY) != 0 {
                    exe::match_day_refresh_human_interest_flags(read_usize(G_MATCH_DAY));
                }
                exe::manager_manager_add_job_vacancy(read_usize(G_MANAGER_MANAGER), nation, manager);
            }
            exe::news_clear_inbox(read_usize(G_NEWS), manager);
            exe::human_manager_set_on_holiday(read_usize(G_HUMAN_MANAGER), 0, manager);
            tel35_this2(0x5fd590, read_usize(G_HUMAN_MANAGER), 0, manager);
            tel35_this2(0x5fe140, read_usize(G_HUMAN_MANAGER), 0, manager);
            exe::contract_manager_remove_pending_offers_for_staff(read_usize(G_CONTRACT_MANAGER), manager);
            exe::contract_manager_remove_contract(read_usize(G_CONTRACT_MANAGER), manager);
            tel35_this1(0x4d0bd0, read_usize(G_CONTRACT_MANAGER), manager);
            tel35_this1(0x775ba0, read_usize(G_NATIONAL_TEAMS), manager);
            tel35_this1(0x86fb80, read_usize(G_STAFF_RECORDS), manager);
            tel35_this1(0x86fc70, read_usize(G_STAFF_RECORDS), manager);
            tel35_this1(0x7fc310, read_usize(G_SCOUT_MANAGER), manager);
            let first = read_usize(manager + staff::FIRST_NAME);
            write_u8(manager + staff::CLASSIFICATION, 0);
            write_u8(first, 0);
            write_u8(read_usize(manager + staff::SECOND_NAME), 0);
            write_u8(read_usize(manager + staff::COMMON_NAME), 0);
            exe::date_set(manager + staff::DATE_OF_BIRTH, 1, 0, 0x7ae, -1);
            write_u16(manager + staff::YEAR_OF_BIRTH, 0x7ae);
            write_u32(manager + staff::NATIONAL_JOB, 0);
            write_u32(manager + staff::CLUB_JOB, 0);
            exe::screenmanager_remove_manager_record(G_SCREEN_MANAGER, manager, -1);
            -11
        }
        _ => manager_menu_bar(raw),
    }
}

/// Rule: the holiday screen opens for the current human manager.
///
/// `open_holiday_screen()`: `open_screen` with the builder 0x6b2d80, the handler 0x6b3440, single instance, no leave
/// routine.
/// Original: `open_holiday_screen` (0x6b2d60, manager_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn open_holiday_screen() {
    covered!("tel35_3 open holiday");
    exe::screenmanager_open_screen(G_SCREEN_MANAGER, 0x6b2d80usize, 0x6b3440usize, 1, 0usize, 0);
}

/// The holiday settings, in order: the text, the link value, the (option, value) whose match lights the line, the rows
/// to skip before it. A value of -1 lights the line when the option is not 0.
const HOLIDAY_SETTINGS: [(usize, u32, (u32, i32), i32); 7] = [
    (0xa156c8, 0, (0, 1), 2), // "Reject all offers for players"
    (0xa156a0, 1, (0, 2), 1), // "Reject all offers below asking price"
    (0xa15688, 2, (4, 1), 1), // "Do not buy any players"
    (0xa15668, 3, (4, 2), 1), // "Only buy players from shortlist"
    (0xa15630, 4, (1, -1), 2), // "Apply for manager position at higher reputation clubs"
    (0xa15614, 5, (2, -1), 1), // "Use current match tactics"
    (0xa155e8, 6, (3, -1), 1), // "Use current team selection when possible"
];

/// Rule: the holiday screen asks to confirm going on holiday and shows the holiday settings, the ones on in pale grey.
///
/// `holiday_screen_build()`: a local Text; the slot's manager; the background of his club, national team or a random
/// one; the menu bar (4, 0); the title (his name) in the heading colours 0 and 1; the subtitle "Please Confirm" (0);
/// the area (0x6e, 0x91)-(0x30c, 0x217) (kind 2); "Go on holiday ?" (font 4); the settings area (0x82, 0xfa)-(0x2f8,
/// 0x217), one column, 0x122 / the height of font 3 rows, kind 1, with "Settings" at row 0 and each setting
/// (`HOLIDAY_SETTINGS`: a Text with the link 3 of its value) drawn wrapped from 0x96 to 0x2f8, pale grey when on
/// (`HUMAN_MANAGER::get_holiday_option`) and grey when off, rows skipped as the table says; No and Yes.
/// Original: `holiday_screen_build` (0x6b2d80, manager_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn holiday_screen_build() {
    let text: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    covered!("tel35_3 holiday");
    let weights: [u8; 2] = [3, 1];
    let mut tx = [0u32; 8];
    let t = tx.as_mut_ptr() as usize;
    exe::new_text(tx.as_mut_ptr() as *mut usize, 0usize);
    let manager = tel26_slot_manager().addr();
    manager_job_background(manager);
    exe::menubar_build(4, 0);
    exe::database_format_staff_name(manager, JOB_TEXT, 0x7d0, 1);
    let fore = exe::get_heading_colour(1) as u32;
    let back = exe::get_heading_colour(0) as u32;
    exe::screenmanager_add_screen_title(G_SCREEN_MANAGER, back, fore, JOB_TEXT);
    text(JOB_TEXT, 0x9909b8);
    exe::screenmanager_add_screen_subtitle(G_SCREEN_MANAGER, JOB_TEXT, 0);
    tel26_add_area(current_human_display(), [0x6e, 0x91, 0x30c, 0x217, 1, 0, 1, 0, 2, 0, u32::MAX]);
    text(JOB_TEXT, 0xa156f4);
    let pale = tel35_colour(G_GUI_COLOUR_PALE_GREY);
    tel35_text_item([0x6e, 0xa5, 0x30c, 0xc8, 1, 0, 0xc, 4, pale, JOB_TEXT as u32, 1]);
    let rows = (0x122 / exe::font_get_height(3)) as u8 as u32;
    let area = tel26_add_area(current_human_display(), [0x82, 0xfa, 0x2f8, 0x217, 1, 0, rows, 0, 1, 0, u32::MAX]);
    let mut line = 0i32;
    text(JOB_TEXT, 0xa156e8);
    tel26_area_text([area, 0, line as u32, 1, 0, 1, 3, pale, JOB_TEXT as u32]);
    for (label, link, (option, value), skip) in HOLIDAY_SETTINGS {
        line += skip;
        text(JOB_TEXT, label);
        exe::text_set_string(t, JOB_TEXT as *const u8);
        exe::text_add_link(t, JOB_TEXT as *const u8, 3, link as usize);
        let current = holiday_option(option);
        let on = if value == -1 { current != 0 } else { current as i32 == value };
        let colour = if on { pale } else { tel35_colour(G_GUI_COLOUR_GREY) };
        tel35_text_draw_wrapped(t, area, 0x96, 0x2f8, &mut line, 3, colour, 2, 0);
        tel35_this1(0x4afa40, t, 0);
    }
    manager_no_yes(&weights);
    exe::drop_text(tx.as_mut_ptr() as *mut usize);
}

/// Rule: on the holiday screen No and Yes leave with the holiday answer pending, and a setting click switches it.
///
/// `holiday_screen_handle_action(item)`: id 1 (No): the pending command 8 with 1, -9. Id 2 (Yes): the pending command 8
/// with 2; options 2 and 3 written back with their own values (`set_holiday_option`); -9. Id 3 (a setting), its value
/// k (the low byte of the widget's data): 0 sets option 0 to 1, or to 0 when it was 1; 1 sets option 0 to 2, or 0 when
/// it was 2; 2 and 3 the same with option 4; 4, 5 and 6 switch options 1, 2 and 3 (0 becomes 1, anything else 0); any
/// other value changes nothing; -11. Otherwise the menu bar.
/// Original: `holiday_screen_handle_action` (0x6b3440, manager_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn holiday_screen_handle_action(raw: u32) -> i32 {
    let item = raw as i16;
    match tel26_item_id(item) {
        1 => {
            write_u32(G_PENDING_COMMAND_CODE, 8);
            write_u32(G_PENDING_COMMAND_ARG, 1);
            -9
        }
        2 => {
            covered!("tel35_3 holiday confirmed");
            write_u32(G_PENDING_COMMAND_CODE, 8);
            write_u32(G_PENDING_COMMAND_ARG, 2);
            set_holiday_option(2, holiday_option(2) as i8 as i32);
            set_holiday_option(3, holiday_option(3) as i8 as i32);
            -9
        }
        3 => {
            covered!("tel35_3 holiday setting");
            let k = tel26_item_value(item) as u8 as i8 as i32;
            let pick = |option: u32, value: i32| set_holiday_option(option, if holiday_option(option) as i32 == value { 0 } else { value });
            let switch = |option: u32| set_holiday_option(option, (holiday_option(option) == 0) as i32);
            match k {
                0 => pick(0, 1),
                1 => pick(0, 2),
                2 => pick(4, 1),
                3 => pick(4, 2),
                4 => switch(1),
                5 => switch(2),
                6 => switch(3),
                _ => {}
            }
            -11
        }
        _ => manager_menu_bar(raw),
    }
}

/// The reputation and age test of the manager stats order: a reputation below `MANAGER_STATS_UNKNOWN_BELOW` counts as
/// -1 for a person under 35 (one of the last 16 staff: with fewer than 50 games).
unsafe fn manager_stats_order_reputation(row: usize, person: usize, id: i32, reputation: i16) -> i16 {
    if reputation >= MANAGER_STATS_UNKNOWN_BELOW {
        return reputation;
    }
    let limit = read_i32(G_STAFF_COUNT) - 0x10;
    let unknown = if id < limit { read_i8(person + staff::AGE) < 0x23 } else { read_i16(row + 0x8e) < 0x32 };
    if unknown { -1 } else { reputation }
}

/// The days since a date of a manager record (`Date::days_since`, the date at `at` by value, from `this`).
unsafe fn manager_stats_days(this: usize, at: usize) -> i32 {
    exe::date_days_since(this, read_u32(at), read_u32(at + 4))
}

/// The win share of a manager record: 100 × wins (+0x90) / games (+0x8e) times the games (at most 100); -1 without
/// games.
unsafe fn manager_stats_win_score(row: usize) -> i32 {
    let games = read_i16(row + 0x8e);
    if games == 0 {
        return -1;
    }
    let share = (read_i16(row + 0x90) as i32 * 100) / games as i32;
    let weight = if games >= 0x64 { 0x64 } else { games as i32 };
    weight.wrapping_mul(share)
}

/// Rule: the Manager Stats list is ordered by the chosen statistic, the best first, and then by name.
///
/// `compare_manager_stats_rows(a, b)` (qsort, 210-byte manager records; +0x86 the staff id): a null a: 1; a null b: -1;
/// a person without his stats block (+0x69 of the staff record): 1 for a, -1 for b. By the statistic
/// (`MANAGER_STATS_SORT_STAT`), b minus a: 1 the reputation (+0xc of the stats block with no nation filter, +0xa with
/// one; `manager_stats_order_reputation`); 2 the money (+0xb6, or with a nation filter the two job amounts +0xba/+0xbe
/// whose nations +0xc2/+0xc6 are the filter); 3 the days in the club job (`staff::CLUB_JOB` and the date +0x3e,
/// `Date::days_since` from today); 4 the bytes +0xb5 and +0xb4; 5 the days since +0x6a's date (when +0x5e is set);
/// 6 the same with +0x7e/+0x72, a minus b; 7, 8, 9, 11, 12 the words +0x8a, +0x8c, +0x9e, +0xa0, +0xa2; 10 the win score
/// (`manager_stats_win_score`); 13, 14 the dwords +0x18, +0x3d; 15, 16 the 64-bit amounts +0xa4, +0xac (1 or -1); any
/// other statistic returns the address of a's staff record (a defect kept). A tie: the names (style 3, 200 bytes)
/// compared (`utils_string_compare`, 1).
/// Original: `compare_manager_stats_rows` (0x6b36f0, manager_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_manager_stats_rows(a: *const usize, b: *const usize) -> i32 {
    let (a, b) = (a as usize, b as usize);
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    let staff_table = read_usize(G_STAFF_TABLE);
    let id_a = read_i32(a + 0x86);
    let pa = staff_table.wrapping_add((id_a as u32).wrapping_mul(staff::SIZE as u32) as usize);
    let sa = read_usize(pa + staff::NON_PLAYER);
    if sa == 0 {
        return 1;
    }
    let id_b = read_i32(b + 0x86);
    let pb = staff_table.wrapping_add((id_b as u32).wrapping_mul(staff::SIZE as u32) as usize);
    let sb = read_usize(pb + staff::NON_PLAYER);
    if sb == 0 {
        return -1;
    }
    let nation = read_i32(MANAGER_STATS_SORT_NATION);
    let wide = |at: usize| ((read_u32(b + at + 4) as i32 as i64) << 32 | read_u32(b + at) as i64)
        .cmp(&((read_u32(a + at + 4) as i32 as i64) << 32 | read_u32(a + at) as i64));
    let d = match read_u8(MANAGER_STATS_SORT_STAT) {
        1 => {
            let at = if nation == -1 { 0xc } else { 0xa };
            let ra = manager_stats_order_reputation(a, pa, id_a, read_i16(sa + at));
            let rb = manager_stats_order_reputation(b, pb, id_b, read_i16(sb + at));
            rb as i32 - ra as i32
        }
        2 => {
            if nation == -1 {
                read_i32(b + 0xb6).wrapping_sub(read_i32(a + 0xb6))
            } else {
                let mut d = 0i32;
                if read_i32(b + 0xc2) == nation {
                    d = read_i32(b + 0xba);
                }
                if read_i32(b + 0xc6) == nation {
                    d = d.wrapping_add(read_i32(b + 0xbe));
                }
                if read_i32(a + 0xc2) == nation {
                    d = d.wrapping_sub(read_i32(a + 0xba));
                }
                if read_i32(a + 0xc6) == nation {
                    d = d.wrapping_sub(read_i32(a + 0xbe));
                }
                d
            }
        }
        3 => {
            let mut d = 0i32;
            if read_usize(pb + staff::CLUB_JOB) != 0 {
                d = manager_stats_days(G_CURRENT_DATE, pb + 0x3e);
            }
            if read_usize(pa + staff::CLUB_JOB) != 0 {
                d = d.wrapping_sub(manager_stats_days(G_CURRENT_DATE, pa + 0x3e));
            }
            d
        }
        4 => (read_u8(b + 0xb5) as i32 - read_u8(a + 0xb5) as i32 - read_u8(a + 0xb4) as i32 + read_u8(b + 0xb4) as i32),
        5 => {
            let mut d = 0i32;
            if read_i32(b + 0x5e) > -1 {
                d = manager_stats_days(b + 0x6a, b + 0x62);
            }
            if read_i32(a + 0x5e) > -1 {
                d = d.wrapping_sub(manager_stats_days(a + 0x6a, a + 0x62));
            }
            d
        }
        6 => {
            let mut d = 0i32;
            if read_i32(b + 0x72) > -1 {
                d = manager_stats_days(b + 0x7e, b + 0x76).wrapping_neg();
            }
            if read_i32(a + 0x72) > -1 {
                d = d.wrapping_add(manager_stats_days(a + 0x7e, a + 0x76));
            }
            d
        }
        7 => read_i16(b + 0x8a) as i32 - read_i16(a + 0x8a) as i32,
        8 => read_i16(b + 0x8c) as i32 - read_i16(a + 0x8c) as i32,
        9 => read_i16(b + 0x9e) as i32 - read_i16(a + 0x9e) as i32,
        0xa => manager_stats_win_score(b).wrapping_sub(manager_stats_win_score(a)),
        0xb => read_i16(b + 0xa0) as i32 - read_i16(a + 0xa0) as i32,
        0xc => read_i16(b + 0xa2) as i32 - read_i16(a + 0xa2) as i32,
        0xd => read_i32(b + 0x18).wrapping_sub(read_i32(a + 0x18)),
        0xe => read_i32(b + 0x3d).wrapping_sub(read_i32(a + 0x3d)),
        0xf => wide(0xa4) as i32,
        0x10 => wide(0xac) as i32,
        _ => pa as i32,
    };
    if d != 0 {
        return d;
    }
    covered!("tel35_3 manager stats name order");
    let (mut name_a, mut name_b) = ([0u8; 200], [0u8; 200]);
    exe::database_format_staff_name(pa, name_a.as_mut_ptr() as usize, 0xc8, 3);
    let pb = read_usize(G_STAFF_TABLE).wrapping_add((read_u32(b + 0x86)).wrapping_mul(staff::SIZE as u32) as usize);
    exe::database_format_staff_name(pb, name_b.as_mut_ptr() as usize, 0xc8, 3);
    exe::utils_string_compare(name_a.as_ptr(), name_b.as_ptr(), 1, 0)
}

/// Rule: the job information list is ordered by the word +8 of its 10-byte rows.
///
/// `compare_job_information_rows(a, b)` (qsort): a null a: 1; a null b: -1; otherwise the word +8 of a minus that of
/// b, as a signed word.
/// Original: `compare_job_information_rows` (0x6b3be0, manager_screens.cpp, cdecl).
pub(crate) unsafe extern "C" fn compare_job_information_rows(a: *const usize, b: *const usize) -> i32 {
    let (a, b) = (a as usize, b as usize);
    if a == 0 {
        return 1;
    }
    if b == 0 {
        return -1;
    }
    read_u16(a + 8).wrapping_sub(read_u16(b + 8)) as i16 as i32
}

