/// Rule: the row an area of the current screen shows; for a remote manager, the row he last reported for that area.
///
/// The record of the current slot (`screen_record`, tel29_1): when it is local (`screen_history::NETWORK_PLAYER` = 0),
/// area −1 gives 0 and any other area (its low word, signed) of the slot's `Display` (`screen_manager::DISPLAY`) gives
/// `Area::get_shown_row` (0x4032e0, thiscall). When it is remote, the reported row (`SCREEN_KEY_DATA`) when the area is
/// the reported one (`SCREEN_KEY`), otherwise 0.
/// Original: `ScreenManager::get_area_scroll_row` (0x803320, scrman.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn screen_manager_get_area_scroll_row(sm: usize, area: u32) -> u32 {
    let rec = screen_record(sm);
    if read_u16(rec + screen_history::NETWORK_PLAYER) == 0 {
        if area as u16 == 0xffff {
            return 0;
        }
        let shown_row: unsafe extern "thiscall" fn(usize) -> u32 = core::mem::transmute(0x4032e0usize);
        return shown_row(display_area_at(read_usize(rec + screen_manager::DISPLAY), area as i16));
    }
    covered!("tel38_1 remote scroll row");
    if area as u16 == read_u16(rec + screen_history::SCREEN_KEY) {
        return read_u32(rec + screen_history::SCREEN_KEY_DATA);
    }
    0
}

compare_value!(compare_screen_manager_get_area_scroll_row, screen_manager_get_area_scroll_row, IDX_SCREEN_MANAGER_GET_AREA_SCROLL_ROW, (area: u32) -> u32);

/// The mouse globals `Display::press_scrollbar_key` (0x5621f0) writes: the y (0xb67a14), the x (0xb67a20), the left button
/// (`G_MOUSE_LEFT_BUTTON_DOWN`) and the key (0xb67a3c).
const SCROLLBAR_KEY_MOUSE: usize = 0xb67a14;

/// Rule: a scrollbar key of the current screen is pressed as a click on the open scrollbar.
///
/// `Display::press_scrollbar_key(key, held)` (0x5621f0, thiscall, ret 8) of the current slot's `Display`, with both
/// arguments: with an open scrollbar (`G_ACTIVE_AREA_SCROLLBAR`) it fakes a left click on the arrow or the track the key
/// names (0..3).
/// Original: `ScreenManager::press_scrollbar_key` (0x803390, scrman.cpp, thiscall, ret 8).
pub(crate) unsafe extern "thiscall" fn screen_manager_press_scrollbar_key(sm: usize, key: u32, held: u32) {
    covered!("tel38_1 scrollbar key");
    let press: unsafe extern "thiscall" fn(usize, u32, u32) = core::mem::transmute(0x5621f0usize);
    press(screens_current_display(sm), key, held);
}

/// Comparer for `screen_manager_press_scrollbar_key`: side by side over the mouse globals.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_press_scrollbar_key(sm: usize, key: u32, held: u32) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32, u32)>(IDX_SCREEN_MANAGER_PRESS_SCROLLBAR_KEY);
    let (_, _, equal, mo, mr) = crate::comparison::side_by_side_light(&[(SCROLLBAR_KEY_MOUSE, 0x2c)], || o(sm, key, held),
        || screen_manager_press_scrollbar_key(sm, key, held));
    SCOREBOARD.record(equal, || format!("screen_manager_press_scrollbar_key({}, {}): differences in {:?}", key, held, first_differences(&mo, &mr)));
}

/// Rule: how many manager records there are in all channels.
///
/// The sum of the 16 channel record counts (`screen_history::CHANNEL_RECORD_COUNTS`), as a 16-bit word (the original
/// keeps garbage in the high word; the callers read the short).
/// Original: `ScreenManager::count_all_records` (0x8033c0, scrman.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn screen_manager_count_all_records(sm: usize) -> u16 {
    (0..16).fold(0u16, |s, c| s.wrapping_add(read_u16(sm + screen_history::CHANNEL_RECORD_COUNTS + 2 * c))) // tel38_1: all 16 channels
}

compare_value!(compare_screen_manager_count_all_records, screen_manager_count_all_records, IDX_SCREEN_MANAGER_COUNT_ALL_RECORDS, () -> u16);

/// Rule: how many single-instance screens are open in all records of all channels.
///
/// The sum of the flagged screen counts (`screen_history::FLAGGED_COUNT`) of the 16 records of each of the 16 channels,
/// as a 16-bit word (the callers read the short).
/// Original: `ScreenManager::count_flagged_screens` (0x803d50, scrman.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn screen_manager_count_flagged_screens(sm: usize) -> u16 {
    (0..256).fold(0u16, |s, k| s.wrapping_add(read_u16(sm + screen_history::FLAGGED_COUNT + k * screen_history::RECORD_SIZE)))
}

compare_value!(compare_screen_manager_count_flagged_screens, screen_manager_count_flagged_screens, IDX_SCREEN_MANAGER_COUNT_FLAGGED_SCREENS, () -> u16);

// ---------- batch 318: the screen manager's manager records: a channel's keys, the away and done flags by key, the idle channels, a manager's channel, swapping and switching managers and ending the network session (scrman.cpp) ----------

/// The record `k` of channel `c` (16 records of `screen_history::RECORD_SIZE` per channel; offsets from the manager,
/// as `screen_history`).
fn scrman_channel_record(sm: usize, c: i16, k: i16) -> usize {
    (sm as isize + (c as isize * 16 + k as isize) * screen_history::RECORD_SIZE as isize) as usize
}

/// The record count of channel `c` (`screen_history::CHANNEL_RECORD_COUNTS`, a signed word).
unsafe fn scrman_channel_count(sm: usize, c: i16) -> i16 {
    read_i16((sm as isize + screen_history::CHANNEL_RECORD_COUNTS as isize + c as isize * 2) as usize)
}

/// The first record of any channel whose manager key (`screen_history::KEY`) is `key`: channels 0..15, records in
/// order; none: `None`.
unsafe fn scrman_find_record(sm: usize, key: u32) -> Option<usize> {
    for c in 0..16i16 {
        let n = scrman_channel_count(sm, c);
        for k in 0..n.max(0) {
            let rec = scrman_channel_record(sm, c, k);
            if read_u32(rec + screen_history::KEY) == key {
                return Some(rec);
            }
        }
    }
    None
}

/// Rule: the manager keys of a channel's records, and how many there are.
///
/// The record count of `channel` (its low word, signed) is written to the word at `count_out`; then, while the index is
/// below that word (read again each time), the key (`screen_history::KEY`) of each record goes to the dword array at
/// `keys_out`. Returns how many keys were written (0 with no records).
/// Original: `ScreenManager::get_channel_manager_keys` (0x7ffd80, scrman.cpp, thiscall, ret 0xc).
pub(crate) unsafe extern "thiscall" fn screen_manager_get_channel_manager_keys(sm: usize, keys_out: usize, count_out: usize, channel: u32) -> u32 {
    let c = channel as i16;
    let n = scrman_channel_count(sm, c);
    write_i16(count_out, n);
    if n <= 0 {
        return 0;
    }
    let mut k: u32 = 0;
    loop {
        write_u32(keys_out + 4 * k as usize, read_u32(scrman_channel_record(sm, c, k as i16) + screen_history::KEY));
        k += 1;
        if k as i16 >= read_i16(count_out) {
            return k;
        }
    }
}

/// Comparer for `screen_manager_get_channel_manager_keys`: side by side over the count and the keys written, and the
/// return.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_get_channel_manager_keys(sm: usize, keys_out: usize, count_out: usize, channel: u32) -> u32 {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, usize, usize, u32) -> u32>(IDX_SCREEN_MANAGER_GET_CHANNEL_MANAGER_KEYS);
    let n = scrman_channel_count(sm, channel as i16).clamp(0, 16) as usize;
    let regions = [(count_out, 2), (keys_out, 4 * n)];
    let (ro, rr, equal, mo, mr) = crate::comparison::side_by_side_light(&regions[..if n > 0 { 2 } else { 1 }], || o(sm, keys_out, count_out, channel),
        || screen_manager_get_channel_manager_keys(sm, keys_out, count_out, channel));
    SCOREBOARD.record(equal && ro == rr, || format!("screen_manager_get_channel_manager_keys({}): return {} x {}, differences in {:?}", channel as i16, ro, rr, first_differences(&mo, &mr)));
    ro
}

/// Rule: whether the manager with this key is away; a manager with no record counts as away.
///
/// The away flag (`screen_history::AWAY`, the whole dword) of the first record with the key (`scrman_find_record`), or
/// 1 when there is none.
/// Original: `ScreenManager::is_manager_away` (0x7ffdd0, scrman.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn screen_manager_is_manager_away(sm: usize, key: u32) -> u32 {
    match scrman_find_record(sm, key) {
        Some(rec) => read_u32(rec + screen_history::AWAY),
        None => 1, // tel38_2: no record counts as away
    }
}

compare_value!(compare_screen_manager_is_manager_away, screen_manager_is_manager_away, IDX_SCREEN_MANAGER_IS_MANAGER_AWAY, (key: u32) -> u32);

/// Rule: whether the manager with this key is done for the day; a manager with no record counts as done.
///
/// The done flag (`screen_history::DONE`, the whole dword) of the first record with the key, or 1 when there is none.
/// Original: `ScreenManager::is_manager_done` (0x7ffe40, scrman.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn screen_manager_is_manager_done(sm: usize, key: u32) -> u32 {
    match scrman_find_record(sm, key) {
        Some(rec) => read_u32(rec + screen_history::DONE),
        None => 1, // tel38_2: no record counts as done
    }
}

compare_value!(compare_screen_manager_is_manager_done, screen_manager_is_manager_done, IDX_SCREEN_MANAGER_IS_MANAGER_DONE, (key: u32) -> u32);

/// Rule: marks the manager with this key as done (or not) for the day.
///
/// The done flag (`screen_history::DONE`) of the first record with the key gets `done`; nothing when there is none.
/// Original: `ScreenManager::set_manager_done` (0x7ffeb0, scrman.cpp, thiscall, ret 8).
pub(crate) unsafe extern "thiscall" fn screen_manager_set_manager_done(sm: usize, key: u32, done: u32) {
    if let Some(rec) = scrman_find_record(sm, key) {
        covered!("tel38_2 manager done set");
        write_u32(rec + screen_history::DONE, done);
    }
}

/// Comparer for `screen_manager_set_manager_done`: side by side over the 16 channels of records.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_set_manager_done(sm: usize, key: u32, done: u32) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32, u32)>(IDX_SCREEN_MANAGER_SET_MANAGER_DONE);
    let (_, _, equal, mo, mr) = crate::comparison::side_by_side(&[(sm + screen_history::NETWORK_PLAYER, 16 * screen_history::CHANNEL_SIZE)],
        || o(sm, key, done), || screen_manager_set_manager_done(sm, key, done));
    SCOREBOARD.record(equal, || format!("screen_manager_set_manager_done({:#x}, {}): differences in {:?}", key, done, first_differences(&mo, &mr)));
}

/// Rule: whether a network player is done: 0 as soon as one channel with records whose first record is his
/// (`screen_history::NETWORK_PLAYER`, the low word of `player`) is not done (`DONE` = 0); otherwise 1.
/// Original: `ScreenManager::is_player_done` (0x7fff20, scrman.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn screen_manager_is_player_done(sm: usize, player: u32) -> u32 {
    for c in 0..16i16 {
        if scrman_channel_count(sm, c) > 0 {
            let rec = scrman_channel_record(sm, c, 0);
            if read_u16(rec + screen_history::NETWORK_PLAYER) == player as u16 && read_u32(rec + screen_history::DONE) == 0 {
                return 0;
            }
        }
    }
    1
}

compare_value!(compare_screen_manager_is_player_done, screen_manager_is_player_done, IDX_SCREEN_MANAGER_IS_PLAYER_DONE, (player: u32) -> u32);

/// Rule: how many channels are idle: with no records, or whose first record is away (`screen_history::AWAY` ≠ 0).
/// Original: `ScreenManager::count_idle_channels` (0x7fff70, scrman.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn screen_manager_count_idle_channels(sm: usize) -> u32 {
    (0..16i16).filter(|&c| scrman_channel_count(sm, c) <= 0 || read_u32(scrman_channel_record(sm, c, 0) + screen_history::AWAY) != 0).count() as u32
}

compare_value!(compare_screen_manager_count_idle_channels, screen_manager_count_idle_channels, IDX_SCREEN_MANAGER_COUNT_IDLE_CHANNELS, () -> u32);

/// Rule: the channel of the manager with this key, or −1 when there is none or the key is 0.
///
/// Channels 0..15, records in order: the first channel holding a record with the key (`screen_history::KEY`); −1
/// otherwise and for key 0. A short (the original leaves the caller's high word in eax for key 0).
/// Original: `ScreenManager::find_manager_channel` (0x7fffa0, scrman.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn screen_manager_find_manager_channel(sm: usize, key: u32) -> i16 {
    if key == 0 {
        return -1;
    }
    for c in 0..16i16 {
        for k in 0..scrman_channel_count(sm, c).max(0) {
            if read_u32(scrman_channel_record(sm, c, k) + screen_history::KEY) == key {
                return c;
            }
        }
    }
    -1
}

compare_value!(compare_screen_manager_find_manager_channel, screen_manager_find_manager_channel, IDX_SCREEN_MANAGER_FIND_MANAGER_CHANNEL, (key: u32) -> i16);

/// Rule: two managers of the current channel swap their keys.
///
/// In the current channel (`screen_manager::CURRENT_SLOT`), records 0..count−1 (the count read once): the last one
/// with key `a` and the last one with key `b`. When both exist, their keys (`screen_history::KEY`) are swapped and the
/// result is 1; otherwise 0 and nothing changes.
/// Original: `ScreenManager::swap_manager_keys` (0x7ff810, scrman.cpp, thiscall, ret 8).
pub(crate) unsafe extern "thiscall" fn screen_manager_swap_manager_keys(sm: usize, a: u32, b: u32) -> u32 {
    let c = read_i16(sm + screen_manager::CURRENT_SLOT);
    let n = scrman_channel_count(sm, c);
    let (mut ia, mut ib) = (-1i16, -1i16);
    for k in 0..n.max(0) {
        let key = read_u32(scrman_channel_record(sm, c, k) + screen_history::KEY);
        if key == a {
            ia = k;
        }
        if key == b {
            ib = k;
        }
    }
    if ia <= -1 || ib <= -1 {
        return 0;
    }
    covered!("tel38_2 manager keys swapped");
    let ra = scrman_channel_record(sm, c, ia) + screen_history::KEY;
    let rb = scrman_channel_record(sm, c, ib) + screen_history::KEY;
    let key_a = read_u32(ra);
    write_u32(ra, read_u32(rb)); // tel38_2: the keys swapped
    write_u32(scrman_channel_record(sm, read_i16(sm + screen_manager::CURRENT_SLOT), ib) + screen_history::KEY, key_a);
    1
}

/// Comparer for `screen_manager_swap_manager_keys`: side by side over the current channel and the return.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_swap_manager_keys(sm: usize, a: u32, b: u32) -> u32 {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32, u32) -> u32>(IDX_SCREEN_MANAGER_SWAP_MANAGER_KEYS);
    let channel = screen_record(sm) + screen_history::NETWORK_PLAYER;
    let (ro, rr, equal, mo, mr) = crate::comparison::side_by_side(&[(channel, screen_history::CHANNEL_SIZE)], || o(sm, a, b),
        || screen_manager_swap_manager_keys(sm, a, b));
    SCOREBOARD.record(equal && ro == rr, || format!("screen_manager_swap_manager_keys({:#x}, {:#x}): return {} x {}, differences in {:?}", a, b, ro, rr, first_differences(&mo, &mr)));
    ro
}

/// Rule: the manager with this key becomes the current one of his channel, when he is neither away nor done.
///
/// In the current channel, the first record with the key (`screen_history::KEY`); none, or the record away (`AWAY`) or
/// done (`DONE`): nothing. Otherwise, when it is not record 0, it swaps places with record 0 (`exe::utils_swap_bytes`,
/// 0x30 bytes), and record 0's `ACTIVE_FLAG` = 1.
/// Original: `ScreenManager::switch_to_manager` (0x7ffcd0, scrman.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn screen_manager_switch_to_manager(sm: usize, key: u32) {
    use screen_history as h;
    let c = read_i16(sm + screen_manager::CURRENT_SLOT);
    let n = scrman_channel_count(sm, c);
    let mut k = 0i16;
    while k < n && read_u32(scrman_channel_record(sm, c, k) + h::KEY) != key {
        k += 1;
    }
    if k >= n {
        return;
    }
    let rec = scrman_channel_record(sm, c, k);
    if read_u32(rec + h::AWAY) != 0 || read_u32(rec + h::DONE) != 0 { // tel38_2: away or done managers stay put
        return;
    }
    if k != 0 {
        covered!("tel38_2 manager switched in");
        let first = scrman_channel_record(sm, c, 0) + h::NETWORK_PLAYER;
        exe::utils_swap_bytes((rec + h::NETWORK_PLAYER) as *mut i32, first as *mut i32, h::RECORD_SIZE as u32);
    }
    write_u32(screen_record(sm) + h::ACTIVE_FLAG, 1);
}

/// Comparer for `screen_manager_switch_to_manager`: side by side over the current channel.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_switch_to_manager(sm: usize, key: u32) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32)>(IDX_SCREEN_MANAGER_SWITCH_TO_MANAGER);
    let channel = screen_record(sm) + screen_history::NETWORK_PLAYER;
    let (_, _, equal, mo, mr) = crate::comparison::side_by_side(&[(channel, screen_history::CHANNEL_SIZE)], || o(sm, key),
        || screen_manager_switch_to_manager(sm, key));
    SCOREBOARD.record(equal, || format!("screen_manager_switch_to_manager({:#x}): differences in {:?}", key, first_differences(&mo, &mr)));
}

/// Rule: ends the network session, when there is one.
///
/// With a session (`screen_history::NETWORK`): 0x7fc690 (thiscall on the manager, the session's farewell [inference]),
/// then, when the session is still there, its destructor (0x77a890, thiscall) and operator delete; the session pointer
/// goes to 0.
/// Original: `ScreenManager::end_network_session` (0x7ff5f0, scrman.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn screen_manager_end_network_session(sm: usize) {
    use screen_history as h;
    if read_usize(sm + h::NETWORK) == 0 {
        return;
    }
    covered!("tel38_2 network session ended");
    let farewell: unsafe extern "thiscall" fn(usize) = core::mem::transmute(0x7fc690usize);
    farewell(sm);
    let net = read_usize(sm + h::NETWORK);
    if net != 0 {
        let destroy: unsafe extern "thiscall" fn(usize) = core::mem::transmute(0x77a890usize);
        destroy(net);
        exe::crt_operator_delete(net);
    }
    write_usize(sm + h::NETWORK, 0);
}

// simplification: closes and frees the session: it does not run twice. Original only; the plan: no session left.
/// Comparer for `screen_manager_end_network_session`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_end_network_session(sm: usize) {
    original_fn::<unsafe extern "thiscall" fn(usize)>(IDX_SCREEN_MANAGER_END_NETWORK_SESSION)(sm);
    let net = read_usize(sm + screen_history::NETWORK);
    SCOREBOARD.record(net == 0, || format!("screen_manager_end_network_session: session {:#x} left", net));
}

// ---------- batch 318: the Back/Next and page buttons and the widget object: its fields, highlight, text, images and colour format (gui_utils.cpp, Guio.cpp) ----------

/// More widget (`Guio`) fields than `display_item` (tel26_1) names: the item's own index, its three colours (words),
/// the text entry's target buffer and the cached text image.
mod guio_fields {
    pub(crate) const ENTRY_TARGET: usize = 0x54;
    pub(crate) const TEXT_IMAGE: usize = 0x5c;
    pub(crate) const INDEX: usize = 0x70;
    pub(crate) const COLOUR: usize = 0x72;
    pub(crate) const HIGHLIGHT_COLOUR: usize = 0x74;
    pub(crate) const TEXT_COLOUR: usize = 0x78;
}

/// The shared text image's name (a widget whose text is this name shares the image and only counts it down) and its
/// count (word) [inference].
const GUIO_SHARED_IMAGE_NAME: usize = 0xae2920;
const GUIO_SHARED_IMAGE_COUNT: usize = 0xae291c;
/// The game's scratch text (`0xde1f64`, 0x100 bytes used here) and the Display flag that lets a widget redraw at once
/// [inference].
const GUI_SCRATCH_TEXT: usize = 0xde1f64;
const DISPLAY_LIVE_REDRAW: usize = 0x12f545;

/// `restore_background(x, y, image)` (0x5e3fd0, cdecl): puts back the screen under a widget.
unsafe fn gui_restore_background(x: u32, y: u32, image: usize) {
    let f: unsafe extern "C" fn(u32, u32, usize) = core::mem::transmute(0x5e3fd0usize);
    f(x, y, image);
}

/// `update_screen_rect(x1, y1, x2, y2)` (0x5e2eb0, cdecl): shows a rectangle of the back buffer.
unsafe fn gui_update_rect(item: usize) {
    use display_item as d;
    let f: unsafe extern "C" fn(u32, u32, u32, u32) = core::mem::transmute(0x5e2eb0usize);
    f(read_u32(item + d::X1), read_u32(item + d::Y1), read_u32(item + d::X2), read_u32(item + d::Y2));
}

/// The display-list writes of a gui builder: what `screens_forwarder_regions` (tel01_1) covers, the next `areas` area
/// slots and `items` item slots, both draw orders (counts and next slots) and the scratch text.
unsafe fn gui_build_regions(areas: usize, items: usize) -> Vec<(usize, usize)> {
    use display_list as l;
    let mut r = screens_forwarder_regions(SCREEN_MANAGER);
    r.push((GUI_SCRATCH_TEXT, 0x100));
    let d = screens_current_display(SCREEN_MANAGER);
    if d == 0 {
        return r;
    }
    let a = read_i16(d + l::AREA_ORDER_COUNT);
    let n = read_i16(d + l::ITEM_ORDER_COUNT);
    r.push((d + l::AREA_ORDER_COUNT, 4));
    if (0..250 - areas as i16).contains(&a) {
        r.push((d + l::AREA_ORDER + a as usize * 2, areas * 2));
    }
    if (0..0x4b0 - items as i16).contains(&n) {
        r.push((d + l::ITEM_ORDER + n as usize * 2, items * 2));
    }
    let ac = read_i16(d + 0x12e99e);
    if (0..0xf9 - areas as i16).contains(&ac) {
        r.push((display_area_at(d, ac), areas * l::AREA_SIZE));
    }
    let ic = read_i16(d + l::ITEM_COUNT);
    if (0..0x4af - items as i16).contains(&ic) {
        r.push((display_item_at(d, ic), items * l::ITEM_SIZE));
    }
    r
}

/// Comparer of a gui builder: side by side over `gui_build_regions` and the return.
unsafe fn compare_gui_build(name: &str, areas: usize, items: usize, original: impl FnOnce() -> u32, rust: impl FnOnce() -> u32) -> u32 {
    let regions = gui_build_regions(areas, items);
    let (ro, rr, equal, mo, mr) = crate::comparison::side_by_side(&regions, original, rust);
    SCOREBOARD.record(equal && ro == rr, || format!("{}: return {:#x} x {:#x}, differences in {:?}", name, ro, rr, first_differences(&mo, &mr)));
    ro
}

/// Rule: the Back and Next buttons are a two-cell area at the bottom of the screen; a button that cannot be used is
/// shown as grey text instead.
///
/// An area on the current slot's `Display` (`Display::add_area`: (100, 555)–(790, 590), 2 cells, the cell layout
/// bytes {3, 1} of a local frame, 1, 0, 1, 0, no owner). In cell 0, "Back" (translated, `FN_LANGLIB_SPRINTF`): with
/// `back` an area button (`ScreenManager::add_area_button`: flags 0x30, `G_GUI_COLOUR_GREY`, font 0xc, style 3,
/// `G_GUI_COLOUR_PALE_GREY`, id −2, data 0), otherwise an area text in font 0x2c. In cell 1 the same with "Next" and id
/// −3. Returns 1. The colours go as words (the original's high halves are leftovers; `Guio::init` keeps words).
/// Original: `gui_add_back_next_buttons` (0x5edcc0, gui_utils.cpp, cdecl).
pub(crate) unsafe extern "C" fn gui_add_back_next_buttons(back: u32, next: u32) -> u32 {
    let add_area: DisplayAddAreaFn = core::mem::transmute(FN_DISPLAY_ADD_AREA);
    let button: unsafe extern "thiscall" fn(usize, u32, u32, u32, u32, u32, u32, u32, u32, usize, u32, u32) -> u16 =
        core::mem::transmute(FN_SCREENMANAGER_ADD_AREA_BUTTON);
    let text_item: unsafe extern "thiscall" fn(usize, u32, u32, u32, u32, u32, u32, u32, u32, usize) -> u16 =
        core::mem::transmute(FN_SCREENMANAGER_ADD_AREA_TEXT);
    let format: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    let mut frame = [0u8; 0x7d4];
    frame[..4].copy_from_slice(&[1, 1, 3, 1]);
    let layout = frame.as_ptr() as usize + 2;
    let text = frame.as_mut_ptr() as usize + 4;
    let area = add_area(screens_current_display(SCREEN_MANAGER), 0x64, 0x22b, 0x316, 0x24e, 2, layout as u32, 1, 0, 1, 0, u32::MAX);
    let grey = read_u16(G_GUI_COLOUR_GREY) as u32;
    let pale = read_u16(G_GUI_COLOUR_PALE_GREY) as u32;
    for (cell, label, enabled, id) in [(0u32, 0x9880a8usize, back, -2i32), (1, 0x9880a0, next, -3)] {
        format(text, label);
        if enabled != 0 {
            button(SCREEN_MANAGER, area, cell, 0, 0x30, grey, 0xc, 3, pale, text, id as u32, 0); // tel38_3: the usable button
        } else {
            covered!("tel38_3 back or next greyed");
            text_item(SCREEN_MANAGER, area, cell, 0, 0x30, grey, 0x2c, 3, pale, text);
        }
    }
    1
}

/// Comparer for `gui_add_back_next_buttons`: side by side over the display list (one area, two items) and the return.
pub(crate) unsafe extern "C" fn compare_gui_add_back_next_buttons(back: u32, next: u32) -> u32 {
    let o = original_fn::<unsafe extern "C" fn(u32, u32) -> u32>(IDX_GUI_ADD_BACK_NEXT_BUTTONS);
    compare_gui_build("gui_add_back_next_buttons", 1, 2, || o(back, next), || gui_add_back_next_buttons(back, next))
}

/// One page button of `gui_add_page_buttons`: 0x14 × 0x14 with its right edge at `right`, at `y`; with the symbol font
/// (`G_FONT_MODE` ≠ −1) the symbol `code` ("%c" into the scratch text, style 0), otherwise the text `plain` (style 1).
unsafe fn gui_page_button(right: i32, y: i32, code: u32, plain: usize, id: u32) {
    let button: unsafe extern "thiscall" fn(usize, i32, i32, i32, i32, u32, u32, u32, u32, u32, usize, u32, u32) -> u16 =
        core::mem::transmute(FN_SCREENMANAGER_ADD_BUTTON_ITEM);
    let (text, style) = if read_i32(G_FONT_MODE) != -1 {
        let format: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_CRT_SPRINTF);
        format(GUI_SCRATCH_TEXT, 0x99ec1c, code);
        (GUI_SCRATCH_TEXT, 0)
    } else {
        (plain, 1)
    };
    button(SCREEN_MANAGER, right - 0x14, y, right, y + 0x14, 0x30, read_u16(G_GUI_COLOUR_DARK_BLUE) as u32, 0xc, style,
        read_u16(G_GUI_COLOUR_PALE_GREY) as u32, text, id, 0);
}

/// Rule: the page buttons of a list, right to left from `right`: last page, next page, the "Pg page/max" text, previous
/// page and first page; the first and last buttons only when they have an id, and the buttons that lead nowhere carry
/// id 0.
///
/// Each button is 0x14 wide with 2 pixels between them (`gui_page_button`; the symbols 0x2f, 0x2b, 0x2a, 0x2e or the
/// texts ">>", ">", "<", "<<"). ">>" (when `last_id` ≠ 0) and ">" carry their ids while `page` < `max` (signed words),
/// "<" and "<<" (when `first_id` ≠ 0) while `page` > 1. The text: its width is that of "Pg max/max"
/// (`FN_LANGLIB_SPRINTF` into the scratch text, `exe::font_text_width` of font 2, + 10); then "Pg page/max", a text
/// item (`ScreenManager::add_text_item`: flags 2, colour 0, font 0xc, style 2, `G_GUI_COLOUR_YELLOW`) ending 2 pixels
/// left of ">"; "<" starts 2 pixels left of it and "<<" one button further. Returns the left edge of the "<<" slot
/// (whether or not it is added).
/// Original: `gui_add_page_buttons` (0x5ede20, gui_utils.cpp, cdecl).
pub(crate) unsafe extern "C" fn gui_add_page_buttons(right: i32, y: i32, page: u32, max: u32, first_id: u32, prev_id: u32, next_id: u32,
    last_id: u32) -> i32 {
    let (page, max) = (page as i16, max as i16);
    let mut x = right;
    if last_id != 0 {
        gui_page_button(x, y, 0x2f, 0x98e7a8, if page >= max { 0 } else { last_id });
        x -= 0x16;
    }
    gui_page_button(x, y, 0x2b, 0x9cdc54, if page >= max { 0 } else { next_id }); // tel38_3: next page while not at the end
    x -= 0x16;
    let format: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_LANGLIB_SPRINTF);
    format(GUI_SCRATCH_TEXT, 0x9cdc30, max as i32, max as i32);
    let width = exe::font_text_width(2usize, GUI_SCRATCH_TEXT as *const u8) + 10;
    format(GUI_SCRATCH_TEXT, 0x9cdc30, page as i32, max as i32);
    let text_item: unsafe extern "thiscall" fn(usize, i32, i32, i32, i32, u32, u32, u32, u32, u32, usize, u32) -> u16 =
        core::mem::transmute(FN_SCREENMANAGER_ADD_TEXT_ITEM);
    let left = x - width;
    text_item(SCREEN_MANAGER, left, y, x, y + 0x14, 2, 0, 0xc, 2, read_u16(G_GUI_COLOUR_YELLOW) as u32, GUI_SCRATCH_TEXT, 1);
    x = left - 2;
    gui_page_button(x, y, 0x2a, 0x9cdc2c, if page <= 1 { 0 } else { prev_id });
    x -= 0x16;
    if first_id != 0 {
        covered!("tel38_3 first page button");
        gui_page_button(x, y, 0x2e, 0x98e7c4, if page <= 1 { 0 } else { first_id });
    }
    x - 0x14
}

/// Comparer for `gui_add_page_buttons`: side by side over the display list (up to five items) and the return.
pub(crate) unsafe extern "C" fn compare_gui_add_page_buttons(right: i32, y: i32, page: u32, max: u32, first_id: u32, prev_id: u32, next_id: u32,
    last_id: u32) -> i32 {
    let o = original_fn::<unsafe extern "C" fn(i32, i32, u32, u32, u32, u32, u32, u32) -> i32>(IDX_GUI_ADD_PAGE_BUTTONS);
    compare_gui_build("gui_add_page_buttons", 0, 5, || o(right, y, page, max, first_id, prev_id, next_id, last_id) as u32,
        || gui_add_page_buttons(right, y, page, max, first_id, prev_id, next_id, last_id) as u32) as i32
}

/// Rule: a widget's fields copied out to the caller's 19 pointers.
///
/// In order: the flags, x1, y1, x2, y2, +0x20, the row (`display_item::ROW`), the style (dwords); the colour and the
/// highlight colour (words), +0x3c (dword), the font and the text colour (words), the text (`TEXT`, a pointer; past the
/// five-space indent, +0x85, when the item is in an area whose +0x20e is not −1), the length limit, the id, +0x48
/// (dwords), the area (word) and the text entry target (dword).
/// Original: `Guio::get_fields` (0x5ee4a0, Guio.cpp, thiscall, ret 0x4c).
#[allow(clippy::too_many_arguments)]
pub(crate) unsafe extern "thiscall" fn guio_get_fields(item: usize, flags: usize, x1: usize, y1: usize, x2: usize, y2: usize, f20: usize, row: usize,
    style: usize, colour: usize, highlight: usize, f3c: usize, font: usize, text_colour: usize, text: usize, max_length: usize, id: usize,
    f48: usize, area: usize, target: usize) {
    use display_item as d;
    use guio_fields as g;
    for (out, field) in [(flags, d::FLAGS), (x1, d::X1), (y1, d::Y1), (x2, d::X2), (y2, d::Y2), (f20, 0x20), (row, d::ROW), (style, d::STYLE)] {
        write_u32(out, read_u32(item + field));
    }
    write_u16(colour, read_u16(item + g::COLOUR));
    write_u16(highlight, read_u16(item + g::HIGHLIGHT_COLOUR));
    write_u32(f3c, read_u32(item + 0x3c));
    write_u16(font, read_u16(item + d::FONT));
    write_u16(text_colour, read_u16(item + g::TEXT_COLOUR));
    write_usize(text, item + d::TEXT);
    write_u32(max_length, read_u32(item + d::MAX_LENGTH));
    write_u32(id, read_u32(item + d::ID));
    write_u32(f48, read_u32(item + 0x48));
    write_u16(area, read_u16(item + d::AREA));
    write_u32(target, read_u32(item + g::ENTRY_TARGET));
    let a = read_i16(area);
    if a != -1 && read_i16(guio_area(item, a) + 0x20e) != -1 { // tel38_3: an area item's text skips the indent
        write_usize(text, item + d::TEXT + 5);
    }
}

/// Comparer for `guio_get_fields`: side by side over the 19 outputs.
#[allow(clippy::too_many_arguments)]
pub(crate) unsafe extern "thiscall" fn compare_guio_get_fields(item: usize, flags: usize, x1: usize, y1: usize, x2: usize, y2: usize, f20: usize, row: usize,
    style: usize, colour: usize, highlight: usize, f3c: usize, font: usize, text_colour: usize, text: usize, max_length: usize, id: usize,
    f48: usize, area: usize, target: usize) {
    type F = unsafe extern "thiscall" fn(usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize, usize,
        usize, usize, usize, usize);
    let o = original_fn::<F>(IDX_GUIO_GET_FIELDS);
    let outs = [(flags, 4), (x1, 4), (y1, 4), (x2, 4), (y2, 4), (f20, 4), (row, 4), (style, 4), (colour, 2), (highlight, 2), (f3c, 4), (font, 2),
        (text_colour, 2), (text, 4), (max_length, 4), (id, 4), (f48, 4), (area, 2), (target, 4)];
    let (_, _, equal, mo, mr) = crate::comparison::side_by_side_light(&outs,
        || o(item, flags, x1, y1, x2, y2, f20, row, style, colour, highlight, f3c, font, text_colour, text, max_length, id, f48, area, target),
        || guio_get_fields(item, flags, x1, y1, x2, y2, f20, row, style, colour, highlight, f3c, font, text_colour, text, max_length, id, f48, area, target));
    SCOREBOARD.record(equal, || format!("guio_get_fields({:#x}): differences in {:?}", item, first_differences(&mo, &mr)));
}

/// Area `a` of a widget's Display (the widget keeps the area table's address at +0).
unsafe fn guio_area(item: usize, a: i16) -> usize {
    (read_usize(item) as isize + a as isize * display_list::AREA_SIZE as isize) as usize
}

/// The redraw shared by the highlight routines and `guio_set_text_and_refresh`: the saved background back
/// (`gui_restore_background`, when there is one), `Guio::draw(item, 0)` and the rectangle shown.
unsafe fn guio_redraw(item: usize) {
    use display_item as d;
    let back = read_usize(item + d::BACK_IMAGE);
    if back != 0 {
        gui_restore_background(read_u32(item + d::X1), read_u32(item + d::Y1), back);
    }
    exe::guio_draw(item, 0);
    gui_update_rect(item);
}

/// Whether a highlight change redraws the widget: a style with 0x30 (the bits that show the highlight), unless the
/// widget has flag 4 and the same colour and highlight colour.
unsafe fn guio_highlight_shows(item: usize) -> bool {
    use guio_fields as g;
    if read_u8(item + display_item::STYLE) & 0x30 == 0 {
        return false;
    }
    !(read_u32(item + display_item::FLAGS) & 4 != 0 && read_u16(item + g::COLOUR) == read_u16(item + g::HIGHLIGHT_COLOUR))
}

/// Rule: highlighting a widget marks it, redraws it when the highlight shows, and makes it its area's highlighted item.
///
/// `display_item::HIGHLIGHTED` = 1 and `HOVER_TIME` = the tick (0xb67a08); when `guio_highlight_shows`, `guio_redraw`;
/// in an area (`AREA` ≠ −1) the area's `display_area::HIGHLIGHTED_ITEM` = the widget's index.
/// Original: `Guio::highlight_on` (0x5eec20, Guio.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn guio_highlight_on(item: usize) {
    use display_item as d;
    write_u32(item + d::HIGHLIGHTED, 1);
    write_u32(item + d::HOVER_TIME, read_u32(0xb67a08));
    if guio_highlight_shows(item) {
        guio_redraw(item);
    }
    let area = read_i16(item + d::AREA);
    if area != -1 {
        write_u16(guio_area(item, area) + display_area::HIGHLIGHTED_ITEM, read_u16(item + guio_fields::INDEX)); // tel38_3: the area's highlight
    }
}

// simplification: draws on the screen: it does not run twice. Original only; the plan: the marks and the area's
// highlighted item.
/// Comparer for `guio_highlight_on`.
pub(crate) unsafe extern "thiscall" fn compare_guio_highlight_on(item: usize) {
    use display_item as d;
    original_fn::<unsafe extern "thiscall" fn(usize)>(IDX_GUIO_HIGHLIGHT_ON)(item);
    let area = read_i16(item + d::AREA);
    let ok = read_u32(item + d::HIGHLIGHTED) == 1 && read_u32(item + d::HOVER_TIME) == read_u32(0xb67a08)
        && (area == -1 || read_u16(guio_area(item, area) + display_area::HIGHLIGHTED_ITEM) == read_u16(item + guio_fields::INDEX));
    SCOREBOARD.record(ok, || format!("guio_highlight_on({:#x}): highlighted {} area {}", item, read_u32(item + d::HIGHLIGHTED), area));
}

/// Rule: taking the highlight off a widget unmarks it, redraws it when the highlight shows, and clears its area's
/// highlighted item when it was this one.
///
/// `display_item::HIGHLIGHTED` = 0 and `HOVER_TIME` = the tick; when `guio_highlight_shows`, `guio_redraw`; in an area
/// whose `display_area::HIGHLIGHTED_ITEM` is the widget's index, it goes to −1.
/// Original: `Guio::highlight_off` (0x5eecb0, Guio.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn guio_highlight_off(item: usize) {
    use display_item as d;
    write_u32(item + d::HIGHLIGHTED, 0);
    write_u32(item + d::HOVER_TIME, read_u32(0xb67a08));
    if guio_highlight_shows(item) {
        guio_redraw(item);
    }
    let area = read_i16(item + d::AREA);
    if area != -1 {
        let h = guio_area(item, area) + display_area::HIGHLIGHTED_ITEM;
        if read_u16(h) == read_u16(item + guio_fields::INDEX) {
            write_u16(h, 0xffff);
        }
    }
}

// simplification: draws on the screen: it does not run twice. Original only; the plan: the marks and, when the area
// highlighted this widget, no highlighted item.
/// Comparer for `guio_highlight_off`.
pub(crate) unsafe extern "thiscall" fn compare_guio_highlight_off(item: usize) {
    use display_item as d;
    let area = read_i16(item + d::AREA);
    let was = area != -1 && read_u16(guio_area(item, area) + display_area::HIGHLIGHTED_ITEM) == read_u16(item + guio_fields::INDEX);
    original_fn::<unsafe extern "thiscall" fn(usize)>(IDX_GUIO_HIGHLIGHT_OFF)(item);
    let ok = read_u32(item + d::HIGHLIGHTED) == 0 && read_u32(item + d::HOVER_TIME) == read_u32(0xb67a08)
        && (!was || read_i16(guio_area(item, area) + display_area::HIGHLIGHTED_ITEM) == -1);
    SCOREBOARD.record(ok, || format!("guio_highlight_off({:#x}): highlighted {} area {}", item, read_u32(item + d::HIGHLIGHTED), area));
}

/// Whether two C strings are equal (the original's inline strcmp).
unsafe fn guio_same_c_string(a: usize, b: usize) -> bool {
    let mut i = 0;
    loop {
        let c = read_u8(a + i);
        if c != read_u8(b + i) {
            return false;
        }
        if c == 0 {
            return true;
        }
        i += 1;
    }
}

/// Frees a widget's cached text image (`guio_fields::TEXT_IMAGE`): when its text is the shared image's name, only the
/// shared count goes down; otherwise `exe::gui_free_image`. The pointer goes to 0.
unsafe fn guio_drop_text_image(item: usize) {
    let image = read_usize(item + guio_fields::TEXT_IMAGE);
    if guio_same_c_string(GUIO_SHARED_IMAGE_NAME, item + display_item::TEXT) {
        write_i16(GUIO_SHARED_IMAGE_COUNT, read_i16(GUIO_SHARED_IMAGE_COUNT).wrapping_sub(1));
    } else {
        exe::gui_free_image(image);
    }
    write_usize(item + guio_fields::TEXT_IMAGE, 0);
}

/// Rule: a widget gets a new text; with `refresh` and a live display it is redrawn at once.
///
/// A null text: the original routine runs (error box `Guio.cpp 559`). A widget with flag 0x400 and a cached text image
/// drops it (`guio_drop_text_image`). The text is copied to `display_item::TEXT`; a text entry (flag 8) with a target
/// copies it there too. With `refresh` and the current slot's `Display` live (`DISPLAY_LIVE_REDRAW`): the saved
/// background is put back and freed (`BACK_IMAGE` = 0), `Guio::draw(item, 0)` and the rectangle shown.
/// Original: `Guio::set_text_and_refresh` (0x5eed50, Guio.cpp, thiscall, ret 8).
pub(crate) unsafe extern "thiscall" fn guio_set_text_and_refresh(item: usize, text: usize, refresh: u32) {
    use display_item as d;
    if text == 0 {
        return original_fn::<unsafe extern "thiscall" fn(usize, usize, u32)>(IDX_GUIO_SET_TEXT_AND_REFRESH)(item, text, refresh);
    }
    if read_u32(item + d::FLAGS) & 0x400 != 0 && read_usize(item + guio_fields::TEXT_IMAGE) != 0 {
        guio_drop_text_image(item);
    }
    copy_c_string(item + d::TEXT, text);
    if read_u32(item + d::FLAGS) & 8 != 0 && read_usize(item + guio_fields::ENTRY_TARGET) != 0 {
        copy_c_string(read_usize(item + guio_fields::ENTRY_TARGET), item + d::TEXT); // tel38_3: the entry's target follows
    }
    if read_u32(screens_current_display(SCREEN_MANAGER) + DISPLAY_LIVE_REDRAW) == 0 || refresh == 0 {
        return;
    }
    covered!("tel38_3 text redrawn at once");
    let back = read_usize(item + d::BACK_IMAGE);
    if back != 0 {
        gui_restore_background(read_u32(item + d::X1), read_u32(item + d::Y1), back);
        exe::gui_free_image(read_usize(item + d::BACK_IMAGE));
        write_usize(item + d::BACK_IMAGE, 0);
    }
    exe::guio_draw(item, 0);
    gui_update_rect(item);
}

// simplification: frees images and draws: it does not run twice. Original only; the plan: the text and, for a text
// entry, its target.
/// Comparer for `guio_set_text_and_refresh`.
pub(crate) unsafe extern "thiscall" fn compare_guio_set_text_and_refresh(item: usize, text: usize, refresh: u32) {
    use display_item as d;
    let o = original_fn::<unsafe extern "thiscall" fn(usize, usize, u32)>(IDX_GUIO_SET_TEXT_AND_REFRESH);
    if text == 0 {
        return o(item, text, refresh);
    }
    let expected = core::slice::from_raw_parts(text as *const u8, c_string_len(text)).to_vec();
    o(item, text, refresh);
    let same = |p: usize| c_string_len(p) == expected.len() && core::slice::from_raw_parts(p as *const u8, expected.len()) == &expected[..];
    let target = read_usize(item + guio_fields::ENTRY_TARGET);
    let ok = same(item + d::TEXT) && (read_u32(item + d::FLAGS) & 8 == 0 || target == 0 || same(target));
    SCOREBOARD.record(ok, || format!("guio_set_text_and_refresh({:#x}): text {:?}", item, String::from_utf8_lossy(&expected)));
}

/// Rule: a widget's images are freed: the saved background (`display_item::BACK_IMAGE`, `exe::gui_free_image`) and the
/// cached text image (`guio_drop_text_image`), each pointer going to 0.
/// Original: `Guio::free_images` (0x5eef00, Guio.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn guio_free_images(item: usize) {
    let back = read_usize(item + display_item::BACK_IMAGE);
    if back != 0 {
        exe::gui_free_image(back);
        write_usize(item + display_item::BACK_IMAGE, 0);
    }
    if read_usize(item + guio_fields::TEXT_IMAGE) != 0 {
        covered!("tel38_3 text image freed");
        guio_drop_text_image(item);
    }
}

// simplification: frees the images: it does not run twice. Original only; the plan: both pointers null.
/// Comparer for `guio_free_images`.
pub(crate) unsafe extern "thiscall" fn compare_guio_free_images(item: usize) {
    original_fn::<unsafe extern "thiscall" fn(usize)>(IDX_GUIO_FREE_IMAGES)(item);
    let (back, image) = (read_usize(item + display_item::BACK_IMAGE), read_usize(item + guio_fields::TEXT_IMAGE));
    SCOREBOARD.record(back == 0 && image == 0, || format!("guio_free_images({:#x}): back {:#x} image {:#x}", item, back, image));
}

/// Rule: a widget's colours chosen by `which` (1 colour, 2 highlight colour, 4 text colour) are converted from the
/// 5-5-5 or 5-6-5 pixel format (`to_565`) to the screen's.
///
/// The source format: masks 0xf800, 0x7e0, 0x1f with `to_565`, otherwise 0x7c00, 0x3e0, 0x1f (at +0x10 of a local
/// format). Each chosen colour is first split into its three channels (0x5e49f0, cdecl), all into the same three
/// locals; then each chosen colour gets `exe::graphics_rgb_to_pixel` of those locals in the screen format. Defect of the
/// original: with more than one colour chosen, every one of them gets the last one split (the text colour, else the
/// highlight colour). With the "no format" flag (0xaebe0c) the split writes nothing and the conversion gives 0.
/// Original: `Guio::convert_colours_pixel_format` (0x5eef80, Guio.cpp, thiscall, ret 8).
pub(crate) unsafe extern "thiscall" fn guio_convert_colours_pixel_format(item: usize, to_565: u32, which: u32) {
    use guio_fields as g;
    let split: unsafe extern "C" fn(u32, *mut u32, *mut u32, *mut u32, *const u32) = core::mem::transmute(0x5e49f0usize);
    let mut format = [0u32; 7];
    format[4..].copy_from_slice(&if to_565 != 0 { [0xf800, 0x7e0, 0x1f] } else { [0x7c00, 0x3e0, 0x1f] });
    // simplification: the original's channel locals start as leftovers; they only matter with the "no format" flag,
    // where the conversion gives 0 anyway
    let (mut c0, mut c1, mut c2) = (0u32, 0u32, 0u32);
    let chosen = [(1u32, g::COLOUR), (2, g::HIGHLIGHT_COLOUR), (4, g::TEXT_COLOUR)];
    for &(bit, field) in &chosen {
        if which & bit != 0 {
            split(read_u16(item + field) as u32, &mut c0, &mut c1, &mut c2, format.as_ptr()); // tel38_3: every split into the same channels
        }
    }
    for &(bit, field) in &chosen {
        if which & bit != 0 {
            write_u16(item + field, exe::graphics_rgb_to_pixel(c0, c1, c2, 0) as u16);
        }
    }
}

/// Comparer for `guio_convert_colours_pixel_format`: side by side over the three colours.
pub(crate) unsafe extern "thiscall" fn compare_guio_convert_colours_pixel_format(item: usize, to_565: u32, which: u32) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32, u32)>(IDX_GUIO_CONVERT_COLOURS_PIXEL_FORMAT);
    let (_, _, equal, mo, mr) = crate::comparison::side_by_side_light(&[(item + guio_fields::COLOUR, 8)], || o(item, to_565, which),
        || guio_convert_colours_pixel_format(item, to_565, which));
    SCOREBOARD.record(equal, || format!("guio_convert_colours_pixel_format({:#x}, {}, {}): differences in {:?}", item, to_565, which, first_differences(&mo, &mr)));
}

// ---------- batch 318: the screen manager's widget packets: setting a widget's flags, style, colours, text flags, font, text, id and data on the current screen, locally or over the network (scrman.cpp) ----------

/// The Display that echoes a remote manager's packets while his own Display blocks them [inference: +0x132ea5 of the
/// screen manager, after the local Display].
const SCRMAN_ECHO_DISPLAY: usize = 0x132ea5;

/// Appends `size` bytes (1, 2 or 4) of `value` to the screen manager's network command buffer (`screen_history::NET_BUFFER`,
/// the position `NET_BUFFER_POS`, the capacity `NET_BUFFER_CAPACITY`), as network.h's inline writers do: no room
/// (position + size above the capacity, unsigned) gives the box `network.h <line>` and nothing written.
unsafe fn scrman_net_put(sm: usize, value: u32, size: u32, line: u32) {
    use screen_history as h;
    let pos = read_u32(sm + h::NET_BUFFER_POS);
    if pos.wrapping_add(size) > read_u32(sm + h::NET_BUFFER_CAPACITY) {
        show_error_at(NETWORK_H, line);
        return;
    }
    let at = read_usize(sm + h::NET_BUFFER) + pos as usize;
    match size {
        1 => write_u8(at, value as u8),
        2 => write_u16(at, value as u16),
        _ => write_u32(at, value),
    }
    write_u32(sm + h::NET_BUFFER_POS, pos + size);
}

/// Starts a widget packet: the buffer position to 0, the command 8, the widget (word) and the sub-command (byte).
unsafe fn scrman_widget_packet(sm: usize, widget: u32, sub: u8) {
    write_u32(sm + screen_history::NET_BUFFER_POS, 0);
    scrman_net_put(sm, 8, 1, 0x85); // tel38_4: the widget command
    scrman_net_put(sm, widget, 2, 0x86);
    scrman_net_put(sm, sub as u32, 1, 0x85);
}

/// Delivers the packet in the buffer for the current record: a local one (`screen_history::NETWORK_PLAYER` = 0) has it
/// applied to the local Display (`Display::process_command_packet` 0x564080, thiscall, with the session and 0); a remote
/// one whose Display blocks it (`DISPLAY_REDRAW_BLOCKED`) has it applied to the echo Display; otherwise it is sent to
/// his player (`Network::send_packet` 0x77ac30, thiscall; failing: the box `scrman.cpp <line>`).
unsafe fn scrman_deliver_packet(sm: usize, line: u32) {
    use screen_history as h;
    let process: unsafe extern "thiscall" fn(usize, usize, u32, usize) -> u32 = core::mem::transmute(0x564080usize);
    let send: unsafe extern "thiscall" fn(usize, usize, u32, u32) -> u32 = core::mem::transmute(0x77ac30usize);
    let rec = screen_record(sm);
    let player = read_u16(rec + h::NETWORK_PLAYER);
    if player == 0 {
        process(sm + h::LOCAL_DISPLAY, read_usize(sm + h::NETWORK), 0, sm + h::NET_BUFFER);
        return;
    }
    covered!("tel38_4 widget packet for a remote manager");
    if read_u32(read_usize(rec + screen_manager::DISPLAY) + DISPLAY_REDRAW_BLOCKED) != 0 {
        process(sm + SCRMAN_ECHO_DISPLAY, read_usize(sm + h::NETWORK), 0, sm + h::NET_BUFFER);
        return;
    }
    if send(read_usize(sm + h::NETWORK), read_usize(sm + h::NET_BUFFER), read_u32(sm + h::NET_BUFFER_POS), player as u32) == 0 {
        show_error_at(SCRMAN_CPP, line);
    }
}

/// The body of the fixed-size widget setters: nothing for widget −1 (unless `always`); the packet (command 8, the
/// widget, `sub`, then `value` in `size` bytes with the box line `put_line`) and its delivery (`send_line`).
unsafe fn scrman_set_widget(sm: usize, widget: u32, sub: u8, value: u32, size: u32, put_line: u32, send_line: u32, always: bool) {
    if !always && widget as u16 == 0xffff {
        return;
    }
    scrman_widget_packet(sm, widget, sub);
    scrman_net_put(sm, value, size, put_line);
    scrman_deliver_packet(sm, send_line);
}

/// The packet a widget setter leaves in the buffer: command 8, the widget word, the sub-command and the value bytes.
fn scrman_expected_packet(widget: u32, sub: u8, value: &[u8]) -> Vec<u8> {
    let mut p = vec![8, widget as u8, (widget >> 8) as u8, sub];
    p.extend_from_slice(value);
    p
}

// simplification: the packet is applied to the Display (it may redraw) or sent: it does not run twice. Original only;
// the plan: the packet in the buffer, when there was room for it.
/// The comparer of a widget setter.
unsafe fn compare_scrman_set_widget(name: &str, sm: usize, widget: u32, skip: bool, expected: Vec<u8>, original: impl FnOnce()) {
    use screen_history as h;
    let room = read_u32(sm + h::NET_BUFFER_CAPACITY) as usize >= expected.len();
    original();
    if skip || !room {
        return;
    }
    let pos = read_u32(sm + h::NET_BUFFER_POS) as usize;
    let got = core::slice::from_raw_parts(read_usize(sm + h::NET_BUFFER) as *const u8, pos.min(expected.len()));
    SCOREBOARD.record(pos == expected.len() && got == &expected[..], || format!("{}(widget {}): packet {:x?}, expected {:x?}", name, widget as i16, got, expected));
}

/// Rule: a widget of the current screen gets its flags (sub-command 0, a dword).
///
/// `scrman_set_widget` with widget −1 doing nothing, the dword written with the box line `network.h 141`, the send
/// failure `scrman.cpp 2606`.
/// Original: `ScreenManager::set_widget_flags` (0x800580, scrman.cpp, thiscall, ret 8).
pub(crate) unsafe extern "thiscall" fn screen_manager_set_widget_flags(sm: usize, widget: u32, flags: u32) {
    scrman_set_widget(sm, widget, 0, flags, 4, 0x8d, 0xa2e, false); // tel38_4: the flags sub-command
}

/// Comparer for `screen_manager_set_widget_flags`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_set_widget_flags(sm: usize, widget: u32, flags: u32) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32, u32)>(IDX_SCREEN_MANAGER_SET_WIDGET_FLAGS);
    compare_scrman_set_widget("screen_manager_set_widget_flags", sm, widget, widget as u16 == 0xffff, scrman_expected_packet(widget, 0, &flags.to_le_bytes()),
        || o(sm, widget, flags));
}

