/// Rule: a widget of the current screen gets a new text (sub-command 8, the string with its terminator, after its
/// length as a word); nothing for widget −1.
///
/// The packet as `scrman_widget_packet`; the length (strlen + 1, a word, box line `network.h 134`); then the string
/// with its terminator is copied after it and the position advances, with no room check (defect of the original: a
/// long text runs past the buffer). Delivery with the send failure `scrman.cpp 2887`.
/// Original: `ScreenManager::set_widget_text` (0x801c70, scrman.cpp, thiscall, ret 8).
pub(crate) unsafe extern "thiscall" fn screen_manager_set_widget_text(sm: usize, widget: u32, text: usize) {
    use screen_history as h;
    if widget as u16 == 0xffff {
        return;
    }
    scrman_widget_packet(sm, widget, 8);
    let len = c_string_len(text) + 1;
    scrman_net_put(sm, len as u32, 2, 0x86);
    let pos = read_u32(sm + h::NET_BUFFER_POS);
    core::ptr::copy_nonoverlapping(text as *const u8, (read_usize(sm + h::NET_BUFFER) + pos as usize) as *mut u8, len); // tel38_4: the text copied unchecked
    write_u32(sm + h::NET_BUFFER_POS, pos.wrapping_add(len as u16 as i16 as u32));
    scrman_deliver_packet(sm, 0xb47);
}

/// Comparer for `screen_manager_set_widget_text`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_set_widget_text(sm: usize, widget: u32, text: usize) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32, usize)>(IDX_SCREEN_MANAGER_SET_WIDGET_TEXT);
    let skip = widget as u16 == 0xffff || text == 0;
    let mut value = Vec::new();
    if !skip {
        let len = c_string_len(text) + 1;
        value.extend_from_slice(&(len as u16).to_le_bytes());
        value.extend_from_slice(core::slice::from_raw_parts(text as *const u8, len));
    }
    compare_scrman_set_widget("screen_manager_set_widget_text", sm, widget, skip, scrman_expected_packet(widget, 8, &value), || o(sm, widget, text));
}

/// Rule: a widget of the current screen gets its id (sub-command 9, a dword; box line `network.h 136`, send failure
/// `scrman.cpp 2922`); nothing for widget −1.
/// Original: `ScreenManager::set_widget_id` (0x801fc0, scrman.cpp, thiscall, ret 8).
pub(crate) unsafe extern "thiscall" fn screen_manager_set_widget_id(sm: usize, widget: u32, id: u32) {
    scrman_set_widget(sm, widget, 9, id, 4, 0x88, 0xb6a, false);
}

/// Comparer for `screen_manager_set_widget_id`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_set_widget_id(sm: usize, widget: u32, id: u32) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32, u32)>(IDX_SCREEN_MANAGER_SET_WIDGET_ID);
    compare_scrman_set_widget("screen_manager_set_widget_id", sm, widget, widget as u16 == 0xffff, scrman_expected_packet(widget, 9, &id.to_le_bytes()),
        || o(sm, widget, id));
}

/// Rule: a widget of the current screen gets its data (sub-command 0xa, a dword; box line `network.h 137`, send failure
/// `scrman.cpp 2957`); nothing for widget −1.
/// Original: `ScreenManager::set_widget_data` (0x8022d0, scrman.cpp, thiscall, ret 8).
pub(crate) unsafe extern "thiscall" fn screen_manager_set_widget_data(sm: usize, widget: u32, data: u32) {
    scrman_set_widget(sm, widget, 0xa, data, 4, 0x89, 0xb8d, false);
}

/// Comparer for `screen_manager_set_widget_data`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_set_widget_data(sm: usize, widget: u32, data: u32) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32, u32)>(IDX_SCREEN_MANAGER_SET_WIDGET_DATA);
    compare_scrman_set_widget("screen_manager_set_widget_data", sm, widget, widget as u16 == 0xffff, scrman_expected_packet(widget, 0xa, &data.to_le_bytes()),
        || o(sm, widget, data));
}

// ---------- batch 318: the screen manager's last base routines: a widget's rectangle, closing every screen, opening a screen for each record and the sounds (scrman.cpp) ----------

/// The sound player (`SoundPlayer`, simulated_stats.cpp; 0 when the game has no sound) and, in the screen manager, the
/// sound slots a remote manager reported playing (16 channels × 10 dwords).
const SOUND_PLAYER: usize = 0xdd7eec;
const SCRMAN_SOUND_PLAYING: usize = 0x26250a;

/// The playing flag of sound slot `slot` of the current channel (the original's `+0x26250a + (channel × 10 + slot) × 4`,
/// the slot sign-extended from its byte).
unsafe fn scrman_sound_flag(sm: usize, slot: u32) -> usize {
    let k = read_i16(sm + screen_manager::CURRENT_SLOT) as isize * 10 + slot as i8 as isize;
    (sm as isize + SCRMAN_SOUND_PLAYING as isize + k * 4) as usize
}

/// Starts a command packet: the buffer position to 0 and the command byte (box line `network.h 133`).
unsafe fn scrman_command_packet(sm: usize, command: u8) {
    write_u32(sm + screen_history::NET_BUFFER_POS, 0);
    scrman_net_put(sm, command as u32, 1, 0x85);
}

/// Appends a string to the packet: its length with the terminator (a word, box line `network.h 134`), then the string
/// with its terminator copied after it and the position advanced, with no room check (defect of the original, as in
/// `screen_manager_set_widget_text`).
unsafe fn scrman_net_put_text(sm: usize, text: usize) {
    use screen_history as h;
    let len = c_string_len(text) + 1;
    scrman_net_put(sm, len as u32, 2, 0x86);
    let pos = read_u32(sm + h::NET_BUFFER_POS);
    core::ptr::copy_nonoverlapping(text as *const u8, (read_usize(sm + h::NET_BUFFER) + pos as usize) as *mut u8, len);
    write_u32(sm + h::NET_BUFFER_POS, pos.wrapping_add(len as u16 as i16 as u32));
}

/// Sends the packet in the buffer to the current record's network player (`Network::send_packet` 0x77ac30, thiscall);
/// failing, the box `scrman.cpp <line>`.
unsafe fn scrman_send_packet(sm: usize, line: u32) {
    use screen_history as h;
    let send: unsafe extern "thiscall" fn(usize, usize, u32, u32) -> u32 = core::mem::transmute(0x77ac30usize);
    let player = read_u16(screen_record(sm) + h::NETWORK_PLAYER);
    if send(read_usize(sm + h::NETWORK), read_usize(sm + h::NET_BUFFER), read_u32(sm + h::NET_BUFFER_POS), player as u32) == 0 {
        show_error_at(SCRMAN_CPP, line);
    }
}

/// The packet left in the buffer checked against the expected bytes, when there was room for it.
unsafe fn scrman_check_packet(name: &str, sm: usize, room: bool, expected: &[u8]) {
    use screen_history as h;
    if !room {
        return;
    }
    let pos = read_u32(sm + h::NET_BUFFER_POS) as usize;
    let got = core::slice::from_raw_parts(read_usize(sm + h::NET_BUFFER) as *const u8, pos.min(expected.len()));
    SCOREBOARD.record(pos == expected.len() && got == expected, || format!("{}: packet {:x?}, expected {:x?}", name, got, expected));
}

/// Rule: a widget of the current screen gets a new rectangle (sub-command 1, four words); nothing for widget −1.
///
/// The packet as `scrman_widget_packet`, then x1, y1, x2 and y2 as words (box line `network.h 134` each) and its
/// delivery (`scrman_deliver_packet`, send failure `scrman.cpp 2644`). The 1080 exe rewrites the entry (it scales the
/// four coordinates to the big screen first): the entry is for the original exe only.
/// Original: `ScreenManager::set_widget_rect` (0x800890, scrman.cpp, thiscall, ret 0x14).
pub(crate) unsafe extern "thiscall" fn screen_manager_set_widget_rect(sm: usize, widget: u32, x1: u32, y1: u32, x2: u32, y2: u32) {
    if widget as u16 == 0xffff {
        return;
    }
    scrman_widget_packet(sm, widget, 1); // tel38_5: the rectangle sub-command
    for v in [x1, y1, x2, y2] {
        scrman_net_put(sm, v, 2, 0x86);
    }
    scrman_deliver_packet(sm, 0xa54);
}

/// Comparer for `screen_manager_set_widget_rect`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_set_widget_rect(sm: usize, widget: u32, x1: u32, y1: u32, x2: u32, y2: u32) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32, u32, u32, u32, u32)>(IDX_SCREEN_MANAGER_SET_WIDGET_RECT);
    let mut value = Vec::new();
    for v in [x1, y1, x2, y2] {
        value.extend_from_slice(&(v as u16).to_le_bytes());
    }
    compare_scrman_set_widget("screen_manager_set_widget_rect", sm, widget, widget as u16 == 0xffff, scrman_expected_packet(widget, 1, &value),
        || o(sm, widget, x1, y1, x2, y2));
}

/// Rule: closing every screen of the current manager runs each screen's exit function and the current screen's leave
/// function, empties the Display and frees the history; a single-instance screen with no exit function blocks it.
///
/// With flagged screens (`screen_history::FLAGGED_COUNT` > 0), the current node walks back from the last one
/// (`screen_node_fields::PREV`); a node with the flag and no exit function stops the walk: `ACTIVE_FLAG` = 1, returns 0
/// (defect of the original: the current node is left at that node). When the walk ends the current node is 0, so the
/// next part is skipped (defect of the original [inference]: with flagged screens open no exit function runs). With a
/// current node: from the first node each exit function runs (cdecl, no arguments; the current node walks along by
/// `NEXT`), the current node comes back, its leave function runs, the record's Display is reset (`Display::reset`
/// 0x55f7c0, thiscall, releasing its items) and the current node goes to 0. Then `ACTIVE_FLAG` = 0,
/// `ScreenManager::free_all_screens` and 1.
/// Original: `ScreenManager::close_all_screens` (0x803d80, scrman.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn screen_manager_close_all_screens(sm: usize) -> u32 {
    use screen_history as h;
    use screen_node_fields as n;
    let current = |sm: usize| screen_record(sm) + h::CURRENT_NODE;
    if read_i16(screen_record(sm) + h::FLAGGED_COUNT) > 0 {
        write_usize(current(sm), read_usize(screen_record(sm) + h::LAST_NODE));
        let mut node = read_usize(current(sm));
        while node != 0 {
            if read_u32(node + n::FLAG) != 0 && read_usize(node + n::EXIT) == 0 {
                covered!("tel38_5 closing blocked");
                write_u32(screen_record(sm) + h::ACTIVE_FLAG, 1); // tel38_5: a flagged screen with no exit blocks
                return 0;
            }
            write_usize(current(sm), read_usize(node + n::PREV));
            node = read_usize(current(sm));
        }
    }
    let saved = read_usize(current(sm));
    if saved != 0 {
        write_usize(current(sm), read_usize(screen_record(sm) + h::FIRST_NODE));
        let mut node = read_usize(current(sm));
        while node != 0 {
            let exit = read_usize(node + n::EXIT);
            if exit != 0 {
                let f: unsafe extern "C" fn() = core::mem::transmute(exit);
                f();
            }
            write_usize(current(sm), read_usize(read_usize(current(sm)) + n::NEXT));
            node = read_usize(current(sm));
        }
        write_usize(current(sm), saved);
        let leave = read_usize(read_usize(current(sm)) + n::LEAVE);
        if leave != 0 {
            let f: unsafe extern "C" fn() = core::mem::transmute(leave);
            f();
        }
        let reset: unsafe extern "thiscall" fn(usize, u32) = core::mem::transmute(0x55f7c0usize);
        reset(read_usize(screen_record(sm) + screen_manager::DISPLAY), 1);
        write_usize(current(sm), 0);
    }
    write_u32(screen_record(sm) + h::ACTIVE_FLAG, 0);
    let free_all: unsafe extern "thiscall" fn(usize) = core::mem::transmute(0x7fef10usize);
    free_all(sm);
    1
}

// simplification: runs the screens' functions and frees the history: it does not run twice. Original only; the plan:
// with 1, the history empty and `ACTIVE_FLAG` 0; with 0, `ACTIVE_FLAG` 1.
/// Comparer for `screen_manager_close_all_screens`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_close_all_screens(sm: usize) -> u32 {
    use screen_history as h;
    let r = original_fn::<unsafe extern "thiscall" fn(usize) -> u32>(IDX_SCREEN_MANAGER_CLOSE_ALL_SCREENS)(sm);
    let rec = screen_record(sm);
    let ok = match r {
        1 => read_usize(rec + h::FIRST_NODE) == 0 && read_usize(rec + h::CURRENT_NODE) == 0 && read_u32(rec + h::ACTIVE_FLAG) == 0,
        0 => read_u32(rec + h::ACTIVE_FLAG) == 1,
        _ => false,
    };
    SCOREBOARD.record(ok, || format!("screen_manager_close_all_screens: returned {} first {:#x} current {:#x} active {}", r, read_usize(rec + h::FIRST_NODE),
        read_usize(rec + h::CURRENT_NODE), read_u32(rec + h::ACTIVE_FLAG)));
    r
}

/// Rule: opens a screen on every record of every channel whose manager key is `key` (all of them when `key` is 0).
///
/// The walk of `screen_manager_set_screen_param_for_each_record`: the current slot saved and walking the 16 channels;
/// in a channel with records, record 0 opens the screen (`exe::screenmanager_open_screen` with `build`, `input`, `flag`,
/// `leave`, `exit`) when its key matches, then each other record k is swapped into place 0 (`exe::utils_swap_bytes`,
/// 0x30 bytes) and opens it when its key matches; with more than one record, records 0 and 1 are swapped at the end
/// (the same defect: with three or more records they come back in another order). The slot is restored; returns 1.
/// Original: `ScreenManager::open_screen_for_each_record` (0x7fe4a0, scrman.cpp, thiscall, ret 0x18).
pub(crate) unsafe extern "thiscall" fn screen_manager_open_screen_for_each_record(sm: usize, key: u32, build: usize, input: usize, flag: u32, leave: usize,
    exit: u32) -> u32 {
    use screen_history as h;
    let saved = read_u16(sm + screen_manager::CURRENT_SLOT);
    write_u16(sm + screen_manager::CURRENT_SLOT, 0);
    let count = |sm: usize| read_i16((sm as isize + h::CHANNEL_RECORD_COUNTS as isize + read_i16(sm + screen_manager::CURRENT_SLOT) as isize * 2) as usize);
    let open = |sm: usize| {
        if key == 0 || key == read_u32(screen_record(sm) + h::KEY) { // tel38_5: only the records with the key
            exe::screenmanager_open_screen(sm, build, input, flag, leave, exit);
        }
    };
    loop {
        if count(sm) != 0 {
            open(sm);
            let mut k: i16 = 1;
            while count(sm) > k {
                let first = screen_record(sm) + h::NETWORK_PLAYER;
                exe::utils_swap_bytes(first as *mut i32, (first + k as usize * h::RECORD_SIZE) as *mut i32, h::RECORD_SIZE as u32);
                open(sm);
                k += 1;
            }
            if count(sm) > 1 {
                covered!("tel38_5 screen opened on several records");
                let first = screen_record(sm) + h::NETWORK_PLAYER;
                exe::utils_swap_bytes(first as *mut i32, (first + h::RECORD_SIZE) as *mut i32, h::RECORD_SIZE as u32);
            }
        }
        let slot = read_i16(sm + screen_manager::CURRENT_SLOT).wrapping_add(1);
        write_i16(sm + screen_manager::CURRENT_SLOT, slot);
        if slot >= 16 {
            break;
        }
    }
    write_u16(sm + screen_manager::CURRENT_SLOT, saved);
    1
}

// simplification: opens screens (allocates history nodes, runs leave functions): it does not run twice. Original only;
// the plan: the current slot restored and 1.
/// Comparer for `screen_manager_open_screen_for_each_record`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_open_screen_for_each_record(sm: usize, key: u32, build: usize, input: usize, flag: u32,
    leave: usize, exit: u32) -> u32 {
    let slot = read_u16(sm + screen_manager::CURRENT_SLOT);
    let r = original_fn::<unsafe extern "thiscall" fn(usize, u32, usize, usize, u32, usize, u32) -> u32>(IDX_SCREEN_MANAGER_OPEN_SCREEN_FOR_EACH_RECORD)(sm, key, build, input, flag, leave, exit);
    let back = read_u16(sm + screen_manager::CURRENT_SLOT);
    SCOREBOARD.record(r == 1 && back == slot, || format!("screen_manager_open_screen_for_each_record: returned {}, slot {} came back as {}", r, slot, back));
    r
}

/// Rule: plays a sound file for the current manager: locally through the sound player, or by a network command to a
/// remote manager; the slot that plays it goes to `*out` (0xff none).
///
/// `*out` = 0xff first. A local record (`screen_history::NETWORK_PLAYER` = 0) with a sound player: `*out` =
/// `SoundPlayer::play_file(pan, file, looping)` (0x84cbc0, thiscall) and that slot's volume to 100
/// (`SoundPlayer::set_slot_volume` 0x84ccc0); with no sound player nothing more. A remote one: the packet command 0xa,
/// `out` itself (a dword, box line `network.h 137`; the remote side answers with `on_remote_sound_started`), `pan` and
/// `looping` (bytes), the file name (`scrman_net_put_text`), sent (failure `scrman.cpp 2992`).
/// Original: `ScreenManager::play_sound` (0x8025e0, scrman.cpp, thiscall, ret 0x10).
pub(crate) unsafe extern "thiscall" fn screen_manager_play_sound(sm: usize, out: usize, pan: u32, file: usize, looping: u32) {
    write_u8(out, 0xff);
    if read_u16(screen_record(sm) + screen_history::NETWORK_PLAYER) == 0 {
        let player = read_usize(SOUND_PLAYER);
        if player == 0 {
            return;
        }
        let play: unsafe extern "thiscall" fn(usize, u32, usize, u32) -> u32 = core::mem::transmute(0x84cbc0usize);
        let volume: unsafe extern "thiscall" fn(usize, u32, u32) = core::mem::transmute(0x84ccc0usize);
        let slot = play(player, pan, file, looping);
        write_u8(out, slot as u8);
        volume(read_usize(SOUND_PLAYER), slot, 100); // tel38_5: full volume
        return;
    }
    covered!("tel38_5 sound for a remote manager");
    scrman_command_packet(sm, 0xa);
    scrman_net_put(sm, out as u32, 4, 0x89);
    scrman_net_put(sm, pan, 1, 0x85);
    scrman_net_put(sm, looping, 1, 0x85);
    scrman_net_put_text(sm, file);
    scrman_send_packet(sm, 0xbb0);
}

// simplification: plays a sound or sends the command: it does not run twice. Original only; the plan: with no sound
// player `*out` = 0xff; for a remote manager the packet.
/// Comparer for `screen_manager_play_sound`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_play_sound(sm: usize, out: usize, pan: u32, file: usize, looping: u32) {
    let remote = read_u16(screen_record(sm) + screen_history::NETWORK_PLAYER) != 0;
    let mut expected = vec![0xa];
    if remote {
        expected.extend_from_slice(&(out as u32).to_le_bytes());
        expected.extend_from_slice(&[pan as u8, looping as u8]);
        let len = c_string_len(file) + 1;
        expected.extend_from_slice(&(len as u16).to_le_bytes());
        expected.extend_from_slice(core::slice::from_raw_parts(file as *const u8, len));
    }
    let room = read_u32(sm + screen_history::NET_BUFFER_CAPACITY) as usize >= expected.len();
    let silent = read_usize(SOUND_PLAYER) == 0;
    original_fn::<unsafe extern "thiscall" fn(usize, usize, u32, usize, u32)>(IDX_SCREEN_MANAGER_PLAY_SOUND)(sm, out, pan, file, looping);
    if remote {
        scrman_check_packet("screen_manager_play_sound", sm, room, &expected);
    } else if silent {
        SCOREBOARD.record(read_u8(out) == 0xff, || format!("screen_manager_play_sound: no sound player, slot {:#x}", read_u8(out)));
    }
}

/// Rule: whether a sound slot still plays: never for slot 0xff; locally the sound player's answer (0 without one); for a
/// remote manager the flag his side reported.
///
/// Local record: `SoundPlayer::is_slot_playing(slot)` (0x84cc80, thiscall; the whole argument passed on). Remote: the
/// dword `scrman_sound_flag`.
/// Original: `ScreenManager::is_sound_playing` (0x8029f0, scrman.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn screen_manager_is_sound_playing(sm: usize, slot: u32) -> u32 {
    if slot as u8 == 0xff {
        return 0;
    }
    if read_u16(screen_record(sm) + screen_history::NETWORK_PLAYER) != 0 {
        return read_u32(scrman_sound_flag(sm, slot)); // tel38_5: the remote flag
    }
    let player = read_usize(SOUND_PLAYER);
    if player == 0 {
        return 0;
    }
    let playing: unsafe extern "thiscall" fn(usize, u32) -> u32 = core::mem::transmute(0x84cc80usize);
    playing(player, slot) // tel38_5: the sound player's answer
}

compare_value!(compare_screen_manager_is_sound_playing, screen_manager_is_sound_playing, IDX_SCREEN_MANAGER_IS_SOUND_PLAYING, (slot: u32) -> u32);

/// Rule: stops a sound slot (every slot for 0xff) locally or by a network command, and clears the playing flags.
///
/// Local record: with a sound player, `SoundPlayer::stop_all` (0x84cb10) for 0xff, otherwise
/// `SoundPlayer::stop_slot(slot)` (0x84cb70). Remote: the packet command 0xb and the slot (byte), sent (failure
/// `scrman.cpp 3043`). Then the current channel's 10 flags go to 0 for 0xff, otherwise the slot's
/// (`scrman_sound_flag`).
/// Original: `ScreenManager::stop_sound` (0x802a50, scrman.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn screen_manager_stop_sound(sm: usize, slot: u32) {
    let all = slot as u8 == 0xff;
    if read_u16(screen_record(sm) + screen_history::NETWORK_PLAYER) == 0 {
        let player = read_usize(SOUND_PLAYER);
        if player != 0 {
            if all {
                let stop_all: unsafe extern "thiscall" fn(usize) = core::mem::transmute(0x84cb10usize);
                stop_all(player);
            } else {
                let stop: unsafe extern "thiscall" fn(usize, u32) = core::mem::transmute(0x84cb70usize);
                stop(player, slot);
            }
        }
    } else {
        covered!("tel38_5 sound stopped for a remote manager");
        scrman_command_packet(sm, 0xb);
        scrman_net_put(sm, slot, 1, 0x85);
        scrman_send_packet(sm, 0xbe3);
    }
    if all {
        for k in 0..10 {
            write_u32(scrman_sound_flag(sm, k), 0);
        }
    } else {
        write_u32(scrman_sound_flag(sm, slot), 0); // tel38_5: the slot no longer plays
    }
}

// simplification: stops the sound or sends the command: it does not run twice. Original only; the plan: the flags
// cleared and, for a remote manager, the packet.
/// Comparer for `screen_manager_stop_sound`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_stop_sound(sm: usize, slot: u32) {
    let remote = read_u16(screen_record(sm) + screen_history::NETWORK_PLAYER) != 0;
    let room = read_u32(sm + screen_history::NET_BUFFER_CAPACITY) >= 2;
    original_fn::<unsafe extern "thiscall" fn(usize, u32)>(IDX_SCREEN_MANAGER_STOP_SOUND)(sm, slot);
    if remote {
        scrman_check_packet("screen_manager_stop_sound", sm, room, &[0xb, slot as u8]);
    }
    let cleared = if slot as u8 == 0xff { (0..10).all(|k| read_u32(scrman_sound_flag(sm, k)) == 0) } else { read_u32(scrman_sound_flag(sm, slot)) == 0 };
    SCOREBOARD.record(cleared, || format!("screen_manager_stop_sound({}): a flag still set", slot as i8));
}

/// Rule: a remote manager's side reports the slot a sound plays in: `*out` = the slot and, unless 0xff, its flag
/// (`scrman_sound_flag`) = 1.
/// Original: `ScreenManager::on_remote_sound_started` (0x802cb0, scrman.cpp, thiscall, ret 8).
pub(crate) unsafe extern "thiscall" fn screen_manager_on_remote_sound_started(sm: usize, slot: u32, out: usize) {
    write_u8(out, slot as u8);
    if slot as u8 != 0xff {
        write_u32(scrman_sound_flag(sm, slot), 1); // tel38_5: the remote slot plays
    }
}

/// Comparer for `screen_manager_on_remote_sound_started`: side by side over `*out` and the channel's flags.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_on_remote_sound_started(sm: usize, slot: u32, out: usize) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32, usize)>(IDX_SCREEN_MANAGER_ON_REMOTE_SOUND_STARTED);
    let flags = scrman_sound_flag(sm, 0);
    let (_, _, equal, mo, mr) = crate::comparison::side_by_side_light(&[(out, 1), (scrman_sound_flag(sm, slot), 4)], || o(sm, slot, out),
        || screen_manager_on_remote_sound_started(sm, slot, out));
    SCOREBOARD.record(equal, || format!("screen_manager_on_remote_sound_started({}) flags {:#x}: differences in {:?}", slot as i8, flags, first_differences(&mo, &mr)));
}

/// Rule: a remote manager's side reports a sound ended: its flag (`scrman_sound_flag`) = 0.
/// Original: `ScreenManager::on_remote_sound_finished` (0x802ce0, scrman.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn screen_manager_on_remote_sound_finished(sm: usize, slot: u32) {
    write_u32(scrman_sound_flag(sm, slot), 0);
}

/// Comparer for `screen_manager_on_remote_sound_finished`: side by side over the flag.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_on_remote_sound_finished(sm: usize, slot: u32) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32)>(IDX_SCREEN_MANAGER_ON_REMOTE_SOUND_FINISHED);
    let (_, _, equal, mo, mr) = crate::comparison::side_by_side_light(&[(scrman_sound_flag(sm, slot), 4)], || o(sm, slot),
        || screen_manager_on_remote_sound_finished(sm, slot));
    SCOREBOARD.record(equal, || format!("screen_manager_on_remote_sound_finished({}): differences in {:?}", slot as i8, first_differences(&mo, &mr)));
}

// ---------- batch 318: the screen manager's print commands: starting and ending a print job, its lines and page breaks, printing it and printing the screen (scrman.cpp) ----------

/// Delivers a print command packet for the current record: a local one (`screen_history::NETWORK_PLAYER` = 0) has it
/// applied to the local Display (`Display::process_command_packet` 0x564080, thiscall, with the session and 0); a
/// remote one has it sent (`scrman_send_packet`, box `scrman.cpp <line>`). Unlike the widget packets there is no echo
/// Display.
unsafe fn scrman_deliver_print(sm: usize, line: u32) {
    use screen_history as h;
    if read_u16(screen_record(sm) + h::NETWORK_PLAYER) == 0 {
        let process: unsafe extern "thiscall" fn(usize, usize, u32, usize) -> u32 = core::mem::transmute(0x564080usize);
        process(sm + h::LOCAL_DISPLAY, read_usize(sm + h::NETWORK), 0, sm + h::NET_BUFFER);
        return;
    }
    covered!("tel38_6 print command for a remote manager");
    scrman_send_packet(sm, line);
}

// simplification: the packet is applied to the Display (it prints or changes the print job) or sent: it does not run
// twice. Original only; the plan: the packet in the buffer, when there was room for it.
/// The comparer of a print command.
unsafe fn compare_scrman_print(name: &str, sm: usize, expected: Vec<u8>, original: impl FnOnce()) {
    let room = read_u32(sm + screen_history::NET_BUFFER_CAPACITY) as usize >= expected.len();
    original();
    scrman_check_packet(name, sm, room, &expected);
}

/// Rule: starts a print job of `columns` columns: the packet command 0x17 and the columns (a word, box line `network.h
/// 134`), delivered (`scrman_deliver_print`, send failure `scrman.cpp 3280`).
/// Original: `ScreenManager::begin_print_job` (0x8033e0, scrman.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn screen_manager_begin_print_job(sm: usize, columns: u32) {
    scrman_command_packet(sm, 0x17); // tel38_6: the begin command
    scrman_net_put(sm, columns, 2, 0x86); // tel38_6: the column count
    scrman_deliver_print(sm, 0xcd0);
}

/// Comparer for `screen_manager_begin_print_job`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_begin_print_job(sm: usize, columns: u32) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, u32)>(IDX_SCREEN_MANAGER_BEGIN_PRINT_JOB);
    compare_scrman_print("screen_manager_begin_print_job", sm, vec![0x17, columns as u8, (columns >> 8) as u8], || o(sm, columns));
}

/// Rule: ends the print job (the Display frees its lines): the packet command 0x18, delivered (send failure
/// `scrman.cpp 3303`).
/// Original: `ScreenManager::end_print_job` (0x8035b0, scrman.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn screen_manager_end_print_job(sm: usize) {
    scrman_command_packet(sm, 0x18);
    scrman_deliver_print(sm, 0xce7);
}

/// Comparer for `screen_manager_end_print_job`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_end_print_job(sm: usize) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize)>(IDX_SCREEN_MANAGER_END_PRINT_JOB);
    compare_scrman_print("screen_manager_end_print_job", sm, vec![0x18], || o(sm));
}

/// Rule: adds a line to the print job: the packet command 0x19 and the text (an empty one for a null pointer) with its
/// length (`scrman_net_put_text`: copied with no room check, defect of the original), delivered (send failure
/// `scrman.cpp 3330`).
/// Original: `ScreenManager::add_print_line` (0x803710, scrman.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn screen_manager_add_print_line(sm: usize, text: usize) {
    let text = if text == 0 { STR_EMPTY } else { text }; // tel38_6: a null line prints empty
    scrman_command_packet(sm, 0x19);
    scrman_net_put_text(sm, text);
    scrman_deliver_print(sm, 0xd02);
}

/// Comparer for `screen_manager_add_print_line`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_add_print_line(sm: usize, text: usize) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, usize)>(IDX_SCREEN_MANAGER_ADD_PRINT_LINE);
    let t = if text == 0 { STR_EMPTY } else { text };
    let len = c_string_len(t) + 1;
    let mut expected = vec![0x19];
    expected.extend_from_slice(&(len as u16).to_le_bytes());
    expected.extend_from_slice(core::slice::from_raw_parts(t as *const u8, len));
    compare_scrman_print("screen_manager_add_print_line", sm, expected, || o(sm, text));
}

/// Rule: adds a page break to the print job (the Display adds a null line): the packet command 0x1a, delivered (send
/// failure `scrman.cpp 3353`).
/// Original: `ScreenManager::add_print_page_break` (0x803930, scrman.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn screen_manager_add_print_page_break(sm: usize) {
    scrman_command_packet(sm, 0x1a);
    scrman_deliver_print(sm, 0xd19);
}

/// Comparer for `screen_manager_add_print_page_break`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_add_print_page_break(sm: usize) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize)>(IDX_SCREEN_MANAGER_ADD_PRINT_PAGE_BREAK);
    compare_scrman_print("screen_manager_add_print_page_break", sm, vec![0x1a], || o(sm));
}

/// Rule: prints the lines of the print job: the packet command 0x16, delivered (send failure `scrman.cpp 3376`).
/// Original: `ScreenManager::print_job` (0x803a90, scrman.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn screen_manager_print_job(sm: usize) {
    scrman_command_packet(sm, 0x16);
    scrman_deliver_print(sm, 0xd30);
}

/// Comparer for `screen_manager_print_job`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_print_job(sm: usize) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize)>(IDX_SCREEN_MANAGER_PRINT_JOB);
    compare_scrman_print("screen_manager_print_job", sm, vec![0x16], || o(sm));
}

/// Rule: prints the screen itself (the Display calls the print routine with no lines): the packet command 0x15,
/// delivered (send failure `scrman.cpp 3399`).
/// Original: `ScreenManager::print_screen` (0x803bf0, scrman.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn screen_manager_print_screen(sm: usize) {
    scrman_command_packet(sm, 0x15); // tel38_6: the print screen command
    scrman_deliver_print(sm, 0xd47);
}

/// Comparer for `screen_manager_print_screen`.
pub(crate) unsafe extern "thiscall" fn compare_screen_manager_print_screen(sm: usize) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize)>(IDX_SCREEN_MANAGER_PRINT_SCREEN);
    compare_scrman_print("screen_manager_print_screen", sm, vec![0x15], || o(sm));
}

// ---------- batch 318: the widget object: filling a new widget and drawing it (Guio.cpp) ----------

/// Widget (`Guio`) fields that neither `display_item` (tel26_1) nor `guio_fields` (tel38_3) names.
mod guio_more {
    /// The Display's area table and item table (pointers given to `Guio::init`).
    pub(crate) const AREAS: usize = 0x0;
    pub(crate) const ITEMS: usize = 0x4;
    /// i32: the column of an area item (field 5; computed for an item in an area).
    pub(crate) const COLUMN: usize = 0x20;
    /// i32 x4: the rectangle as it was built (x1, x2, y1, y2 at +0x28, +0x2c, +0x30, +0x34) [inference: the home of a
    /// dragged widget].
    pub(crate) const HOME_X1: usize = 0x28;
    pub(crate) const HOME_X2: usize = 0x2c;
    pub(crate) const HOME_Y1: usize = 0x30;
    pub(crate) const HOME_Y2: usize = 0x34;
    /// Fields 10 and 16 of `Display::add_item`, kept as they come [inference: the text flags and a link].
    pub(crate) const FIELD_10: usize = 0x3c;
    pub(crate) const FIELD_16: usize = 0x48;
    /// i16: the popup area this widget opens (−1 none; set after `Guio::init`).
    pub(crate) const POPUP_AREA: usize = 0x7c;
    /// u32: an odd row of an area (the next draw darkens the colour once).
    pub(crate) const ODD_ROW: usize = 0x184;
}

/// Area fields `Guio::init` uses that have no name in `display_area` (tel26_1): the widest item text (i32, at least 125),
/// the height so far (i32), the visible item count (i16), the items' list (i16[]), the columns (byte) and the rows added
/// (byte) [inference from the use].
mod guio_area_fields {
    pub(crate) const X1: usize = 0x0;
    pub(crate) const Y1: usize = 0x4;
    pub(crate) const X2: usize = 0x8;
    pub(crate) const Y2: usize = 0xc;
    pub(crate) const INDENT_MODE: usize = 0x20e;
    pub(crate) const ITEM_LIST: usize = 0x212;
    pub(crate) const ITEM_LIST_COUNT: usize = 0xb74;
    pub(crate) const COLUMNS: usize = 0xbab;
    pub(crate) const ROWS_ADDED: usize = 0xbac;
}

/// The shared text image (`Guio::draw` loads a picture named by a widget's text once and lends it to the next widget
/// with the same text).
const GUIO_SHARED_IMAGE: usize = 0xae2a24;
/// "     %s" (the five-space indent of an area item's text).
const GUIO_INDENT_FORMAT: usize = 0x9cdc58;
/// The popup arrows and the marks a widget can carry: each glyph starts with its width and height (bytes).
const GLYPH_POPUP_ABOVE: usize = 0x9cd6bc;
const GLYPH_POPUP_BELOW: usize = 0x9cd6dc;
const GLYPH_POPUP_LEFT: usize = 0x9cd67c;
const GLYPH_POPUP_RIGHT: usize = 0x9cd69c;
const GLYPH_FLAG_2000: usize = 0x9cd6fc;
const GLYPH_FLAG_4000: usize = 0x9cd730;
const GLYPH_FLAG_20000: usize = 0x9cd774;
const GLYPH_FLAG_40000: usize = 0x9cd7bc;
/// The "draw nothing" colour for the arrows (`G_GUI_COLOUR_BLACK`) and the colour of the marks drawn as glyphs.
const GUIO_MARK_COLOUR: usize = 0xaebdd4;

/// Area `a` of a widget's area table (`guio_more::AREAS`).
unsafe fn guio_area_of(item: usize, a: i16) -> usize {
    (read_usize(item + guio_more::AREAS) as isize + a as isize * display_list::AREA_SIZE as isize) as usize
}

/// Rule: a new widget gets its fields: its rectangle put in order and kept inside the screen, and, in an area that
/// indents (`guio_area_fields::INDENT_MODE` ≠ −1), its text indented, its column and row computed and the area grown
/// to fit it.
///
/// `AREAS`, `ITEMS`, `ODD_ROW` = 0. A rectangle with x1 > x2 (y1 > y2), unless style 0x400 without 0x4000, has the two
/// swapped; x1 and y1 below 0 go to 0, x2 and y2 at or above the screen's last column and row (799 and 599, read from
/// the exe: 1919 and 1079 in the 1080 exe) go to it. In an indenting area: the text ("" for null) is written as
/// "     %s"; the area's `X2` grows to the text width (`exe::font_text_width` + 15, at least 125); the column is 0 with
/// one column, otherwise the column after that of the area's last item (walking its list with `display_area::WALK`)
/// modulo the columns; the row is the area's `ROWS_ADDED` (odd: `ODD_ROW` = 1), which goes up; the area's `Y2` grows by
/// the font height + 6. Otherwise the text is copied as it is (no length check) and the row is field 6. Then: `INDEX`,
/// the flags, the rectangle (twice: also in `HOME_*`), the column, the row, the style, the colours (words), field 10,
/// the font, the length limit, the id, field 16, the area, `CURSOR` = −1, `CHANGED` = 0, `BACK_IMAGE` = 0, `POPUP_AREA`
/// = −1, `HIGHLIGHTED` = 0, `HOVER_TIME` = the tick, `DROP_TARGET` = −1, `TEXT_IMAGE` = 0, `ENTRY_TARGET` = the text
/// for a text entry (flag 8) with one, else 0; a text entry with flag 0x10 has its cursor at the end of the text.
/// Original: `Guio::init` (0x5ee150, Guio.cpp, thiscall, ret 0x54).
#[allow(clippy::too_many_arguments)]
pub(crate) unsafe extern "thiscall" fn guio_init(item: usize, areas: usize, items: usize, index: u32, flags: u32, x1: i32, y1: i32, x2: i32, y2: i32,
    column: i32, row: i32, style: u32, colour: u32, highlight: u32, field_10: u32, font: u32, text_colour: u32, text: usize, max_length: u32,
    id: u32, field_16: u32, area: u32) {
    use display_item as d;
    use guio_area_fields as af;
    use guio_fields as g;
    use guio_more as m;
    let (mut x1, mut y1, mut x2, mut y2, mut column, mut row) = (x1, y1, x2, y2, column, row);
    write_usize(item + m::AREAS, areas);
    write_usize(item + m::ITEMS, items);
    write_u32(item + m::ODD_ROW, 0);
    let swaps = style & 0x400 == 0 || style & 0x4000 != 0;
    if x1 > x2 && swaps {
        core::mem::swap(&mut x1, &mut x2);
    }
    if y1 > y2 && swaps {
        core::mem::swap(&mut y1, &mut y2);
    }
    x1 = x1.max(0);
    y1 = y1.max(0);
    let (last_x, last_y) = (exe_immediate(0x5ee1f6 as *const i32), exe_immediate(0x5ee20b as *const i32));
    if x2 >= last_x {
        x2 = last_x; // tel38_7: kept inside the screen
    }
    if y2 >= last_y {
        y2 = last_y;
    }
    let a = area as i16;
    let format: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(FN_CRT_SPRINTF);
    if a != -1 && read_i16(guio_area_of(item, a) + af::INDENT_MODE) != -1 {
        covered!("tel38_7 area item");
        let ar = guio_area_of(item, a);
        format(item + d::TEXT, GUIO_INDENT_FORMAT, if text == 0 { STR_EMPTY } else { text });
        let width = (exe::font_text_width(font as usize, (item + d::TEXT) as *const u8) + 0xf).max(0x7d);
        if width > read_i32(ar + af::X2) {
            write_i32(ar + af::X2, width);
        }
        let columns = read_u8(ar + af::COLUMNS);
        if columns == 1 {
            column = 0;
        } else {
            let mut last = 0i32;
            write_u16(ar + display_area::WALK, 0);
            loop {
                let w = read_i16(ar + display_area::WALK);
                if w >= read_i16(ar + af::ITEM_LIST_COUNT) {
                    break;
                }
                let k = read_i16(ar + af::ITEM_LIST + w as usize * 2);
                write_i16(ar + display_area::WALK, w + 1);
                if k == -1 {
                    break;
                }
                last = read_i32((items as isize + k as isize * display_list::ITEM_SIZE as isize) as usize + m::COLUMN);
            }
            column = (last + 1) % columns as i32; // tel38_7: the column after the last item's
        }
        let added = read_u8(ar + af::ROWS_ADDED);
        let height = exe::font_get_height(font as i32);
        write_i32(ar + af::Y2, height + read_i32(ar + af::Y2) + 6);
        if added & 1 != 0 { // tel38_7: the odd rows
            write_u32(item + m::ODD_ROW, 1);
        }
        write_u8(ar + af::ROWS_ADDED, added.wrapping_add(1));
        row = added as i32;
    } else {
        copy_c_string(item + d::TEXT, if text == 0 { STR_EMPTY } else { text });
    }
    write_u16(item + g::INDEX, index as u16);
    write_u32(item + d::FLAGS, flags);
    write_i32(item + d::X1, x1);
    write_i32(item + m::HOME_X1, x1);
    write_i32(item + d::Y1, y1);
    write_i32(item + m::HOME_Y1, y1);
    write_u16(item + g::COLOUR, colour as u16);
    write_i32(item + d::Y2, y2);
    write_i32(item + m::HOME_Y2, y2);
    write_u32(item + d::STYLE, style);
    write_u16(item + d::FONT, font as u16);
    write_i32(item + d::X2, x2);
    write_i32(item + m::HOME_X2, x2);
    write_i32(item + m::COLUMN, column);
    write_u16(item + g::HIGHLIGHT_COLOUR, highlight as u16);
    write_u32(item + m::FIELD_10, field_10);
    write_u32(item + d::ID, id);
    write_u16(item + g::TEXT_COLOUR, text_colour as u16);
    write_u32(item + d::MAX_LENGTH, max_length);
    write_u32(item + m::FIELD_16, field_16);
    write_i32(item + d::ROW, row);
    write_i32(item + d::CURSOR, -1);
    write_u32(item + d::CHANGED, 0);
    write_usize(item + d::BACK_IMAGE, 0);
    write_u16(item + d::AREA, area as u16);
    write_i16(item + m::POPUP_AREA, -1);
    write_u32(item + d::HIGHLIGHTED, 0);
    write_u32(item + d::HOVER_TIME, read_u32(DISPLAY_TICKS));
    write_i16(item + d::DROP_TARGET, -1);
    write_usize(item + g::TEXT_IMAGE, 0);
    let entry = flags & 8 != 0;
    write_usize(item + g::ENTRY_TARGET, if text != 0 && entry { text } else { 0 });
    if entry && flags & 0x10 != 0 {
        write_i32(item + d::CURSOR, c_string_len(item + d::TEXT) as i32);
    }
}

/// Comparer for `guio_init`: side by side over the widget and, for an area item, its area.
#[allow(clippy::too_many_arguments)]
pub(crate) unsafe extern "thiscall" fn compare_guio_init(item: usize, areas: usize, items: usize, index: u32, flags: u32, x1: i32, y1: i32, x2: i32,
    y2: i32, column: i32, row: i32, style: u32, colour: u32, highlight: u32, field_10: u32, font: u32, text_colour: u32, text: usize,
    max_length: u32, id: u32, field_16: u32, area: u32) {
    type F = unsafe extern "thiscall" fn(usize, usize, usize, u32, u32, i32, i32, i32, i32, i32, i32, u32, u32, u32, u32, u32, u32, usize, u32, u32,
        u32, u32);
    let o = original_fn::<F>(IDX_GUIO_INIT);
    let mut regions = vec![(item, display_list::ITEM_SIZE)];
    let a = area as i16;
    if (0..0xf9).contains(&a) {
        regions.push(((areas as isize + a as isize * display_list::AREA_SIZE as isize) as usize, display_list::AREA_SIZE));
    }
    let (_, _, equal, mo, mr) = crate::comparison::side_by_side(&regions,
        || o(item, areas, items, index, flags, x1, y1, x2, y2, column, row, style, colour, highlight, field_10, font, text_colour, text, max_length, id,
            field_16, area),
        || guio_init(item, areas, items, index, flags, x1, y1, x2, y2, column, row, style, colour, highlight, field_10, font, text_colour, text,
            max_length, id, field_16, area));
    SCOREBOARD.record(equal, || format!("guio_init(item {}, area {}): differences in {:?}", index as i16, a, first_differences(&mo, &mr)));
}

/// `gui_draw_glyph(x, y, colour, glyph)` (0x5e3ce0, cdecl): a one-colour glyph on the back buffer.
unsafe fn guio_glyph(x: i32, y: i32, colour: u32, glyph: usize) {
    let f: unsafe extern "C" fn(i32, i32, u32, usize) = core::mem::transmute(0x5e3ce0usize);
    f(x, y, colour, glyph);
}

/// `gui_draw_text_box(x1, y1, x2, y2, flags, font, colour, text, caret)` (0x5e6d80, cdecl): word-wrapped text.
#[allow(clippy::too_many_arguments)]
unsafe fn guio_text_box(x1: i32, y1: i32, x2: i32, y2: i32, flags: u32, font: u32, colour: u32, text: usize, caret: i32) {
    let f: unsafe extern "C" fn(i32, i32, i32, i32, u32, u32, u32, usize, i32) = core::mem::transmute(0x5e6d80usize);
    f(x1, y1, x2, y2, flags, font, colour, text, caret);
}

/// Where a glyph of size `size` is centred between `lo` and `hi` (the original's halving rounds toward zero).
fn guio_centre(lo: i32, hi: i32, size: i32) -> i32 {
    (hi - size - lo + 1) / 2 + lo
}

/// A popup arrow at the widget's right edge (`at_left`: its left edge) when it has a text, otherwise centred; centred
/// in height; `dx`, `dy` = the pressed offset.
unsafe fn guio_popup_arrow(item: usize, glyph: usize, at_left: bool, dx: i32, dy: i32, colour: u32) {
    use display_item as d;
    let (w, h) = (read_u8(glyph) as i32, read_u8(glyph + 1) as i32);
    let (x1, x2) = (read_i32(item + d::X1), read_i32(item + d::X2));
    let x = if c_string_len(item + d::TEXT) != 0 {
        if at_left { x1 + dx + 4 } else { x2 - w + dx - 4 }
    } else {
        guio_centre(x1, x2, w) + dx
    };
    guio_glyph(x, guio_centre(read_i32(item + d::Y1), read_i32(item + d::Y2), h) + dy, colour, glyph);
}

/// One of the marks of flags 0x4000, 0x20000 and 0x40000: with the symbol font (`G_FONT_MODE` ≠ −1) the symbol `code`
/// as a text box (flags 0x48, font 0, the text colour) over the widget less 4 at the right; otherwise `glyph` at the
/// right edge in `colour`.
unsafe fn guio_mark(item: usize, code: u32, glyph: usize, colour: u32, dx: i32, dy: i32) {
    use display_item as d;
    let (x1, y1, x2, y2) = (read_i32(item + d::X1), read_i32(item + d::Y1), read_i32(item + d::X2), read_i32(item + d::Y2));
    if read_i32(G_FONT_MODE) != -1 {
        let mut symbol = [0u8; 4];
        let format: unsafe extern "C" fn(*mut u8, usize, ...) -> i32 = core::mem::transmute(FN_CRT_SPRINTF);
        format(symbol.as_mut_ptr(), 0x99ec1c, code);
        guio_text_box(x1 + dx, y1 + dy, x2 + dx - 4, y2 + dy, 0x48, 0, read_u16(item + guio_fields::TEXT_COLOUR) as u32, symbol.as_ptr() as usize, -1);
    } else {
        let (w, h) = (read_u8(glyph) as i32, read_u8(glyph + 1) as i32);
        guio_glyph(x2 - w + dx - 4, guio_centre(y1, y2, h) + dy, colour, glyph);
    }
}

/// The arrow colour: `G_GUI_COLOUR_BLACK`, or `G_GUI_COLOUR_PALE_GREY` on a widget of that colour.
unsafe fn guio_arrow_colour(item: usize) -> u32 {
    let black = read_u16(G_GUI_COLOUR_BLACK);
    (if read_u16(item + guio_fields::COLOUR) == black { read_u16(G_GUI_COLOUR_PALE_GREY) } else { black }) as u32
}

/// Rule: draws a widget: its panel, its picture, the arrow towards the popup it opens, its marks and its text, pressed
/// down 2 pixels when highlighted with style 0x20 (or with style 0x40).
///
/// An odd area row (`guio_more::ODD_ROW`) darkens its colour once (`gui_scale_colour` 0x5e4890, 110%, the flag back to
/// 0). With `refresh` the saved background is freed; with no style 0x10 and none saved, the screen under the widget is
/// saved (`exe::gui_save_screen_image`). A picture widget (flag 0x400) with no image: the shared image when its text
/// is the shared name and there is one (the count goes up), otherwise the picture is loaded (`gui_load_rgn_picture`
/// 0x5e40d0) and, when nobody shares the current one (count 0), it becomes the shared image (the old one freed, the
/// name copied, the count 1). The image is put on the screen. The panel (`exe::gui_draw_panel`: the rectangle, the
/// style, the colour, the text colour; highlighted: the highlight colour and, with style 0x20 and no flag 4, style
/// 0x40; style 0x40 presses it 2 pixels right and down). With a popup area and no flag 0x80: the popup's position
/// (`Area::get_popup_position`); its bottom above the widget: the up arrow; its top below the widget: the down
/// arrow; else its right edge left of the widget: the left arrow; else its left edge right of it: the right arrow
/// (`guio_popup_arrow`, colour `guio_arrow_colour`). Flag 0x2000: a glyph at the left edge. Flags 0x4000, 0x20000,
/// 0x40000: the marks '+', ',' and '-' (`guio_mark`). A widget without flag 0x400: with flag 0x800 the text is cut at
/// its first byte 1 while drawn; the text box (`gui_draw_text_box`: the rectangle pressed, field 10, the font, the
/// text colour, the text, the cursor), then the byte 1 comes back.
/// Original: `Guio::draw` (0x5ee590, Guio.cpp, thiscall, ret 4).
pub(crate) unsafe extern "thiscall" fn guio_draw(item: usize, refresh: u32) {
    use display_item as d;
    use guio_fields as g;
    use guio_more as m;
    if read_u32(item + m::ODD_ROW) != 0 {
        write_u32(item + m::ODD_ROW, 0); // tel38_7: the darkening only once
        let scale: unsafe extern "C" fn(u32, u32, usize) -> u16 = core::mem::transmute(0x5e4890usize);
        write_u16(item + g::COLOUR, scale(read_u16(item + g::COLOUR) as u32, 0x6e, 0)); // tel38_7: an odd row darkened
    }
    if read_usize(item + d::BACK_IMAGE) != 0 && refresh != 0 {
        exe::gui_free_image(read_usize(item + d::BACK_IMAGE));
        write_usize(item + d::BACK_IMAGE, 0);
    }
    if read_u8(item + d::STYLE) & 0x10 == 0 && read_usize(item + d::BACK_IMAGE) == 0 {
        let image = exe::gui_save_screen_image(read_i32(item + d::X1), read_i32(item + d::Y1), read_i32(item + d::X2), read_i32(item + d::Y2), 0usize);
        write_usize(item + d::BACK_IMAGE, image);
    }
    if read_u32(item + d::FLAGS) & 0x400 != 0 && read_usize(item + g::TEXT_IMAGE) == 0 {
        covered!("tel38_7 picture widget");
        if guio_same_c_string(GUIO_SHARED_IMAGE_NAME, item + d::TEXT) && read_usize(GUIO_SHARED_IMAGE) != 0 {
            write_usize(item + g::TEXT_IMAGE, read_usize(GUIO_SHARED_IMAGE));
            write_i16(GUIO_SHARED_IMAGE_COUNT, read_i16(GUIO_SHARED_IMAGE_COUNT).wrapping_add(1));
        } else {
            let load: unsafe extern "C" fn(usize, usize) -> usize = core::mem::transmute(0x5e40d0usize);
            let image = load(item + d::TEXT, 0);
            write_usize(item + g::TEXT_IMAGE, image);
            if image != 0 && read_i16(GUIO_SHARED_IMAGE_COUNT) == 0 {
                let old = read_usize(GUIO_SHARED_IMAGE);
                if old != 0 {
                    exe::gui_free_image(old);
                }
                write_usize(GUIO_SHARED_IMAGE, read_usize(item + g::TEXT_IMAGE));
                copy_c_string(GUIO_SHARED_IMAGE_NAME, item + d::TEXT);
                write_u16(GUIO_SHARED_IMAGE_COUNT, 1);
            }
        }
    }
    let image = read_usize(item + g::TEXT_IMAGE);
    if image != 0 {
        gui_restore_background(read_u32(item + d::X1), read_u32(item + d::Y1), image);
    }
    let mut style = read_u32(item + d::STYLE);
    let mut colour = read_u16(item + g::COLOUR);
    if read_u32(item + d::HIGHLIGHTED) != 0 {
        colour = read_u16(item + g::HIGHLIGHT_COLOUR);
        if style & 0x20 != 0 && read_u32(item + d::FLAGS) & 4 == 0 {
            style |= 0x40; // tel38_7: a highlighted button pressed
        }
    }
    let (dx, dy) = if style & 0x40 != 0 { (2, 2) } else { (0, 0) };
    exe::gui_draw_panel(read_i32(item + d::X1), read_i32(item + d::Y1), read_i32(item + d::X2), read_i32(item + d::Y2), style, colour as u32,
        read_u16(item + g::TEXT_COLOUR) as u32);
    let flags = read_u32(item + d::FLAGS);
    let popup = read_i16(item + m::POPUP_AREA);
    if popup != -1 && flags & 0x80 == 0 {
        use guio_area_fields as af;
        let ar = guio_area_of(item, popup);
        let (mut px, mut py) = (0i32, 0i32);
        let position: unsafe extern "thiscall" fn(usize, *mut i32, *mut i32) = core::mem::transmute(0x403760usize);
        position(ar, &mut px, &mut py);
        let arrow = guio_arrow_colour(item);
        let ar = guio_area_of(item, read_i16(item + m::POPUP_AREA));
        if read_i32(ar + af::Y2) - read_i32(ar + af::Y1) + py < read_i32(item + d::Y1) {
            guio_popup_arrow(item, GLYPH_POPUP_ABOVE, false, dx, dy, arrow);
        } else if py > read_i32(item + d::Y2) {
            guio_popup_arrow(item, GLYPH_POPUP_BELOW, false, dx, dy, arrow);
        } else if read_i32(ar + af::X2) - read_i32(ar + af::X1) + px < read_i32(item + d::X1) {
            guio_popup_arrow(item, GLYPH_POPUP_LEFT, true, dx, dy, arrow);
        } else if px > read_i32(item + d::X2) {
            guio_popup_arrow(item, GLYPH_POPUP_RIGHT, false, dx, dy, arrow);
        }
    }
    if flags & 0x2000 != 0 {
        let h = read_u8(GLYPH_FLAG_2000 + 1) as i32;
        guio_glyph(read_i32(item + d::X1) + dx + 4, guio_centre(read_i32(item + d::Y1), read_i32(item + d::Y2), h) + dy, guio_arrow_colour(item),
            GLYPH_FLAG_2000);
    }
    if flags & 0x4000 != 0 {
        guio_mark(item, 0x2b, GLYPH_FLAG_4000, read_u16(GUIO_MARK_COLOUR) as u32, dx, dy);
    }
    if read_u32(item + d::FLAGS) & 0x20000 != 0 {
        guio_mark(item, 0x2c, GLYPH_FLAG_20000, read_u16(GUIO_MARK_COLOUR) as u32, dx, dy);
    }
    if read_u32(item + d::FLAGS) & 0x40000 != 0 {
        guio_mark(item, 0x2d, GLYPH_FLAG_40000, read_u16(G_GUI_COLOUR_RED) as u32, dx, dy);
    }
    let flags = read_u32(item + d::FLAGS);
    if flags & 0x400 != 0 {
        return;
    }
    let mut cut = None;
    if flags & 0x800 != 0 {
        let mut k = 0;
        while read_u8(item + d::TEXT + k) != 1 && read_u8(item + d::TEXT + k) != 0 {
            k += 1;
        }
        if read_u8(item + d::TEXT + k) == 1 {
            write_u8(item + d::TEXT + k, 0);
            cut = Some(k);
        }
    }
    guio_text_box(read_i32(item + d::X1) + dx, read_i32(item + d::Y1) + dy, read_i32(item + d::X2) + dx, read_i32(item + d::Y2) + dy,
        read_u32(item + m::FIELD_10), read_u16(item + d::FONT) as u32, read_u16(item + g::TEXT_COLOUR) as u32, item + d::TEXT, read_i32(item + d::CURSOR));
    if let Some(k) = cut {
        write_u8(item + d::TEXT + k, 1);
    }
}

// simplification: draws on the screen and saves or frees images: it does not run twice. Original only; the plan: the
// odd row flag cleared and the text as it was (the byte 1 back).
/// Comparer for `guio_draw`.
pub(crate) unsafe extern "thiscall" fn compare_guio_draw(item: usize, refresh: u32) {
    let text = core::slice::from_raw_parts((item + display_item::TEXT) as *const u8, 0x100).to_vec();
    original_fn::<unsafe extern "thiscall" fn(usize, u32)>(IDX_GUIO_DRAW)(item, refresh);
    let after = core::slice::from_raw_parts((item + display_item::TEXT) as *const u8, 0x100);
    let odd = read_u32(item + guio_more::ODD_ROW);
    SCOREBOARD.record(odd == 0 && after == &text[..], || format!("guio_draw({:#x}): odd row {} text changed {}", item, odd, after != &text[..]));
}

// ---------- batch 318: the line graph: building a plot, its series and points, and drawing it with its axes (plot.cpp) ----------

/// A line graph (`Plot`, 0x1c bytes): the series array, the value range (from and to on each axis; "to" may be below
/// "from", which turns the axis around), how many series there are and how many fit.
mod plot_fields {
    pub(crate) const SERIES: usize = 0x0;
    pub(crate) const X_FROM: usize = 0x4;
    pub(crate) const Y_FROM: usize = 0x8;
    pub(crate) const X_TO: usize = 0xc;
    pub(crate) const Y_TO: usize = 0x10;
    pub(crate) const SERIES_COUNT: usize = 0x14;
    pub(crate) const SERIES_CAPACITY: usize = 0x18;
    pub(crate) const SIZE: usize = 0x1c;
}

/// A plot series (0x12 bytes, packed): its points (x, y dwords), how many fit and how many there are, its colour
/// (word) and its label (a copy).
mod plot_series {
    pub(crate) const POINTS: usize = 0x0;
    pub(crate) const CAPACITY: usize = 0x4;
    pub(crate) const COUNT: usize = 0x8;
    pub(crate) const COLOUR: usize = 0xc;
    pub(crate) const LABEL: usize = 0xe;
    pub(crate) const SIZE: usize = 0x12;
}

/// "E:\dev\CM3\cm3 00-01\si\code\plot.cpp" (the error boxes) and "%d" (the axis labels).
const PLOT_CPP: usize = 0xa7853c;
const PLOT_NUMBER_FORMAT: usize = 0x98806c;

/// Series `s` of a plot.
unsafe fn plot_series_at(plot: usize, s: i32) -> usize {
    (read_usize(plot + plot_fields::SERIES) as isize + s as isize * plot_series::SIZE as isize) as usize
}

/// The magnitude of a value (the original's cdq/xor/sub).
fn plot_abs(v: i32) -> i32 {
    v.wrapping_abs()
}

/// A value's position on an axis drawn from `lo` to `hi` over the range `from`..`to`: `|(v − from) × (hi − lo) / |to −
/// from||` from `lo`, or from `hi` backwards when `to` is not above `from`.
fn plot_scale(v: i32, from: i32, to: i32, length: i32, lo: i32, hi: i32) -> i32 {
    let q = plot_abs(v.wrapping_sub(from).wrapping_mul(length).wrapping_div(plot_abs(to.wrapping_sub(from))));
    if to > from { q.wrapping_add(lo) } else { hi.wrapping_sub(q) }
}

/// Rule: a new plot keeps its value range and room for `capacity` series; no room asked (`capacity` < 1): no array.
///
/// `X_FROM`, `Y_FROM`, `X_TO`, `Y_TO` = the four values, `SERIES_CAPACITY` = `capacity`, `SERIES_COUNT` = 0; the
/// series array (`exe::crt_malloc`, 0x12 bytes each, not zeroed); out of memory: the box `plot.cpp 47`. Returns the
/// plot.
/// Original: `Plot::Plot` (0x7c6fc0, plot.cpp, thiscall, ret 0x14).
pub(crate) unsafe extern "thiscall" fn construct_plot(plot: usize, x_from: i32, y_from: i32, x_to: i32, y_to: i32, capacity: i32) -> usize {
    use plot_fields as p;
    write_i32(plot + p::X_FROM, x_from);
    write_i32(plot + p::Y_FROM, y_from);
    write_i32(plot + p::X_TO, x_to);
    write_i32(plot + p::Y_TO, y_to);
    write_i32(plot + p::SERIES_CAPACITY, capacity);
    write_u32(plot + p::SERIES_COUNT, 0);
    if capacity < 1 {
        write_usize(plot + p::SERIES, 0);
        return plot;
    }
    let series = exe::crt_malloc((capacity as u32).wrapping_mul(plot_series::SIZE as u32));
    write_usize(plot + p::SERIES, series);
    if series == 0 {
        show_error_at(PLOT_CPP, 0x2f);
    }
    plot
}

// simplification: allocates the series array: it does not run twice. Original only; the plan: the range, the capacity,
// no series yet and an array exactly when room was asked.
/// Comparer for `construct_plot`.
pub(crate) unsafe extern "thiscall" fn compare_construct_plot(plot: usize, x_from: i32, y_from: i32, x_to: i32, y_to: i32, capacity: i32) -> usize {
    use plot_fields as p;
    let r = original_fn::<unsafe extern "thiscall" fn(usize, i32, i32, i32, i32, i32) -> usize>(IDX_CONSTRUCT_PLOT)(plot, x_from, y_from, x_to, y_to, capacity);
    let ok = r == plot && read_i32(plot + p::X_FROM) == x_from && read_i32(plot + p::Y_FROM) == y_from && read_i32(plot + p::X_TO) == x_to
        && read_i32(plot + p::Y_TO) == y_to && read_i32(plot + p::SERIES_CAPACITY) == capacity && read_u32(plot + p::SERIES_COUNT) == 0
        && (capacity >= 1 || read_usize(plot + p::SERIES) == 0);
    SCOREBOARD.record(ok, || format!("construct_plot({}, {}, {}, {}, {}): the fields came out otherwise", x_from, y_from, x_to, y_to, capacity));
    r
}

/// Rule: a plot is freed: for every slot of the series array (all `SERIES_CAPACITY` of them) its points and its label,
/// then the array (`exe::crt_free`); nothing without an array. Defect of the original: the slots past `SERIES_COUNT`
/// were never written (the array is not zeroed), so a plot with fewer series than room frees leftover pointers.
/// Original: `Plot::~Plot` (0x7c70a0, plot.cpp, thiscall).
pub(crate) unsafe extern "thiscall" fn destroy_plot(plot: usize) {
    use plot_series as s;
    if read_usize(plot + plot_fields::SERIES) == 0 {
        return;
    }
    let mut k = 0;
    while k < read_i32(plot + plot_fields::SERIES_CAPACITY) {
        let slot = plot_series_at(plot, k);
        if read_usize(slot + s::POINTS) != 0 {
            exe::crt_free(read_usize(slot + s::POINTS));
        }
        let slot = plot_series_at(plot, k);
        if read_usize(slot + s::LABEL) != 0 {
            exe::crt_free(read_usize(slot + s::LABEL)); // tel38_8: each slot's label freed
        }
        k += 1;
    }
    exe::crt_free(read_usize(plot + plot_fields::SERIES));
}

// simplification: frees memory: it does not run twice and leaves nothing to check. Original only.
/// Comparer for `destroy_plot`.
pub(crate) unsafe extern "thiscall" fn compare_destroy_plot(plot: usize) {
    original_fn::<unsafe extern "thiscall" fn(usize)>(IDX_DESTROY_PLOT)(plot);
}

/// Rule: a new series with room for `capacity` points, a colour and a copy of its label; no room left in the plot
/// (`SERIES_COUNT` ≥ `SERIES_CAPACITY`): the box `plot.cpp 86` and nothing.
///
/// The points array (`exe::crt_malloc`, 8 bytes a point) goes to the next slot; with none and `capacity` > 0: the box
/// `plot.cpp 94` and nothing more. Then the slot's capacity, no points yet, the colour, the label (`_strdup` 0x952f5b)
/// and the series count goes up.
/// Original: `Plot::add_series` (0x7c7100, plot.cpp, thiscall, ret 0xc).
pub(crate) unsafe extern "thiscall" fn plot_append_series(plot: usize, capacity: i32, colour: u32, label: usize) {
    use plot_fields as p;
    use plot_series as s;
    if read_i32(plot + p::SERIES_COUNT) >= read_i32(plot + p::SERIES_CAPACITY) {
        show_error_at(PLOT_CPP, 0x56);
        return;
    }
    let points = exe::crt_malloc((capacity as u32).wrapping_mul(8));
    write_usize(plot_series_at(plot, read_i32(plot + p::SERIES_COUNT)) + s::POINTS, points);
    let slot = plot_series_at(plot, read_i32(plot + p::SERIES_COUNT));
    if read_usize(slot + s::POINTS) == 0 && capacity > 0 {
        show_error_at(PLOT_CPP, 0x5e);
        return;
    }
    write_i32(slot + s::CAPACITY, capacity);
    write_u32(plot_series_at(plot, read_i32(plot + p::SERIES_COUNT)) + s::COUNT, 0);
    write_u16(plot_series_at(plot, read_i32(plot + p::SERIES_COUNT)) + s::COLOUR, colour as u16);
    let strdup: unsafe extern "C" fn(usize) -> usize = core::mem::transmute(0x952f5busize);
    let copy = strdup(label);
    write_usize(plot_series_at(plot, read_i32(plot + p::SERIES_COUNT)) + s::LABEL, copy);
    write_i32(plot + p::SERIES_COUNT, read_i32(plot + p::SERIES_COUNT) + 1); // tel38_8: one series more
}

// simplification: allocates the points and the label copy: it does not run twice. Original only; the plan: with room,
// one series more with the capacity, no points and the colour.
/// Comparer for `plot_append_series`.
pub(crate) unsafe extern "thiscall" fn compare_plot_append_series(plot: usize, capacity: i32, colour: u32, label: usize) {
    use plot_fields as p;
    use plot_series as s;
    let n = read_i32(plot + p::SERIES_COUNT);
    let room = n < read_i32(plot + p::SERIES_CAPACITY);
    original_fn::<unsafe extern "thiscall" fn(usize, i32, u32, usize)>(IDX_PLOT_APPEND_SERIES)(plot, capacity, colour, label);
    if !room {
        return;
    }
    let slot = plot_series_at(plot, n);
    let ok = read_usize(slot + s::POINTS) == 0
        || (read_i32(plot + p::SERIES_COUNT) == n + 1 && read_i32(slot + s::CAPACITY) == capacity && read_i32(slot + s::COUNT) == 0
            && read_u16(slot + s::COLOUR) == colour as u16);
    SCOREBOARD.record(ok, || format!("plot_append_series({}, colour {:#x}): series {} came out otherwise", capacity, colour, n));
}

/// Rule: a point (x, y) is appended to series `series`; a series past the plot's room (`SERIES_CAPACITY`, not the
/// series count) gives the box `plot.cpp 117`, a full series the box `plot.cpp 123`, and nothing is added.
/// Original: `Plot::add_point` (0x7c7240, plot.cpp, thiscall, ret 0xc).
pub(crate) unsafe extern "thiscall" fn plot_append_point(plot: usize, series: i32, x: i32, y: i32) {
    use plot_series as s;
    if series >= read_i32(plot + plot_fields::SERIES_CAPACITY) {
        show_error_at(PLOT_CPP, 0x75);
        return;
    }
    let slot = plot_series_at(plot, series);
    let n = read_i32(slot + s::COUNT);
    if n >= read_i32(slot + s::CAPACITY) {
        show_error_at(PLOT_CPP, 0x7b);
        return;
    }
    let point = read_usize(slot + s::POINTS) + n as usize * 8;
    write_i32(point, x);
    write_i32(point + 4, y); // tel38_8: the point's value
    write_i32(slot + s::COUNT, n + 1);
}

/// Comparer for `plot_append_point`: side by side over the series and its next point (the error paths only through the
/// original: the box would show twice).
pub(crate) unsafe extern "thiscall" fn compare_plot_append_point(plot: usize, series: i32, x: i32, y: i32) {
    use plot_series as s;
    let o = original_fn::<unsafe extern "thiscall" fn(usize, i32, i32, i32)>(IDX_PLOT_APPEND_POINT);
    if series >= read_i32(plot + plot_fields::SERIES_CAPACITY) {
        return o(plot, series, x, y);
    }
    let slot = plot_series_at(plot, series);
    let n = read_i32(slot + s::COUNT);
    if n >= read_i32(slot + s::CAPACITY) {
        return o(plot, series, x, y);
    }
    let regions = [(slot, s::SIZE), (read_usize(slot + s::POINTS) + n as usize * 8, 8)];
    let (_, _, equal, mo, mr) = crate::comparison::side_by_side_light(&regions, || o(plot, series, x, y), || plot_append_point(plot, series, x, y));
    SCOREBOARD.record(equal, || format!("plot_append_point(series {}, {}, {}): differences in {:?}", series, x, y, first_differences(&mo, &mr)));
}

/// `Display::add_item` on the screen manager's current slot: a line (type 1, style 0x400) from (x1, y1) to (x2, y2)
/// in `colour`, no area.
unsafe fn plot_line(x1: i32, y1: i32, x2: i32, y2: i32, colour: u32) {
    let add: DisplayAddItemFn = core::mem::transmute(FN_DISPLAY_ADD_ITEM);
    add(screens_current_display(SCREEN_MANAGER), 1, x1 as u32, y1 as u32, x2 as u32, y2 as u32, 0, 0, 0x400, colour, 0, 0, 0, 0, 0, 0, 0, 0, u32::MAX);
}

/// `ScreenManager::add_text_item(x1, y1, x2, y2, 0, colour, font, 1, colour, text, 1)` with `G_GUI_COLOUR_PALE_GREY`.
unsafe fn plot_label(x1: i32, y1: i32, x2: i32, y2: i32, font: u32, text: usize) {
    let add: unsafe extern "thiscall" fn(usize, i32, i32, i32, i32, u32, u32, u32, u32, u32, usize, u32) -> u16 =
        core::mem::transmute(FN_SCREENMANAGER_ADD_TEXT_ITEM);
    let colour = read_u16(G_GUI_COLOUR_PALE_GREY) as u32;
    add(SCREEN_MANAGER, x1, y1, x2, y2, 0, colour, font, 1, colour, text, 1);
}

/// Rule: a graph's frame: an area over the box, its four sides as double lines, the two titles and the numbered ticks
/// of both axes; with `pad` = 1 each range is one wider while drawn.
///
/// With `pad`: `X_TO` + 1 and the larger of `Y_FROM`/`Y_TO` + 1 for the area, undone after it. The area
/// (`Display::add_area`: the box, |x range| columns, |y range| rows, style 0x80000, no owner). The sides, each a line
/// and a second one a pixel outside (`plot_line`): left and top in `G_GUI_COLOUR_BLUE`, bottom and right in
/// `G_GUI_COLOUR_BLACK`. The x title under the box ((x0, y1 + 20)–(x1, y1 + 30), font 0xc), the y title over it ((x0,
/// y0 − 20)–(x1, y0), font 1). The x step: the smallest from 1 that puts the ticks more than 15 pixels apart (at most
/// the range); each x value from `X_FROM` to `X_TO` by the step gets its number ("%d") under the box: with `pad`
/// between its position and the next one's, otherwise 20 pixels wide around it (`plot_scale`). The y step: the
/// smallest that puts the ticks more than 10 pixels apart; each y value from the lower to the higher end gets its
/// number left of the box, 20 pixels wide (with `pad` between its position and the next one's, the higher end + 1
/// while computed). A range of 0 divides by zero, as in the original.
/// Original: `Plot::draw_axes` (0x7c7580, plot.cpp, thiscall, ret 0x1c).
#[allow(clippy::too_many_arguments)]
pub(crate) unsafe extern "thiscall" fn plot_draw_axes(plot: usize, x0: i32, y0: i32, x1: i32, y1: i32, pad: i32, x_title: usize, y_title: usize) {
    use plot_fields as p;
    let get = |f: usize| read_i32(plot + f);
    let set = |f: usize, v: i32| write_i32(plot + f, v);
    let widen = |by: i32| {
        set(p::X_TO, get(p::X_TO) + by);
        let (yf, yt) = (get(p::Y_FROM), get(p::Y_TO));
        if yf.max(yt) == yt { set(p::Y_TO, yt + by) } else { set(p::Y_FROM, yf + by) }
    };
    if pad == 1 {
        widen(1);
    }
    let add_area: DisplayAddAreaFn = core::mem::transmute(FN_DISPLAY_ADD_AREA);
    add_area(screens_current_display(SCREEN_MANAGER), x0 as u32, y0 as u32, x1 as u32, y1 as u32, plot_abs(get(p::X_TO) - get(p::X_FROM)) as u32, 0,
        plot_abs(get(p::Y_TO) - get(p::Y_FROM)) as u32, 0, 0x80000, 0, u32::MAX);
    if pad == 1 {
        widen(-1);
    }
    let (blue, black) = (read_u16(G_GUI_COLOUR_BLUE) as u32, read_u16(G_GUI_COLOUR_BLACK) as u32);
    plot_line(x0, y0, x0, y1, blue);
    plot_line(x0 - 1, y0 - 1, x0 - 1, y1 + 1, blue);
    plot_line(x0, y1, x1, y1, black);
    plot_line(x0 - 1, y1 + 1, x1 + 1, y1 + 1, black);
    plot_line(x1, y0, x1, y1, black);
    plot_line(x1 + 1, y0 - 1, x1 + 1, y1 + 1, black);
    plot_line(x0, y0, x1, y0, blue); // tel38_8: the top side
    plot_line(x0 - 1, y0 - 1, x1 + 1, y0 - 1, blue);
    plot_label(x0, y1 + 0x14, x1, y1 + 0x1e, 0xc, x_title);
    plot_label(x0, y0 - 0x14, x1, y0, 1, y_title);
    let mut number = [0u8; 20];
    let format: unsafe extern "C" fn(*mut u8, usize, ...) -> i32 = core::mem::transmute(FN_CRT_SPRINTF);
    // the x ticks
    let width = x1 - x0;
    let range = get(p::X_TO) - get(p::X_FROM);
    let mut step = 1;
    if range > 1 {
        let mut gap = width;
        loop {
            if gap.wrapping_div(plot_abs(range)) > 0xf {
                break;
            }
            step += 1;
            gap = gap.wrapping_add(width);
            if step >= range {
                break;
            }
        }
    }
    let mut v = get(p::X_FROM);
    while v <= get(p::X_TO) {
        format(number.as_mut_ptr(), PLOT_NUMBER_FORMAT, v);
        let text = number.as_ptr() as usize;
        let (from, length) = (get(p::X_FROM), plot_abs(x1 - x0));
        if pad == 1 {
            let to = get(p::X_TO) + 1;
            let left = plot_scale(v, from, to, length, x0, x1);
            let right = plot_scale(v + 1, from, to, length, x0, x1);
            plot_label(left, y1, right, y1 + 0x14, 0xc, text);
        } else {
            let centre = plot_scale(v, from, get(p::X_TO), length, x0, x1);
            plot_label(centre - 10, y1, centre + 10, y1 + 0x14, 0xc, text); // tel38_8: an x number
        }
        v += step;
    }
    // the y ticks
    let range = get(p::Y_TO) - get(p::Y_FROM);
    let span = plot_abs(range);
    let mut step = 1;
    if span > 1 {
        loop {
            let q = if pad == 1 {
                (y0 - y1).wrapping_mul(step).wrapping_div(plot_abs(range + 1))
            } else {
                (y0 - y1).wrapping_mul(step).wrapping_div(span)
            };
            if plot_abs(q) > 10 {
                break;
            }
            step += 1;
            if step >= span {
                break;
            }
        }
    }
    let mut v = get(p::Y_FROM).min(get(p::Y_TO));
    while v <= get(p::Y_FROM).max(get(p::Y_TO)) {
        format(number.as_mut_ptr(), PLOT_NUMBER_FORMAT, v);
        let text = number.as_ptr() as usize;
        let length = plot_abs(y1 - y0);
        if pad == 1 {
            let (top, bottom);
            let (yf, yt) = (get(p::Y_FROM), get(p::Y_TO));
            if yt > yf {
                set(p::Y_TO, yt + 1);
                top = plot_scale(v, yf, yt + 1, length, y0, y1);
                bottom = plot_scale(v + 1, yf, yt + 1, length, y0, y1);
                set(p::Y_TO, yt);
            } else {
                set(p::Y_FROM, yf + 1);
                top = plot_scale(v, yf + 1, yt, length, y0, y1);
                bottom = plot_scale(v + 1, yf + 1, yt, length, y0, y1);
                set(p::Y_FROM, yf);
            }
            plot_label(x0 - 0x14, top, x0, bottom, 0xc, text);
        } else {
            let centre = plot_scale(v, get(p::Y_FROM), get(p::Y_TO), length, y0, y1);
            plot_label(x0 - 0x14, centre - 10, x0, centre + 10, 0xc, text);
        }
        v += plot_abs(step);
    }
}

/// The display-list writes of a plot drawing: the gui builder's (`gui_build_regions` of tel38_3, one area), the plot
/// itself (its range moves while drawn) and the next `items` item slots and free-order slots (clamped to the tables),
/// with the network packet up to 0x4000 bytes.
unsafe fn plot_regions(plot: usize, items: usize) -> Vec<(usize, usize)> {
    use display_list as l;
    let mut r = gui_build_regions(1, 0);
    r.push((plot, plot_fields::SIZE));
    let (base, pos, limit) = (read_usize(0xae2908), read_usize(0xae290c), read_usize(0xae2910));
    if base != 0 && pos < limit {
        r.push((base + pos, (limit - pos).min(0x4000)));
    }
    let d = screens_current_display(SCREEN_MANAGER);
    if d != 0 {
        let ic = read_i16(d + l::ITEM_COUNT).clamp(0, 0x4af) as usize;
        r.push((display_item_at(d, ic as i16), items.min(0x4af - ic) * l::ITEM_SIZE));
        let oc = read_i16(d + l::ITEM_ORDER_COUNT).clamp(0, 0x4b0) as usize;
        r.push((d + l::ITEM_ORDER + oc * 2, items.min(0x4b0 - oc) * 2));
    }
    r
}

/// How many items a frame can add at most: 8 sides, 2 titles and a number per value of each range (step 1).
unsafe fn plot_axes_items(plot: usize) -> usize {
    use plot_fields as p;
    let x = plot_abs(read_i32(plot + p::X_TO) - read_i32(plot + p::X_FROM)) as usize;
    let y = plot_abs(read_i32(plot + p::Y_TO) - read_i32(plot + p::Y_FROM)) as usize;
    10 + x + 2 + y + 2
}

/// Comparer for `plot_draw_axes`: side by side over `plot_regions`.
#[allow(clippy::too_many_arguments)]
pub(crate) unsafe extern "thiscall" fn compare_plot_draw_axes(plot: usize, x0: i32, y0: i32, x1: i32, y1: i32, pad: i32, x_title: usize, y_title: usize) {
    let o = original_fn::<unsafe extern "thiscall" fn(usize, i32, i32, i32, i32, i32, usize, usize)>(IDX_PLOT_DRAW_AXES);
    let regions = plot_regions(plot, plot_axes_items(plot));
    let (_, _, equal, mo, mr) = crate::comparison::side_by_side(&regions, || o(plot, x0, y0, x1, y1, pad, x_title, y_title),
        || plot_draw_axes(plot, x0, y0, x1, y1, pad, x_title, y_title));
    SCOREBOARD.record(equal, || format!("plot_draw_axes(({}, {})-({}, {}), pad {}): differences in {:?}", x0, y0, x1, y1, pad, first_differences(&mo, &mr)));
}

/// Rule: draws a line graph in the box (x0, y0)–(x1, y1): the frame and each series as a line through its points.
///
/// The plot area: left = the smaller x + 20, top = the smaller y + 20, right = the larger x, bottom = the larger y −
/// 30; the frame (`Plot::draw_axes` with no padding and the two titles). Each series with points: each point is scaled
/// into the area (`plot_scale`, x over the width from the left, y over the height from the top, an axis turned around
/// when "to" is not above "from"); a line from the previous point to it and a second one a pixel higher, in the
/// series' colour (`plot_line`); the first point of a series is its own previous point (two lines of no length).
/// Original: `Plot::draw_line_graph` (0x7c7340, plot.cpp, thiscall, ret 0x18).
#[allow(clippy::too_many_arguments)]
pub(crate) unsafe extern "thiscall" fn plot_draw_line_graph(plot: usize, x0: i32, y0: i32, x1: i32, y1: i32, x_title: usize, y_title: usize) {
    use plot_fields as p;
    use plot_series as s;
    let (left, right) = (x0.min(x1) + 0x14, x0.max(x1));
    let (top, bottom) = (y0.min(y1) + 0x14, y0.max(y1) - 0x1e);
    let axes: unsafe extern "thiscall" fn(usize, i32, i32, i32, i32, i32, usize, usize) = core::mem::transmute(0x7c7580usize);
    axes(plot, left, top, right, bottom, 0, x_title, y_title);
    let (width, height) = (right - left, bottom - top);
    // simplification: the original's previous point starts as a leftover local; the first point always sets it
    let (mut px, mut py) = (0i32, 0i32);
    let mut k = 0;
    while k < read_i32(plot + p::SERIES_COUNT) {
        let mut j = 0;
        while j < read_i32(plot_series_at(plot, k) + s::COUNT) {
            let point = read_usize(plot_series_at(plot, k) + s::POINTS) + j as usize * 8;
            let x = plot_scale(read_i32(point), read_i32(plot + p::X_FROM), read_i32(plot + p::X_TO), width, left, right);
            let y = plot_scale(read_i32(point + 4), read_i32(plot + p::Y_FROM), read_i32(plot + p::Y_TO), height, top, bottom);
            if j == 0 {
                px = x;
                py = y;
            }
            let colour = read_u16(plot_series_at(plot, k) + s::COLOUR) as u32;
            plot_line(px, py, x, y, colour);
            plot_line(px, py - 1, x, y - 1, colour); // tel38_8: the line a pixel thicker
            px = x;
            py = y;
            j += 1;
        }
        k += 1;
    }
}

/// Comparer for `plot_draw_line_graph`: side by side over `plot_regions` (the frame's items and two a point).
#[allow(clippy::too_many_arguments)]
pub(crate) unsafe extern "thiscall" fn compare_plot_draw_line_graph(plot: usize, x0: i32, y0: i32, x1: i32, y1: i32, x_title: usize, y_title: usize) {
    use plot_series as s;
    let o = original_fn::<unsafe extern "thiscall" fn(usize, i32, i32, i32, i32, usize, usize)>(IDX_PLOT_DRAW_LINE_GRAPH);
    let mut points = 0usize;
    for k in 0..read_i32(plot + plot_fields::SERIES_COUNT).max(0) {
        points += read_i32(plot_series_at(plot, k) + s::COUNT).max(0) as usize;
    }
    let regions = plot_regions(plot, plot_axes_items(plot) + 2 * points);
    let (_, _, equal, mo, mr) = crate::comparison::side_by_side(&regions, || o(plot, x0, y0, x1, y1, x_title, y_title),
        || plot_draw_line_graph(plot, x0, y0, x1, y1, x_title, y_title));
    SCOREBOARD.record(equal, || format!("plot_draw_line_graph(({}, {})-({}, {})): differences in {:?}", x0, y0, x1, y1, first_differences(&mo, &mr)));
}
